D.pilots[2] = { name_FRA = "Luke Skywalker", name_ENG = "Luke Skywalker", id = 1, max_per_squad = 1, faction = "Rebel_Alliance", ship = "T-65 X-wing", shipId = 0, skill = 5, points = 14, charge = {0}, force = 2, ability_FRA = "<div class='text'>Après être devenu le défenseur (avant que les dés ne soient lancés), vous pouvez récupérer 1 <img class='inline-img' src='img/fo.png'> .</div>", ability_ENG = "<div class='text'>After being a defender (before dice are rolled), you may recover 1 <img class='inline-img' src='img/fo.png'>.</div>" }
D.pilots[3] = { name_FRA = "Wedge Antilles", name_ENG = "Wedge Antilles", id = 2, max_per_squad = 1, faction = "Rebel_Alliance", ship = "T-65 X-wing", charge = {0}, force = 0, shipId = 0, skill = 6, points = 14, ability_FRA = "<div class='text'>Tant que vous effectuez une attaque, le défenseur lance 1 dé de défense en moins.</div>", ability_ENG = "<div class='text'>While you perform an attack, the defender rolls 1 less attack die.</div>" }
D.pilots[4] = { name_FRA = "Biggs Darklighter", name_ENG = "Biggs Darklighter", id = 3, max_per_squad = 1, faction = "Rebel_Alliance", ship = "T-65 X-wing", charge = {0}, force = 0, shipId = 0, skill = 3, points = 11, ability_FRA = "<div class='text'>Tant qu’un autre vaisseau allié à portée 0–1 défend, avant l’étape « Neutraliser les résultats », si vous êtes dans l’arc de l’attaque, vous pouvez subir 1 dégât <img class='inline-img' src='img/hit.png'> ou <img class='inline-img' src='img/crit.png'> pour annuler 1 dégât correspondant.</div>", ability_ENG = "<div class='text'>While another friendly ship at range 0-1 defends, before the Neutralize results step, if you are in the attack arc, you may suffer 1 <img class='inline-img' src='img/hit.png'> or <img class='inline-img' src='img/crit.png'> damage to cancel 1 equivalent damage.</div>" }
D.pilots[5] = { name_FRA = "Wes Janson", name_ENG = "Wes Janson", id = 4, max_per_squad = 1, faction = "Rebel_Alliance", ship = "T-65 X-wing", force = 0, shipId = 0, skill = 5, charge = {1, "yellow", "+"}, points = 12, ability_FRA = "<div class='text'>Après avoir effectué une attaque, vous pouvez dépenser 1 <img class='inline-img' src='img/charge.png'> pour assigner au défenseur 1 marqueur de brouillage. Après avoir défendu, vous pouvez dépenser 1 <img class='inline-img' src='img/charge.png'> pour assigner à l'attaquant 1 marqueur de brouillage.</div>", ability_ENG = "<div class='text'>After performing an attack, you may spend 1 <img class='inline-img' src='img/charge.png'> to assign 1 jam token to the defender. After defending, you may spend 1 <img class='inline-img' src='img/charge.png'> to assign 1 jam token to the defender.</div>" }
D.pilots[6] = { name_FRA = "Norra Wexley", name_ENG = "Norra Wexley", id = 5, max_per_squad = 1, faction = "Rebel_Alliance", ship = "BTL-A4 Y-wing", charge = {0}, force = 0, shipId = 1, skill = 5, points = 12, ability_FRA = "<div class='text'>Tant que vous défendez, si un vaisseau ennemi est à portée 0–1, ajoutez 1 résultat <img class='inline-img' src='img/Ev W.png'> à vos résultats de dés.</div>", ability_ENG = "<div class='text'>While defending, if an enemy ship is at range 0-1, add 1 <img class='inline-img' src='img/Ev W.png'> result to your dice results.</div>" }
D.pilots[7] = { name_FRA = "Horton Salm", name_ENG = "Horton Salm", id = 6, max_per_squad = 1, faction = "Rebel_Alliance", ship = "BTL-A4 Y-wing", charge = {0}, force = 0, shipId = 1, skill = 5, points = 9, ability_FRA = "<div class='text'>Tant que vous effectuez une attaque, vous pouvez relancer 1 dé d’attaque pour chaque autre vaisseau allié à portée 0–1 du défenseur.</div>", ability_ENG = "<div class='text'>While you perform an attack, you may reroll 1 attack dice for each other friendly ship at range 0-1 of the defender." }
D.pilots[8] = { name_FRA = "'Dutch' Vander", name_ENG = "'Dutch' Vander", id = 7, max_per_squad = 1, faction = "Rebel_Alliance", ship = "BTL-A4 Y-wing", charge = {0}, force = 0, shipId = 1, skill = 4, points = 11, ability_FRA = "<div class='text'>Après avoir effectué l’action <img class='inline-img' src='img/Lo W.png'>, vous pouvez choisir 1 vaisseau allié à portée 1–3. Ce vaisseau allié peut verrouiller l’objet que vous avez verrouillé, en ignorant les restrictions de portée</div>", ability_ENG = "<div class='text'>After performing a <img class='inline-img' src='img/Lo W.png'> action, you may choose 1 friendly ship at range 1-3. This friendly ship may lock the object you have locked, ignoring range restrictions.</div>" }
D.pilots[9] = { name_FRA = "Evaan Verlaine", name_ENG = "Evaan Verlaine", id = 8, max_per_squad = 1, faction = "Rebel_Alliance", ship = "BTL-A4 Y-wing", charge = {0}, force = 0, shipId = 1, skill = 3, points = 9, ability_FRA = "<div class='text'>Au début de la phase d’engagement, vous pouvez dépenser 1 marqueur de concentration pour choisir un vaisseau allié à portée 0–1. Dans ce cas, ce vaisseau allié lance 1 dé de défense supplémentaire tant qu’il défend, jusqu’à la fin du round.</div>", ability_ENG = "<div class='text'>At the beginning of Engagement Phase, you may spend 1 focus token to choose a friendly ship at range 0-1. If you do, this friendly ship rolls 1 additional defense die while defending until then end of the round.</div>" }
D.pilots[10] = { name_FRA = "Vétéran de l'Escadron Or", name_ENG = "Gold Squadron Veteran", id = 9, faction = "Rebel_Alliance", ship = "BTL-A4 Y-wing", max_per_squad = 8, charge = {0}, force = 0, shipId = 1, skill = 3, points = 8 }
D.pilots[11] = { name_FRA = "Bodhi Rook", name_ENG = "Bodhi Rook", id = 10, max_per_squad = 1, faction = "Rebel_Alliance", ship = "UT-60D U-wing", charge = {0}, force = 0, shipId = 34, skill = 4, points = 11, ability_FRA = "<div class='text'>Les vaisseaux alliés peuvent verrouiller des objets à portée 0–3 de n’importe quel vaisseau allié.</div>", ability_ENG = "<div class='text'>Friendly ships may lock objects at range 0-3 of any friendly ship.</div>" }
D.pilots[12] = { name_FRA = "Cassian Andor", name_ENG = "Cassian Andor", id = 11, max_per_squad = 1, faction = "Rebel_Alliance", ship = "UT-60D U-wing", charge = {0}, force = 0, shipId = 34, skill = 5, points = 13, ability_FRA = "<div class='text'>Au début de la phase d’activation, vous pouvez choisir 1 vaisseau allié à portée 1–3. Dans ce cas, ce vaisseau allié retire 1 marqueur de stress.</div>", ability_ENG = "<div class='text'>At the beginning of Activation Phase, you may choose 1 friendly ship at range 1-3. If you do, this friendly ship removes 1 stress token.</div>" }
D.pilots[13] = { name_FRA = "Heff Tobber", name_ENG = "Heff Tobber", id = 12, max_per_squad = 1, faction = "Rebel_Alliance", ship = "UT-60D U-wing", charge = {0}, force = 0, shipId = 34, skill = 2, points = 12, ability_FRA = "<div class='text'>Après qu’un vaisseau ennemi a exécuté une manœuvre, s’il est à portée 0, vous pouvez effectuer une action.</div>", ability_ENG = "<div class='text'>After an enemy ship executes a maneuver, if it is at range 0, you may perform an action.</div>" }
