D.pilots[15] = { name_FRA = "Jan Ors", name_ENG = "Jan Ors", id = 14, max_per_squad = 1, faction = "Rebel_Alliance", ship = "HWK-290 Light Freighter", charge = {0}, force = 0, shipId = 8, skill = 5, points = 10, ability_FRA = "<div class='text'>Tant qu’un vaisseau allié situé dans votre arc de tir effectue une attaque principale, si vous n’êtes pas stressé, vous pouvez gagner 1 marqueur de stress. Dans ce cas, ce vaisseau peut lancer 1 dé d’attaque supplémentaire.</div>", ability_ENG = "<div class='text'>While a friendly ship in your firing arc performs a primary attack, if you are not stressed, you may receive 1 stress token. If you do, this ship may roll 1 additional attack die.</div>" }
D.pilots[16] = { name_FRA = "Roark Garnet", name_ENG = "Roark Garnet", id = 15, max_per_squad = 1, faction = "Rebel_Alliance", ship = "HWK-290 Light Freighter", charge = {0}, force = 0, shipId = 8, skill = 4, points = 9, ability_FRA = "<div class='text'>Au début de la phase d’engagement, vous pouvez choisir 1 vaisseau situé dans votre arc de tir. Dans ce cas, pendant cette phase, il s’engage à l’initiative 7 au lieu de le faire à sa valeur d’initiative standard.</div>", ability_ENG = "<div class='text'>At the beginning of Engagement phase, you may choose 1 ship in your firing arc. If you do, during this phase, it engages at initiative 7 instead engaging at its original initiative.</div>" }
D.pilots[17] = { name_FRA = "Kyle Katarn", name_ENG = "Kyle Katarn", id = 16, max_per_squad = 1, faction = "Rebel_Alliance", ship = "HWK-290 Light Freighter", charge = {0}, force = 0, shipId = 8, skill = 3, points = 9, ability_FRA = "<div class='text'>Au début de la phase d’engagement, vous pouvez transférer 1 de vos marqueurs de concentration à un vaisseau allié situé dans votre arc de tir.</div>", ability_ENG = "<div class='text'>At the beginning of Engagement Phase, you may transfer 1 of your focus tokens to a friendly ship in your firing arc.</div>" }
D.pilots[18] = { name_FRA = "Palob Godalhi", name_ENG = "Palob Godalhi", id = 17, max_per_squad = 1, faction = "Rebel_Alliance", ship = "HWK-290 Light Freighter", charge = {0}, force = 0, shipId = 8, skill = 3, points = 9, ability_FRA = "<div class='text'>Au début de la phase d’engagement, vous pouvez transférer un marqueur de stress de votre vaisseau vers un vaisseau allié dans votre arc de tir. Lorsque vous retirez un marqueur de stress de votre vaisseau, vous pouvez effectuer une action.</div>", ability_ENG = "<div class='text'>At the beginning of Engagement Phase, you may transfer 1 stress token from you to a friendly ship in your firing arc. When you remove a stress token from you, you may perform an action.</div>" }
D.pilots[19] = { name_FRA = "Jake Farell", name_ENG = "Jake Farell", id = 18, max_per_squad = 1, faction = "Rebel_Alliance", ship = "RZ-1 A-wing", charge = {0}, force = 0, shipId = 2, skill = 4, points = 11, ability_FRA = "<div class='text'>Après avoir effectué une action <img class='inline-img' src='img/Br W.png'> ou <img class='inline-img' src='img/Bo W.png'>, vous pouvez choisir un vaisseau allié à portée 0–1. Ce vaisseau peut effectuer une action <img class='inline-img' src='img/Fo W.png'> .</div>", ability_ENG = "<div class='text'>After performing a <img class='inline-img' src='img/Br W.png'> or <img class='inline-img' src='img/Bo W.png'> action, you may choose a friendly ship at range 0-1. This ship may perform a <img class='inline-img' src='img/Fo W.png'> action.</div>" }
D.pilots[20] = { name_FRA = "Arvel Crynyd", name_ENG = "Arvel Crynyd", id = 19, max_per_squad = 1, faction = "Rebel_Alliance", ship = "RZ-1 A-wing", charge = {0}, force = 0, shipId = 2, skill = 3, points = 9, ability_FRA = "<div class='text'>Vous pouvez effectuer des attaques principales à portée 0. Si vous deviez échouer une action <img class='inline-img' src='img/Bo W.png'> qui vous amènerait à chevaucher un autre vaisseau, résolvez-la comme si vous exécutiez partiellement une manœuvre à la place.</div>", ability_ENG = "<div class='text'>You may perform primary attacks at range 0. If you would fail a <img class='inline-img' src='img/Bo W.png'> action because you would overlap an other ship, perform it as you would execute partially a maneuver instead.</div>" }
