D.pilots[54] = { name_FRA = "Lyttan Dree", name_ENG = "Lyttan Dree", id = 53, faction = "Imperial_Academy", skill = 3, max_per_squad = 1, ship = "TIE/rb Heavy", charge = {0}, force = 0, shipId = 69, points = 10, ability_FRA = "<div class='text'>Tant qu’un vaisseau allié à portée 0–2 effectue une attaque, si vous êtes dans le <img class='inline-img' src='img/Larc.png'> ou <img class='inline-img' src='img/Rarc.png'> du défenseur, l’attaquant peut relancer 1 dé d’attaque.</div>", ability_ENG = "<div class='text'>While a friendly ship at range 0-2 performs an attack, if you are in the <img class='inline-img' src='img/Larc.png'> or <img class='inline-img' src='img/Rarc.png'> of the defender, the attacker may reroll 1 attack die." }
D.pilots[55] = { name_FRA = "Rampage", name_ENG = "Rampage", id = 54, faction = "Imperial_Academy", skill = 4, max_per_squad = 1, ship = "TIE/rb Heavy", charge = {0}, force = 0, shipId = 69, points = 11, ability_FRA = "<div class='text'>Après avoir exécuté une manœuvre à vitesse 3–4, vous pouvez choisir un vaisseau situé dans votre <img class='inline-img' src='img/Tarc.png'> à portée 0–1. Dans ce cas, ce vaisseau gagne 1 marqueur de contrainte, ou 2 marqueurs de contrainte si vous êtes endommagé.</div>", ability_ENG = "<div class='text'>After you execute a speed 3-4 maneuver, you may choose a ship in your <img class='inline-img' src='img/Tarc.png'> at range 0-1. If you do, this ship receives 1 strain token, or 2 strain tokens if you are damaged." }
D.pilots[56] = { name_FRA = "Leader d'Escadron Ubbel", name_ENG = "Flight Leader Ubbel", id = 55, max_per_squad = 1, faction = "Imperial_Academy", ship = "TIE/rb Heavy", charge = {0}, force = 0, shipId = 69, skill = 5, points = 12, ability_FRA = "<div class='text'>Après qu'un vaisseau allié à portée 0-2 a défendu, si une carte de dégât lui a été attribuée, vous pouvez effectuer une attaque bonus contre l'attaquant.</div>", ability_ENG = "<div class='text'>After a friendly ship at range 0-2 defends, if a damage card was dealt to him, you may perform a bonus attack against the attacker." }
D.pilots[57] = { name_FRA = "Fenn Rau", name_ENG = "Fenn Rau", id = 56, max_per_squad = 1, faction = "Mandalorian_Clans", ship = "Fang Fighter", charge = {0}, force = 0, shipId = 31, skill = 6, points = 15, ability_FRA = "<div class='text'>Lorsque vous attaquez ou défendez, si l’attaque est à portée 1, vous pouvez lancer 1 dé supplémentaire.</div>", ability_ENG = "<div class='text'>While you attack or defend, if the attack is at range 1, you may roll 1 additional die." }
