D.pilots[129] = { name_FRA = "Nashtah Pup", name_ENG = "Nashtah Pup", id = 128, max_per_squad = 1, faction = "Bounty_Hunters_Guild", ship = "Z-95-AF4 Headhunter", charge = {0}, force = 0, shipId = 12, skill = 0, points = 1, ability_FRA = "<div class='text'>Ne peut être joué que si un YV666 avec le titre Hound’s Tooth est dans votre escadron. Vous commencez la partie en réserve, arrimé au Hound's Tooth. Vous ne pouvez vous déployez que lorsque le Hound's Tooth est détruit. Vous pouvez copier :<br>- Le texte de sa capacité de pilote ou<br>-  Le texte de l’une de ses améliorations <img class='inline-img' src='img/Crew.png'> </div>", ability_ENG = "<div class='text'>Cannot be played if there's no YV666 with the Hound's Tooth title in your squad. You begin the game in reserve, docked to the Hound's Tooth. You may deploy only when the Hound's Tooth is destroyed. You may copy :<br>- Its Pilot ability or<br>- The text of one of its <img class='inline-img' src='img/Crew.png'> upgrade</div>" }
D.pilots[130] = { name_FRA = "Bossk", name_ENG = "Bossk", id = 129, faction = "Bounty_Hunters_Guild", max_per_squad = 1, skill = 4, ship = "Z-95-AF4 Headhunter", charge = {0}, force = 0, shipId = 12, points = 7, ability_FRA = "<div class='text'>Tant que vous effectuez une attaque principale, après l’étape « Neutraliser les résultats », vous pouvez dépenser 1 résultat <img class='inline-img' src='img/crit.png'> pour ajouter 2 résultats <img class='inline-img' src='img/hit.png'> .</div>", ability_ENG = "<div class='text'>While you perform a primary attack, after the 'Neutralize Results' stem, you may spend 1 <img class='inline-img' src='img/crit.png'> result to add 2 <img class='inline-img' src='img/hit.png'> results.</div>" }
D.pilots[131] = { name_FRA = "Cad Bane", name_ENG = "Cad Bane", id = 130, max_per_squad = 1, faction = "Bounty_Hunters_Guild", ship = "Rogue-class Starfighter", force = 0, shipId = 80, skill = 4, charge = {2, "yellow", "+"}, points = 12, ability_FRA = "<div class='text'>Après avoir effectué une attaque qui a touché, vous pouvez dépenser 2 <img class='inline-img' src='img/charge.png'> pour transférer 1 de vos jetons rouges non-verrouillage ou orange au défenseur.</div>", ability_ENG = "<div class='text'>After you perform an attack that hits, you may spend 2 <img class='inline-img' src='img/charge.png'> to transfer 1 of your non lock red tokens or orange tokens to the defender.</div>" }
D.pilots[132] = { name_FRA = "Nom Lumb", name_ENG = "Nom Lumb", id = 131, max_per_squad = 1, faction = "Bounty_Hunters_Guild", ship = "Rogue-class Starfighter", charge = {0}, force = 0, shipId = 80, skill = 1, points = 10, ability_FRA = "<div class='text'>Au début de la phase d’engagement, vous pouvez choisir 1 vaisseau ennemi dans votre <img class='inline-img' src='img/attackF.png'>. Dans ce cas, considérez votre initiative comme étant égale à celle de ce vaisseau jusqu’à la fin du round.</div>", ability_ENG = "<div class='text'>At the beginning of Engagement Phase, you may choose 1 enemy ship in your <img class='inline-img' src='img/attackF.png'>. If you do, consider your initiative as equal to this ship's initiative until the end of the round.</div>" }
D.pilots[133] = { name_FRA = "Durge", name_ENG = "Durge", id = 132, max_per_squad = 1, faction = "Bounty_Hunters_Guild", ship = "Rogue-class Starfighter", charge = {0}, force = 0, shipId = 80, skill = 5, points = 11, ability_FRA = "<div class='text'>Tant que vous défendez, après l'étape Neutraliser les Résultats, s'il y a plus de résultats <img class='inline-img' src='img/hit.png'>/<img class='inline-img' src='img/crit.png'> que vos boucliers actifs, vous pouvez changer 1 résultat <img class='inline-img' src='img/hit.png'> en 1 résultat <img class='inline-img' src='img/crit.png'> et annuler 1 résultat <img class='inline-img' src='img/hit.png'>.</div>", ability_ENG = "<div class='text'>While you defend, after the 'Neutralize Results' step, if there are more <img class='inline-img' src='img/hit.png'>/<img class='inline-img' src='img/crit.png'> results than your active shields, you may change 1 <img class='inline-img' src='img/hit.png'> result into 1 <img class='inline-img' src='img/crit.png'> result to cancel 1 <img class='inline-img' src='img/hit.png'> result</div>" }
