D.pilots[164] = { name_FRA = "General Grievous", name_ENG = "General Grievous", id = 163, max_per_squad = 1, faction = "Separatist_Government", ship = "Belbullab-22 Starfighter", charge = {0}, force = 0, shipId = 57, skill = 4, points = 12, ability_FRA = "<div class='text'>Lorsque vous effectuez une attaque principale, si vous n'êtes pas dans l'arc de tir du défenseur, vous pouvez relancer jusqu'à 2 dés d'attaque.</div>", ability_ENG = "<div class='text'>While you perform a primary attack, if you are not in the defender's firing arc, you may reroll up to 2 attack dice.</div>" }
D.pilots[165] = { name_FRA = "Capitaine Sear", name_ENG = "Captain Sear", id = 164, max_per_squad = 1, faction = "Separatist_Government", ship = "Belbullab-22 Starfighter", charge = {0}, force = 0, shipId = 57, skill = 2, points = 10, ability_FRA = "<div class='text'>Lorsqu'un vaisseau allié à portée 0-3 effectue une attaque principale, si le défenseur est dans son <img class='inline-img' src='img/bulls.png'>, avant l'étape 'Neutraliser les résultats', le vaisseau allié peut dépenser 1 jeton calcul pour annuler un résultat <img class='inline-img' src='img/Ev W.png'>.</div>", ability_ENG = "<div class='text'>While a friendly ship at range 0-3 performs a primary attack, if the defender is in its <img class='inline-img' src='img/bulls.png'>, before the Neutralize Results step, the friendly ship may spend 1 calculate token to cancel 1 <img class='inline-img' src='img/Ev W.png'> result.</div>" }
D.pilots[166] = { name_FRA = "Wat Tambor", name_ENG = "Wat Tambor", id = 165, max_per_squad = 1, faction = "Separatist_Government", ship = "Belbullab-22 Starfighter", charge = {0}, force = 0, shipId = 57, skill = 3, points = 10, ability_FRA = "<div class='text'>Lorsque vous effectuez une attaque principale, vous pouvez relancer 1 dé pour chaque vaisseau allié calculateur à portée 1 du défenseur.</div>", ability_ENG = "<div class='text'>While you perform a primary attack or defend, you may reroll 1 die for each calculating friendly ship at range 1 of the defender.</div>" }
D.pilots[167] = { name_FRA = "General Kleeve", name_ENG = "General Kleeve", id = 166, max_per_squad = 1, faction = "Separatist_Government", ship = "Belbullab-22 Starfighter", charge = {0}, force = 0, shipId = 57, skill = 3, points = 11, ability_FRA = "<div class='text'>Lorsqu'un vaisseau à portée 0-3 effectue une attaque principale, s'il n'est pas dans l'arc de tir du défenseur et qu'il est calculateur, il peut relancer 1 dé d'attaque.</div>", ability_ENG = "<div class='text'>While a friendly ship at range 0-3 performs a primary attack, if it is not in the defender's firing arc and if it is calculating, it may reroll 1 attack die.</div>" }
