D.pilots[169] = { name_FRA = "AP5", name_ENG = "AP5", id = 168, max_per_squad = 1, faction = "Trade_Federation", ship = "Sheathipede-Class Shuttle", charge = {0}, force = 0, shipId = 41, skill = 1, points = 8, ability_FRA = "<div class='text'>Lorsque vous coordonnez, is vous choisissez un vaisseau avec exactement 1 jeton stress, il peut effectuer une action.</div>", ability_ENG = "<div class='text'>While you coordinate, if you chose a ship with exactly 1 stress token, it can perform actions.</div>" }
D.pilots[170] = { name_FRA = "Rune Haako", name_ENG = "Rune Haako", id = 169, max_per_squad = 1, faction = "Trade_Federation", ship = "Sheathipede-Class Shuttle", charge = {0}, force = 0, shipId = 41, skill = 3, points = 9, ability_FRA = "<div class='text'>Lorsque vous effectuez une attaque <img class='inline-img' src='img/attackB.png'>, avant l'étape 'Neutralisez les résultats', vous pouvez recevoir un jeton stress pour annuler 1 résultat <img class='inline-img' src='img/Ev W.png'>.</div>", ability_ENG = "<div class='text'>While you perform a <img class='inline-img' src='img/attackB.png'> attack, before the Neutralize results step, you may receive a stress token to cancel 1 <img class='inline-img' src='img/Ev W.png'> result.</div>" }
D.pilots[171] = { name_FRA = "Nute Gunray", name_ENG = "Nute Gunray", id = 170, max_per_squad = 1, faction = "Trade_Federation", ship = "Sheathipede-Class Shuttle", charge = {0}, force = 0, shipId = 41, skill = 2, points = 9, ability_FRA = "<div class='text'>Lorsque vous êtes détruit, vous devez déployer la navette de secours de Nute Gunray depuis votre vaisseau (Coque 2 Agilité 2). Pendant la phase Système, déplacez vous vers l'avant avec un gabarit de vitesse 1, ou le gabarit 2 <img class='inline-img' src='img/manSt2.png'>. Vous pouvez être placé sous un vaisseau si vous les chevauchez. Lorsque vous défendez, vous pouvez modifier vos résultats <img class='inline-img' src='img/Fo W.png'> en <img class='inline-img' src='img/Ev W.png'>. Si vous deviez fuir du tapis de jeu, votre adversaire perd 2 PO.", ability_ENG = "<div class='text'>When you would be destroyed, you must deploy Nute Gunray's escape pod from your ship (2 Hull 3 agility). During System phase, you move forward with any 1 speed template, or the 2 straight template. You may be placed under any ship if you overlap them. When you defend, you may change your <img class='inline-img' src='img/Fo W.png'> results into <img class='inline-img' src='img/Ev W.png'> results. If you would flee from the Battlefield, your opponent lose 2 PO.</div>" }
D.pilots[172] = { name_FRA = "Riff Tamson", name_ENG = "Riff Tamson", id = 171, max_per_squad = 1, faction = "Trade_Federation", ship = "Sheathipede-Class Shuttle", charge = {0}, force = 0, shipId = 41, skill = 2, points = 9, ability_FRA = "<div class='text'>Les améliorations que vous équipez perdent la restriction 'Solitaire'.</div>", ability_ENG = "<div class='text'>The upgrades you equip lose the 'Solitary' restriction.</div>" }
