D.pilots[174] = { name_FRA = "Oppresseur d'Onderon", name_ENG = "Onderon Oppressor", id = 173, max_per_squad = 3, faction = "Trade_Federation", ship = "HMP Droid Gunship", charge = {0}, force = 0, shipId = 67, skill = 3, points = 10, ability_FRA = "<div class='text'>Après avoir effectué un tonneau ou un dérapage, si vous êtes stressé, recevez un jeton calcul.</div>", ability_ENG = "<div class='text'>After you barrel roll or sideslip, if you are stressed, gain 1 calculate token.</div>" }
D.pilots[175] = { name_FRA = "Prototype Géonosien", name_ENG = "Geonosian Prototype", id = 174, max_per_squad = 2, faction = "Trade_Federation", ship = "HMP Droid Gunship", charge = {1, "yellow", "0"}, force = 0, shipId = 67, skill = 2, points = 10, ability_FRA = "<div class='text'>Pendant la phase système, vous pouvez dépenser ou récupérer votre charge.<br><img class='inline-img' src='img/charge.png'> active : Lorsque vous vous engagez, s'il y a un vaisseau avec un jeton tracté dans votre arc de tir, recevez 1 jeton calcul.<br><img class='inline-img' src='img/charge.png'> inactive : Après avoir dérapé, si vous vous êtes déplacé à travers un vaisseau, il gagne un jeton tracté.</div>", ability_ENG = "<div class='text'>During System Phase, you may spend or recover your charge.<br><img class='inline-img' src='img/charge.png'> active : When you engage, if there is a ship with a tractor token in your firing arc, gain 1 calculate token.<br><img class='inline-img' src='img/charge.png'> inactive : After you sideslip, if you moved through a ship, it gains 1 tractor token.</div>" }
D.pilots[176] = { name_FRA = "DGS-286", name_ENG = "DGS-286", id = 175, max_per_squad = 1, faction = "Trade_Federation", ship = "HMP Droid Gunship", charge = {0}, force = 0, shipId = 67, skill = 3, points = 11, ability_FRA = "<div class='text'>Avant de vous engager, vous pouvez choisir un autre vaisseau allié à portée 0-1. Transférez un 1 jeton calcul de ce vaisseau vers vous.</div>", ability_ENG = "<div class='text'>Before you engage, you may choose another friendly ship at range 0-1. That ship transfers 1 calculate token to you.</div>" }
D.pilots[177] = { name_FRA = "DGS-047", name_ENG = "DGS-047", id = 176, max_per_squad = 1, faction = "Trade_Federation", ship = "HMP Droid Gunship", charge = {0}, force = 0, shipId = 67, skill = 1, points = 10, ability_FRA = "<div class='text'>Après avoir attaqué, si le défenseur se trouve dans votre <img class='inline-img' src='img/attackF.png'>, vous pouvez acquisitionner ce vaisseau. Puis, si le défenseur est dans votre <img class='inline-img' src='img/bulls.png'>, il reçoit un jeton contrainte.</div>", ability_ENG = "<div class='text'>After you perform an attack, if the defender is in your <img class='inline-img' src='img/attackF.png'> , you may acquire a lock on it. Then, if the defender is in your <img class='inline-img' src='img/bulls.png'>, it gains 1 strain token.</div>" }
