D.pilots[179] = { name_FRA = "Prototype Phlac Arphocc", name_ENG = "Phlac Arphocc Prototype", id = 178, max_per_squad = 2, faction = "Trade_Federation", ship = "Droid Tri-fighter", charge = {1, "yellow", "0"}, force = 0, shipId = 70, skill = 5, points = 11, ability_FRA = "<div class='text'>Pendant la phase système, vous pouvez dépenser ou récupérer votre charge.<br><img class='inline-img' src='img/charge.png'> active : Pendant la phase Système, vous pouvez regarder le cadran d'un vaisseau que vous avez acquisitionné.<br><img class='inline-img' src='img/charge.png'> inactive : Au début de la phase d'Engagement, s'il y a un vaisseau dans votre <img class='inline-img' src='img/bulls.png'>, recevez 1 jeton calcul.</div>", ability_ENG = "<div class='text'>During System Phase, you may spend or recover your charge.<br><img class='inline-img' src='img/charge.png'> active : During System Phase, you may look at the dial of a ship you have a lock on.<br><img class='inline-img' src='img/charge.png'> inactive : At the beginning of engagement phase, if there's an enemy ship in your <img class='inline-img' src='img/bulls.png'>, gain 1 calculate token.</div>" }
