D.pilots[186] = { name_FRA = "Prototype Haor Chall", name_ENG = "Haor Chall Prototype", id = 185, max_per_squad = 2, faction = "Trade_Federation", ship = "Vulture-class Droid Fighter", charge = {1, "yellow", "0"}, force = 0, shipId = 56, skill = 1, points = 6, ability_FRA = "<div class='text'>Pendant la phase système, vous pouvez dépenser ou récupérer votre charge.<br><img class='inline-img' src='img/charge.png'> active : Après qu'un vaisseau ennemi dans votre <img class='inline-img' src='img/bulls.png'> à portée 0-2 déclare un autre vaisseau allié comme cible, vous pouvez effectuer une action <img class='inline-img' src='img/Cc W.png'> ou <img class='inline-img' src='img/Lo W.png'>.<br><img class='inline-img' src='img/charge.png'> inactive : Après qu'un vaisseau ennemi se déplace, s'il se retrouve dans votre <img class='inline-img' src='img/bulls.png'>, vous pouvez effectuer une attaque bonus principale.</div>", ability_ENG = "<div class='text'>During system Phase, you may spend or recover your charge.<br><img class='inline-img' src='img/charge.png'> active : After an enemy ship in your <img class='inline-img' src='img/bulls.png'> at range 0-2 declares another friendly ship as the defender, you may perform a <img class='inline-img' src='img/Cc W.png'> or <img class='inline-img' src='img/Lo W.png'> action.<br><img class='inline-img' src='img/charge.png'> inactive : After an enemy ship moves, if it is in your <img class='inline-img' src='img/bulls.png'>, you may perform a bonus primary attack.</div>" }
