D.pilots[188] = { name_FRA = "Lin Gaava", name_ENG = "Lin Gaava", id = 187, max_per_squad = 1, faction = "First_Order_Vanguard", ship = "TIE/fo Fighter", charge = {0}, force = 0, shipId = 46, skill = 3, points = 8, ability_FRA = "<div class='text'>Mise en Place : Après avoir placé les forces, assignez la condition 'Primed for Speed' à vous même et 2 autres vaisseaux TIE/fo ou TIE/fs alliés qui n'ont pas d'amélioration <img class='inline-img' src='img/Modification.png'> équipée.</div>", ability_ENG = "<div class='text'>Setup: After placing forces, assign the Primed for Speed condition to yourself and up to 2 other friendly TIE/fo or TIE/sf Fighters that have no equipped <img class='inline-img' src='img/Modification.png'> upgrades.</div>" }
