D.pilots[190] = { name_FRA = "Lieutenant Galek", name_ENG = "Lieutenant Galek", id = 189, max_per_squad = 1, faction = "First_Order_Vanguard", ship = "TIE/fo Fighter", charge = {0}, force = 0, shipId = 46, skill = 5, points = 9, ability_FRA = "<div class='text'>Après qu'un autre vaisseau allié à portée 0-2 a été détruit, vous pouvez effectuer une action <img class='inline-img' src='img/Co W.png'>, même stressé. Lorsque vous coordonnez, le vaisseau que vous choississez peut effectuer uniquement une action qui se trouve aussi sur votre barre d'action.</div>", ability_ENG = "<div class='text'>After another friendly ship at range 0-2 is destroyed, you may perform a <img class='inline-img' src='img/Co W.png'> action, even while stressed. While you coordinate, the ship you choose can perform an action only if that action is also on your action bar.</div>" }
