D.pilots[239] = { name_FRA = "Zori Bliss", name_ENG = "Zori Bliss", id = 238, max_per_squad = 1, faction = "Heroes_of_the_Resistance", ship = "BTA-NR2 Y-wing", force = 0, shipId = 74, skill = 5, points = 11, charge = {1, "yellow", "+"}, ability_FRA = "<div class='text'>Après qu'un vaisseau à portée 1 effectue une action pendant son étape 'Effectuer une action', si cette action est aussi sur votre barre d'action, vous pouvez dépenser 1 <img class='inline-img' src='img/charge.png'> pour effectuer cette action, en la considérant comme rouge.</div>", ability_ENG = "<div class='text'>After a ship at range 1 performs an action during its Perform Action step, if that action is on your action bar, you may spend 1 <img class='inline-img' src='img/charge.png'> to perform that action, treating it as red.</div>" }
D.pilots[240] = { name_FRA = "Corus Kapellim", name_ENG = "Corus Kapellim", id = 239, max_per_squad = 1, faction = "Heroes_of_the_Resistance", ship = "BTA-NR2 Y-wing", charge = {0}, force = 0, shipId = 74, skill = 1, points = 9, ability_FRA = "<div class='text'>Avant de vous engager, vous pouvez choisir un vaisseau dans votre arc de tir à portée 0-1. Dans ce cas, transférez 1 jeton vert de ce vaisseau vers votre vaisseau.</div>", ability_ENG = "<div class='text'>Before you engage, you may choose 1 ship in your firing arc at range 0-1. If you do, transfer 1 green token from that ship to yourself.</div>" }
D.pilots[241] = { name_FRA = "Wilsa Teshlo", name_ENG = "Wilsa Teshlo", id = 240, max_per_squad = 1, faction = "Heroes_of_the_Resistance", ship = "BTA-NR2 Y-wing", charge = {0}, force = 0, shipId = 74, skill = 3, points = 9, ability_FRA = "<div class='text'>Après avoir effectué une attaque principale ou une attaque <img class='inline-img' src='img/Tarc.png'>, vous pouvez relancer 1 dé d'attaque pour chaque engin allié ou vaisseau allié calculateur dans l'arc d'attaque.</div>", ability_ENG = "<div class='text'>While you perform a primary or <img class='inline-img' src='img/Tarc.png'> attack, you may reroll 1 attack die for each friendly device or calculating friendly ship in the attack arc.</div>" }
D.pilots[242] = { name_FRA = "Tesa Nasz", name_ENG = "Tesa Nasz", id = 241, max_per_squad = 1, faction = "Heroes_of_the_Resistance", ship = "BTA-NR2 Y-wing", charge = {0}, force = 0, shipId = 74, skill = 4, points = 11, ability_FRA = "<div class='text'>Lorsqu'un vaisseau allié à portée 0-2 attaque, si le défenseur a un vaisseau allié (à vous) dans son <img class='inline-img' src='img/Larc.png'> ET son <img class='inline-img' src='img/Rarc.png'>, l'attaquant peut relancer 1 dé d'attaque.</div>", ability_ENG = "<div class='text'>While a friendly ship at range 0-2 performs an attack, if the defender has a ship friendly to the attacker in its <img class='inline-img' src='img/Larc.png'> AND <img class='inline-img' src='img/Rarc.png'>, the attacker may reroll 1 attack die.</div>" }
