D.pilots[244] = { name_FRA = "Vice Amiral Chiraneau", name_ENG = "Rear Admiral Chiraneau", id = 243, max_per_squad = 1, faction = "Imperial_Elite_Squadrons", ship = "VT-49 Decimator", charge = {0}, force = 0, shipId = 17, skill = 5, points = 19, ability_FRA = "<div class='text'>Lorsque vous attaquez, si vous êtes renforcés et que le défenseur est dans le <img class='inline-img' src='img/F180.png'> ou <img class='inline-img' src='img/B180.png'> correspondant à votre jeton renforcement, vous pouvez changez un de vos résultats <img class='inline-img' src='img/Fo W.png'> en résultat <img class='inline-img' src='img/crit.png'>.</div>", ability_ENG = "<div class='text'>While you perform an attack, if you are reinforced and the defender is in the <img class='inline-img' src='img/F180.png'> or <img class='inline-img' src='img/B180.png'> matching your reinforce token, you may change 1 of your <img class='inline-img' src='img/Fo W.png'> results to a <img class='inline-img' src='img/crit.png'> result.</div>" }
D.pilots[245] = { name_FRA = "Capitaine Oicunn", name_ENG = "Captain Oicunn", id = 244, max_per_squad = 1, faction = "Imperial_Elite_Squadrons", ship = "VT-49 Decimator", charge = {0}, force = 0, shipId = 17, skill = 3, points = 17, ability_FRA = "<div class='text'>Vous pouvez attaquer à portée 0. Considérez vos attaques à portée 0 comme des attaques à portée 1.</div>", ability_ENG = "<div class='text'>You may attack at range 0. While you perform an attack at attack range 0, treat it as an attack at attack range 1.</div>" }
