D.pilots[271] = { name_FRA = "Luminara Unduli", name_ENG = "Luminara Unduli", id = 270, max_per_squad = 1, faction = "Jedi_Order", ship = "Delta-7b Aethersprite", charge = {0}, force = 2, shipId = 54, skill = 4, points = 13, ability_FRA = "<div class='text'>Lorsqu'un vaisseau allié à portée 0-2 défend, s'il ne se trouve pas dans le <img class='inline-img' src='img/bulls.png'> de l'attaquant, vous pouvez dépenser 1 <img class='inline-img' src='img/fo.png'>. Dans ce cas, dégradez 1 dé d'attaque.</div>", ability_ENG = "<div class='text'>While a friendly ship at range 0-2 defends, if it is not in the attacker's <img class='inline-img' src='img/bulls.png'>, you may spend 1 <img class='inline-img' src='img/fo.png'>. If you do, downgrade an attack die</div>" }
D.pilots[272] = { name_FRA = "Bariss Offee", name_ENG = "Barriss Offee", id = 271, max_per_squad = 1, faction = "Jedi_Order", ship = "Delta-7b Aethersprite", charge = {0}, force = 1, shipId = 54, skill = 3, points = 12, ability_FRA = "<div class='text'>Lorsqu'un vaisseau allié à portée 0-2 effectue une attaque, si le défenseur se trouve dans son <img class='inline-img' src='img/bulls.png'>, vous pouvez dépenser 1 <img class='inline-img' src='img/fo.png'>. Dans ce cas, améliorez 1 dé d'attaque.</div>", ability_ENG = "<div class='text'>While a friendly ship at range 0-2 performs an attack, if the defender is in its <img class='inline-img' src='img/bulls.png'>, you may spend 1 <img class='inline-img' src='img/fo.png'>. If you do, upgrade an attack die.</div>" }
D.pilots[273] = { name_FRA = "Adi Gallia", name_ENG = "Adi Gallia", id = 272, max_per_squad = 1, faction = "Jedi_Order", ship = "Delta-7b Aethersprite", charge = {0}, force = 2, shipId = 54, skill = 5, points = 14, ability_FRA = "<div class='text'>Lorsque vous attaquez à portée 1, vous pouvez dépenser 1 <img class='inline-img' src='img/fo.png'>. Dans ce cas, l'attaquant n'applique pas le bonus de portée.<br>Lorsque vous effectuez une attaque contre un vaisseau à portée 3, vous pouvez dépenser 1 <img class='inline-img' src='img/fo.png'>. Dans ce cas, le défenseur n'applique pas le bonus de portée.</div>", ability_ENG = "<div class='text'>While you defend at attack range 1, you may spend 1 <img class='inline-img' src='img/fo.png'>. If you do, the attacker cannot apply the range bonus.<br>While you perform an attack against a defender at attack range 3, you may spend 1 <img class='inline-img' src='img/fo.png'>, the defender cannot apply the range bonus.</div>" }
D.pilots[274] = { name_FRA = "Yoda", name_ENG = "Yoda", id = 273, max_per_squad = 1, faction = "Jedi_Order", ship = "Eta-2 Actis", charge = {0}, force = 3, shipId = 72, skill = 3, points = 10, ability_FRA = "<div class='text'>Après qu'un vaisseau allié à portée 0-3 a dépensé au moins 1 <img class='inline-img' src='img/fo.png'>, vous pouvez dépenser 1 <img class='inline-img' src='img/fo.png'>. Dans ce cas, ce vaisseau récupère 1 <img class='inline-img' src='img/fo.png'>.</div>", ability_ENG = "<div class='text'>After another friendly ship at range 0-3 spends 1 or more <img class='inline-img' src='img/fo.png'>, you may spend 1 <img class='inline-img' src='img/fo.png'>. If you do, that ship recovers 1 <img class='inline-img' src='img/fo.png'>.</div>" }
D.pilots[275] = { name_FRA = "Aayla Secura", name_ENG = "Aayla Secura", id = 274, max_per_squad = 1, faction = "Jedi_Order", ship = "Eta-2 Actis", charge = {0}, force = 2, shipId = 72, skill = 5, points = 11, ability_FRA = "<div class='text'>Lorsqu'un vaisseau ennemi dans votre <img class='inline-img' src='img/attackF.png'> à portée 0-1 effectue une attaque, le défenseur peut modifier 1 résultat vierge en résultat <img class='inline-img' src='img/Fo W.png'>.</div>", ability_ENG = "<div class='text'>While an enemy ship in your <img class='inline-img' src='img/attackF.png'> at range 0-1 performs an attack, the defender may change 1 blank result to a <img class='inline-img' src='img/Fo W.png'> result.</div>" }
D.pilots[276] = { name_FRA = "Shaak Ti", name_ENG = "Shaak Ti", id = 275, max_per_squad = 1, faction = "Jedi_Order", ship = "Eta-2 Actis", charge = {0}, force = 2, shipId = 72, skill = 4, points = 12, ability_FRA = "<div class='text'>Au début de la phase de fin, vous pouvez dépenser 1 ou plusieurs <img class='inline-img' src='img/fo.png'> pour choisir autant de vaisseaux alliés à portée 0-2. Dans ce cas, chaque vaisseau choisi ne retire pas 1 jeton vert pendant la phase de fin.</div>", ability_ENG = "<div class='text'>At the start of the End Phase, you may spend any number of <img class='inline-img' src='img/fo.png'> to choose that many friendly ships at range 0-2. Each chosen ship does not remove 1 focus or evade token during this End Phase.</div>" }
D.pilots[277] = { name_FRA = "Kit Fisto", name_ENG = "Kit Fisto", id = 276, max_per_squad = 1, faction = "Jedi_Order", ship = "Eta-2 Actis", charge = {0}, force = 2, shipId = 72, skill = 4, points = 10, ability_FRA = "<div class='text'>Lorsqu'un autre vaisseau allié à portée 0-3 défend, si l'attaquant est dans son <img class='inline-img' src='img/bulls.png'>, vous pouvez dépenser 1 <img class='inline-img' src='img/fo.png'> pour changer un résultat vierge du défenseur en résultat <img class='inline-img' src='img/Fo W.png'>.</div>", ability_ENG = "<div class='text'>While another friendly ship at range 0-3 defends, if the attacker is in its <img class='inline-img' src='img/bulls.png'>, you may spend 1 <img class='inline-img' src='img/fo.png'> to change 1 of the defender's blank results to a <img class='inline-img' src='img/Fo W.png'> result.</div>" }
D.pilots[278] = { name_FRA = "Drift", name_ENG = "Drift", id = 277, max_per_squad = 1, faction = "Clone_Army", ship = "Clone Z-95 Headhunter", charge = {0}, force = 0, shipId = 79, skill = 3, points = 8, ability_FRA = "<div class='text'>Lorsqu'un vaisseau allié à portée 0-1 effectue une attaque, si vous avez exactement 1 jeton rouge ou exactement 1 jeton orange, ce vaisseau peut relancer 1 dé d'attaque.</div>", ability_ENG = "<div class='text'>While a friendly ship at range 0-1 performs an attack, if you have exactly 1 red token or exactly 1 orange token, that ship may reroll 1 attack die.</div>" }
D.pilots[279] = { name_FRA = "Stub", name_ENG = "Stub", id = 278, max_per_squad = 1, faction = "Clone_Army", ship = "Clone Z-95 Headhunter", charge = {0}, force = 0, shipId = 79, skill = 3, points = 8, ability_FRA = "<div class='text'>Lorsque vous défendez, si la vitesse de votre manoeuvre révélée est paire, lancez 1 dé de défense supplementaire.<br>Lorsque vous effectuez une attaque principale, si la vitesse de votre manoeuvre révélée est impaire, lancez 1 dé d'attaque supplémentaire.</div>", ability_ENG = "<div class='text'>While you defend, if the speed of your revealed maneuver is even, roll 1 additional defense die. While you perform a primary attack, if the speed of your revealed maneuver is odd, roll 1 additional attack die.</div>" }
