D.pilots[281] = { name_FRA = "Killer", name_ENG = "Killer", id = 280, max_per_squad = 1, faction = "Clone_Army", ship = "Clone Z-95 Headhunter", charge = {0}, force = 0, shipId = 79, skill = 2, points = 7, ability_FRA = "<div class='text'>Lorsque vous effectuez une attaque, si le défenseur a 2 coques restantes ou moins, vous pouvez lancer 1 dé d'attaque supplémentaire. Dans ce cas, recevez 1 jeton épuisement après avoir lancé les dés.</div>", ability_ENG = "<div class='text'>While you perform an attack, if the defender has 2 or fewer hull remaining, you may roll 1 additional attack die. If you do, gain 1 deplete token after rolling attack dice.</div>" }
