D.pilots[302] = { name_FRA = "Contrail", name_ENG = "Contrail", id = 301, max_per_squad = 1, faction = "Clone_Army", ship = "Nimbus-class V-wing", charge = {0}, force = 0, shipId = 71, skill = 5, points = 10, ability_FRA = "<div class='text'>Lorsqe vous attaquez ou défendez, si la direction de votre manoeuvre révélée est la même que celle du vaisseau ennemi, vous pouvez changer 1 résultat <img class='inline-img' src='img/Fo W.png'> du vaisseau ennemis en résultat vierge.</div>", ability_ENG = "<div class='text'>While you defend or perform an attack, if the bearing of your revealed maneuver is the same as the enemy ship's, you may change 1 of the enemy ship's <img class='inline-img' src='img/Fo W.png'> results to a blank result.</div>" }
