D.pilots[304] = { name_FRA = "Wilhuff Tarkin", name_ENG = "Wilhuff Tarkin", id = 303, max_per_squad = 1, faction = "Clone_Army", ship = "Nimbus-class V-wing", charge = {0}, force = 0, shipId = 71, skill = 3, points = 9, ability_FRA = "<div class='text'>Fin de la Mise en Place : votre adversaire doit placer 1 'Cible à Eliminer'.<br>'Cible à Eliminer' : Satellite, 3 Coques 2 Agilité, peut se relocaliser. Il doit être attaqué à portée 1. Lorsque CàE est détruite, vous gagnez 2 PO.</div>", ability_ENG = "<div class='text'>End of SETUP : your opponent has to place 1 'Target to eliminate'.<br>'Target to Eliminate' : Remote, 3hull 2 agility, may relocate. It must be attacked at range 1. When T2E is destroyed, you gain 2 PO.</div>" }
D.pilots[305] = { name_FRA = "Crosshair", name_ENG = "Crosshair", id = 304, max_per_squad = 1, faction = "Clone_Army", ship = "Nimbus-class V-wing", charge = {0}, force = 0, shipId = 71, skill = 3, points = 10, ability_FRA = "<div class='text'>Lorsque vous effectuez une attaque, considérez la comme étant dans votre <img class='inline-img' src='img/bulls.png'> et à portée 1.</div>", ability_ENG = "<div class='text'>While you perform an attack, consider it at range 1 and in your <img class='inline-img' src='img/bulls.png'>.</div>" }
D.pilots[306] = { name_FRA = "Pilote du 104ème Bataillon", name_ENG = "104th Battalion Pilot", id = 305, max_per_squad = 8, faction = "Clone_Army", ship = "ARC-170 Starfighter", charge = {0}, force = 0, shipId = 30, skill = 2, points = 10, ability_FRA = "<div class='text'></div>", ability_ENG = "<div class='text'></div>" }
D.pilots[307] = { name_FRA = "Wolffe", name_ENG = "Wolffe", id = 306, max_per_squad = 1, faction = "Clone_Army", ship = "ARC-170 Starfighter", charge = {0}, force = 0, shipId = 30, skill = 4, points = 12, ability_FRA = "<div class='text'>Lorsque vous effectuez une attaque principale <img class='inline-img' src='img/attackF.png'>, vous pouvez dépenser 1 <img class='inline-img' src='img/charge.png'> pour relancer 1 dé d'attaque. Lorsque vous effectuez une attaque principale <img class='inline-img' src='img/attackB.png'>, vous pouvez récupérer 1 <img class='inline-img' src='img/charge.png'> pour lancer 1 dé d'attaque supplémentaire.</div>", ability_ENG = "<div class='text'>While you perform a primary <img class='inline-img' src='img/attackF.png'> attack, you may spend 1 <img class='inline-img' src='img/charge.png'> to reroll 1 attack die. While you perform a primary <img class='inline-img' src='img/attackB.png'> attack, you may recover 1 <img class='inline-img' src='img/charge.png'> to roll 1 additional die.</div>" }
D.pilots[308] = { name_FRA = "Odd Ball", name_ENG = "Odd Ball", id = 307, max_per_squad = 1, faction = "Clone_Army", ship = "ARC-170 Starfighter", charge = {0}, force = 0, shipId = 30, skill = 5, points = 11, ability_FRA = "<div class='text'>Après avoir entièrement exécuté une manoeuvre rouge ou effectué une action rouge, si il y a un vaisseau ennemi dans votre <img class='inline-img' src='img/bulls.png'>, vous pouvez effectuer une acquisition sur ce vaisseau.</div>", ability_ENG = "<div class='text'>After you fully execute a red maneuver or perform a red action, if there is an enemy ship in your <img class='inline-img' src='img/bulls.png'>, you may acquire a lock on that ship.</div>" }
D.pilots[309] = { name_FRA = "Sinker", name_ENG = "Sinker", id = 308, max_per_squad = 1, faction = "Clone_Army", ship = "ARC-170 Starfighter", charge = {0}, force = 0, shipId = 30, skill = 3, points = 12, ability_FRA = "<div class='text'>Lorsqu'un un vaisseau allié à portée 0-2 dans votre <img class='inline-img' src='img/Larc.png'> ou <img class='inline-img' src='img/Rarc.png'> effectue une attaque principale, il peut relancer 1 dé d'attaque.</div>", ability_ENG = "<div class='text'>While a friendly ship at range 1-2 in your <img class='inline-img' src='img/Larc.png'> or <img class='inline-img' src='img/Rarc.png'> performs a primary attack, it may reroll 1 attack die.</div>" }
D.pilots[310] = { name_FRA = "Jag", name_ENG = "Jag", id = 309, max_per_squad = 1, faction = "Clone_Army", ship = "ARC-170 Starfighter", charge = {0}, force = 0, shipId = 30, skill = 3, points = 11, ability_FRA = "<div class='text'>Après qu'un vaisseau allié à portée 1-2 dans cotre <img class='inline-img' src='img/Larc.png'> ou <img class='inline-img' src='img/Rarc.png'> a défendu, vous pouvez acquisitionner l'attaquant.</div>", ability_ENG = "<div class='text'>After a friendly ship at range 1-2 in your <img class='inline-img' src='img/Rarc.png'> or <img class='inline-img' src='img/Larc.png'> defends, you may acquire a lock on the attacker.</div>" }
D.pilots[311] = { name_FRA = "Pilote de Navette d'Escorte", name_ENG = "Escort Shuttle Pilot", id = 310, max_per_squad = 8, faction = "Clone_Army", ship = "Omicron Class Shuttle", charge = {0}, force = 0, shipId = 95, skill = 1, points = 9, ability_FRA = "<div class='text'></div>", ability_ENG = "<div class='text'></div>" }
D.pilots[312] = { name_FRA = "Echo", name_ENG = "Echo", id = 311, max_per_squad = 1, faction = "Clone_Army", ship = "Omicron Class Shuttle", charge = {0}, force = 0, shipId = 95, skill = 4, points = 13, ability_FRA = "<div class='text'>Après avoir effectué une action, vous pouvez effectuer une action rouge <img class='inline-img' src='img/Cc W.png'>. Pendant la phase de fin, vous pouvez dépenser un jeton calcul. Dans ce cas, coordonnez un vaisseau 1-3</div>", ability_ENG = "<div class='text'>After you perform an action, you may perform a bonus <img class='inline-img' src='img/Cc W.png'> action. At the end phase, you may spend a calculate token. If you do, you may coordinate a ship at range 1-3.</div>" }
D.pilots[313] = { name_FRA = "Tech", name_ENG = "Tech", id = 312, max_per_squad = 1, faction = "Clone_Army", ship = "Omicron Class Shuttle", charge = {0}, force = 0, shipId = 95, skill = 4, points = 12, ability_FRA = "<div class='text'>Après avoir effectué une action, vous pouvez effectuer une action rouge <img class='inline-img' src='img/Ja W.png'>. Pendant la phase de fin, si il y a un vaisseau brouillé à portée 0-1, coordonnez un vaisseau à portée 1-3.</div>", ability_ENG = "<div class='text'>After you perform an action, you may perform a red <img class='inline-img' src='img/Ja W.png'> action. At the end phase, if there is a jammed ship at range 0-1, you may coordinate a ship at range 1-3.</div>" }
D.pilots[314] = { name_FRA = "Hunter", name_ENG = "Hunter", id = 313, max_per_squad = 1, faction = "Clone_Army", ship = "Omicron Class Shuttle", charge = {0}, force = 0, shipId = 95, skill = 3, points = 12, ability_FRA = "<div class='text'>Après avoir effectué une action, vous pouvez effectuer une action rouge <img class='inline-img' src='img/Lo W.png'>. Pendant la phase de fin, vous pouvez dépenser une acquisition que vous avez sur un vaisseau. Dans ce cas, coordonnez ce vaisseau.</div>", ability_ENG = "<div class='text'>After you perform an action, you may perform a red <img class='inline-img' src='img/Lo W.png'> action. At the end phase, you may spend a lock you have on a ship. If you do, coordinate this ship.</div>" }
D.pilots[315] = { name_FRA = "Wrecker", name_ENG = "Wrecker", id = 314, max_per_squad = 1, faction = "Clone_Army", ship = "Omicron Class Shuttle", charge = {0}, force = 0, shipId = 95, skill = 1, points = 12, ability_FRA = "<div class='text'>Après avoir effectué une action, vous pouvez effectuer une action rouge <img class='inline-img' src='img/Br W.png'>. Pendant la phase de fun, vous pouvez dépenser 1 jeton stress pour effectuer une attaque bonus principale contre un vaisseau ennemi à portée 0.</div>", ability_ENG = "<div class='text'>After you perform an action, you may perform a red <img class='inline-img' src='img/Br W.png'> action. At the end phase, you may spend a stress token to perform a bonus primary attack against an enemy ship at range 0.</div>" }
