D.pilots[381] = { name_FRA = "Ketsu Onyo", name_ENG = "Ketsu Onyo", id = 380, max_per_squad = 1, faction = "Black_Sun", ship = "Lancer-Class Pursuit Craft", charge = {0}, force = 0, shipId = 32, skill = 5, points = 16, ability_FRA = "<div class='text'>Au début de la phase d’engagement, vous pouvez choisir 1 vaisseau à portée 0-1 qui est à la fois dans votre <img class='inline-img' src='img/attackF.png'> et dans votre <img class='inline-img' src='img/Tarc.png'>. Dans ce cas, ce vaisseau gagne 1 jeton tractage.</div>", ability_ENG = "<div class='text'>At the start of the Engagement Phase, you may choose 1 ship in both your <img class='inline-img' src='img/attackF.png'> and <img class='inline-img' src='img/Tarc.png'> at range 0-1. If you do, it gains 1 tractor token.</div>" }
D.pilots[382] = { name_FRA = "Gyran", name_ENG = "Gyran", id = 381, max_per_squad = 1, faction = "Black_Sun", ship = "Lancer-Class Pursuit Craft", charge = {0}, force = 0, shipId = 32, skill = 4, points = 15, ability_FRA = "<div class='text'>Lorsque vous défendez, si l'attaquant est dans votre <img class='inline-img' src='img/Tarc.png'> à portée 0-2, vous pouvez ajouter 1 résultat <img class='inline-img' src='img/Fo W.png'> à vos résultats.</div>", ability_ENG = "<div class='text'>While you defend, if the attacker is in your <img class='inline-img' src='img/Tarc.png'> at range 0-2, you may add 1 <img class='inline-img' src='img/Fo W.png'> result to your dice result.</div>" }
D.pilots[383] = { name_FRA = "Malva Greek", name_ENG = "Malva Greek", id = 382, max_per_squad = 1, faction = "Black_Sun", ship = "Lancer-Class Pursuit Craft", charge = {0}, force = 0, shipId = 32, skill = 1, points = 15, ability_FRA = "<div class='text'>Après être désigné défenseur, si l'attaquant n'est pas dans votre <img class='inline-img' src='img/Tarc.png'> , vous devez tournez votre indicateur <img class='inline-img' src='img/Tarc.png'> vers un arc de tir dans lequel se trouve l'attaquant.</div>", ability_ENG = "<div class='text'>After you become the defender, if the attacker is not in your <img class='inline-img' src='img/Tarc.png'> , you must rotate your <img class='inline-img' src='img/Tarc.png'> indicator to a standard arc the attacker is in.</div>" }
