D.pilots[385] = { name_FRA = "Zu Pike", name_ENG = "Zu Pike", id = 384, max_per_squad = 1, faction = "Black_Sun", ship = "Rihkxyrk Attack Ship", charge = {0}, force = 0, shipId = 86, skill = 5, points = 13, ability_FRA = "<div class='text'>Lorsqu'un vaisseau verrouillé par vous attaque, vous pouvez choisir 1 dé d'attaque. Dans ce cas, l'attaquant relance ce dé.</div>", ability_ENG = "<div class='text'>While a ship you are locking performs an attack, you may choose 1 attack die. If you do, the attacker rerolls that die.</div>" }
D.pilots[386] = { name_FRA = "Zan Pike", name_ENG = "Zan Pike", id = 385, max_per_squad = 1, faction = "Black_Sun", ship = "Rihkxyrk Attack Ship", charge = {0}, force = 0, shipId = 86, skill = 5, points = 13, ability_FRA = "<div class='text'>Vous ne subissez pas l'effet d'une bombe alliée ou d'un engin verrouillé. Lorsqu'un engin verrouillé explose, vous pouvez verrouiller un objet à portée 0-1 de cet engin.</div>", ability_ENG = "<div class='text'>You don't suffer effects from  allied bombs or locked payloads. When a locked payload detonates, you may acquire a lock on an boject at range 0-1 from that payload.</div>" }
D.pilots[387] = { name_FRA = "Zeka Thyne", name_ENG = "Zeka Thyne", id = 386, max_per_squad = 1, faction = "Black_Sun", ship = "Rihkxyrk Attack Ship", charge = {0}, force = 0, shipId = 86, skill = 3, points = 13, ability_FRA = "<div class='text'>Pendant la Phase Système, si il n'y a pas de vaisseaux ennemis à portée 1-2, vous pouvez récupérer 1 <img class='inline-img' src='img/charge.png'> sur n'importe quelle amélioration.</div>", ability_ENG = "<div class='text'>During the System Phase, if there are no enemy ships at range 1-2, you may recover 1 <img class='inline-img' src='img/charge.png'> on any upgrade.</div>" }
D.pilots[388] = { name_FRA = "Lar'Omx", name_ENG = "Lar'Omx", id = 387, max_per_squad = 1, faction = "Black_Sun", ship = "Supa Starfighter", charge = {0}, force = 0, shipId = 83, skill = 5, points = 13, ability_FRA = "<div class='text'>Après avoir effecuté une manoeuvre rouge, vous pouvez verrouiller un vaisseau ennemi dans votre <img class='inline-img' src='img/attackF.png'> at range 0-1.</div>", ability_ENG = "<div class='text'>After you execute a red maneuver, you may acquire a lock on an enemy ship in your <img class='inline-img' src='img/attackF.png'> at range 0-1.</div>" }
D.pilots[389] = { name_FRA = "Rynscar", name_ENG = "Rynscar", id = 388, max_per_squad = 1, faction = "Black_Sun", ship = "Supa Starfighter", charge = {0}, force = 0, shipId = 83, skill = 3, points = 12, ability_FRA = "<div class='text'>Pendant la Phase Système, vous pouvez choisir un objet que vous avez verrouillé à portée 1-3. Un autre vaisseau allié à portée 1-3 peut verrouiller cet objet.</div>", ability_ENG = "<div class='text'>During the System Phase, you may choose an object that you have locked at range 1-3. Another friendly ships at range 1-3 may acquire a lock on that object.</div>" }
D.pilots[390] = { name_FRA = "Duc Blazor", name_ENG = "Duke Blazor", id = 389, max_per_squad = 1, faction = "Black_Sun", ship = "Supa Starfighter", charge = {0}, force = 0, shipId = 83, skill = 4, points = 12, ability_FRA = "<div class='text'>Lorsque vous recevez un jeton orange, vous pouvez recevoir à la place un autre jeton orange de votre choix.</div>", ability_ENG = "<div class='text'>When you receive an orange token, you may receive instead an other orange token of your choice.</div>" }
D.pilots[391] = { name_FRA = "Dalan Oberos", name_ENG = "Dalan Oberos", id = 390, max_per_squad = 1, faction = "Hutt_Cartel", ship = "M12-L Kimogila Fighter", charge = {2, "yellow", "0"}, force = 0, shipId = 40, skill = 3, points = 12, ability_FRA = "<div class='text'>Au début de la phase d’engagement, vous pouvez choisir 1 vaisseau protégé dans votre <img class='inline-img' src='img/bulls.png'> et dépenser 1 <img class='inline-img' src='img/charge.png'>. Dans ce cas, ce vaisseau perd 1 bouclier et vous récupérez 1 bouclier.</div>", ability_ENG = "<div class='text'>At the start of the engagement phase, you may choose 1 shielded ship in your <img class='inline-img' src='img/bulls.png'> and spend 1 charge. If you do, that ship loses 1 shield and you recover 1 shield.</div>" }
D.pilots[392] = { name_FRA = "Torani Kulda", name_ENG = "Torani Kulda", id = 391, max_per_squad = 1, faction = "Hutt_Cartel", ship = "M12-L Kimogila Fighter", charge = {0}, force = 0, shipId = 40, skill = 4, points = 13, ability_FRA = "<div class='text'>Après avoir attaqué, chaque vaisseau ennemi dans votre <img class='inline-img' src='img/bulls.png'> subit 1 dégat <img class='inline-img' src='img/hit.png'> à moins qu'il ne retire 1 jeton vert.</div>", ability_ENG = "<div class='text'>After you perform an attack, each enemy ship in your <img class='inline-img' src='img/bulls.png'> suffers 1 <img class='inline-img' src='img/hit.png'> damage unless it removes 1 green token.</div>" }
D.pilots[393] = { name_FRA = "Khel Tanna", name_ENG = "Khel Tanna", id = 392, max_per_squad = 1, faction = "Hutt_Cartel", ship = "M12-L Kimogila Fighter", charge = {0}, force = 0, shipId = 40, skill = 2, points = 12, ability_FRA = "<div class='text'>Après avoir effectué une attaque qui touche dans votre <img class='inline-img' src='img/bulls.png'>, vous pouvez retirer une charge du pilote défenseur, ou d'une de ses améliorations.</div>", ability_ENG = "<div class='text'>After you perform an attack in your <img class='inline-img' src='img/bulls.png'> that hits, you may remove a charge from the defending pilot, or from one of its equipped upgrades.</div>" }
