D.pilots[401] = { name_FRA = "Moralo Eval", name_ENG = "Moralo Eval", id = 400, max_per_squad = 1, faction = "Hutt_Cartel", ship = "YV-666 Light Freighter", charge = {2, "yellow", "0"}, force = 0, shipId = 21, skill = 3, points = 15, ability_FRA = "<div class='text'>Si vous êtes censé fuir, vous pouvez dépenser 1 <img class='inline-img' src='img/charge.png'>. Dans ce cas, mettez-vous en réserve à la place. Au début de la prochaine phase de préparation, placez-vous intégralement à portée 1 du bord de la zone de jeu par lequel vous auriez dû fuir.</div>", ability_ENG = "<div class='text'>If you would flee, you may spend 1 <img class='inline-img' src='img/charge.png'>. If you do, place yourself in reserves instead. At the start of the next Planning Phase, place yourself within range 1 of the edge of the play area that you fled from.</div>" }
D.pilots[402] = { name_FRA = "Ephant Mon", name_ENG = "Ephant Mon", id = 401, max_per_squad = 1, faction = "Hutt_Cartel", ship = "YV-666 Light Freighter", charge = {2, "yellow", "0"}, force = 0, shipId = 21, skill = 4, points = 16, ability_FRA = "<div class='text'>Lorsqu'un vaisseau à portée 2 est détruit, vous pouvez dépenser 1 <img class='inline-img' src='img/charge.png'> et recevoir un jeton désarmement. Dans ce cas, gagnez 1 point de scénario.</div>", ability_ENG = "<div class='text'>When a ship at range 2 is destroyed, you may spend 1 charge and gain 1 disarm token. If you do, gain 1 PO.</div>" }
D.pilots[403] = { name_FRA = "EV-9D9", name_ENG = "EV-9D9", id = 402, max_per_squad = 1, faction = "Hutt_Cartel", ship = "YV-666 Light Freighter", charge = {0}, force = 0, shipId = 21, skill = 1, points = 15, ability_FRA = "<div class='text'>Lorsqu'un vaisseau ennemi à portée 0-2 est détruit, s'il a une amélioration <img class='inline-img' src='img/Crew.png'> ou <img class='inline-img' src='img/Astromech.png'> équipée, vous pouvez l'équipper sur votre vaisseau. Elle utilise à présent l'un de vos emplacement <img class='inline-img' src='img/Crew.png'>. Si vous n'avez pas d'emplacement disponible, vous pouvez retirer l'une de vos améliorations <img class='inline-img' src='img/Crew.png'> pour équipper la nouvelle.</div>", ability_ENG = "<div class='text'>When a enemy ship at range 0-2 is destroyed, if it has a <img class='inline-img' src='img/Crew.png'> or <img class='inline-img' src='img/Astromech.png'> equipped upgrade, you may equip it. It now occupies 1 of your available <img class='inline-img' src='img/Crew.png'> slot. If you don't have any available <img class='inline-img' src='img/Crew.png'> slot, you may remove one of your <img class='inline-img' src='img/Crew.png'> upgrade in order to equip the new one.</div>" }
D.pilots[404] = { name_FRA = "Docteure Aphra", name_ENG = "Doctor Aphra", id = 403, max_per_squad = 1, faction = "Hutt_Cartel", ship = "YV-666 Light Freighter", charge = {3, "yellow", "0"}, force = 0, shipId = 21, skill = 3, points = 16, ability_FRA = "<div class='text'>Avant de vous engager, vous pouvez dépenser 1 jeton vert et 1 <img class='inline-img' src='img/charge.png'>. Dans ce cas, vous pouvez choisir un autre vaisseau à portée 0-1 qui n'est pas stressé. Le vaisseau choisi reçoit 1 jeton stress.</div>", ability_ENG = "<div class='text'>Before you engage, you may spend 1 green token and 1 <img class='inline-img' src='img/charge.png'>. If you do, you may choose another ship at range 0-1 that is not stressed. The chosen ship gains 1 stress token.</div>" }
