D.pilots[418] = { name_FRA = "Carson Teva", name_ENG = "Carson Teva", id = 417, max_per_squad = 1, faction = "New_Republic_Patrol", ship = "T-65 X-wing", charge = {0}, force = 0, shipId = 0, skill = 4, points = 12, ability_FRA = "<div class='text'>Mise en Place : Assignez la condition 'Intrus' à un vaisseau.<br>Après avoir désigné le défenseur lors d'une attaque, si vous avez un verrouillage sur le défenseur, un vaisseau allié peut transférer un verrouillage qu'il avait sur vous vers le défenseur.</div>", ability_ENG = "<div class='text'>SETUP : assign the 'Intruder' condition to a ship.<br>After you declare the defender of an attack, if you a have lock on the defender, a friendly ship may transfer its lock token from you to the defender</div>" }
D.pilots[419] = { name_FRA = "Trapper Wolf", name_ENG = "Trapper Wolf", id = 418, max_per_squad = 1, faction = "New_Republic_Patrol", ship = "T-65 X-wing", charge = {0}, force = 0, shipId = 0, skill = 3, points = 12, ability_FRA = "<div class='text'>Mise en Place : Assignez la condition 'Intrus' à un vaisseau.<br>Après avoir reçu un jeton stress, vous pouvez lancer 1 dé d'attaque pour le retirer. Sur un résultat <img class='inline-img' src='img/hit.png'>, subissez un dégat <img class='inline-img' src='img/hit.png'>.</div>", ability_ENG = "<div class='text'>SETUP : assign the 'Intruder' condition to a ship.<br>After you receive a stress token, you may roll 1 attack die to remove it. On a <img class='inline-img' src='img/hit.png'> result, suffer 1 <img class='inline-img' src='img/hit.png'> damage.</div>" }
D.pilots[420] = { name_FRA = "Iden Versio", name_ENG = "Iden Versio", id = 419, max_per_squad = 1, faction = "New_Republic_Patrol", ship = "T-65 X-wing", charge = {2, "yellow", "+"}, force = 0, shipId = 0, skill = 5, points = 14, ability_FRA = "<div class='text'>Avant qu'un vaisseau allié X-Wing ou A-Wing à portée 0-1 ne subisse des dégats, vous pouvez dépenser 2 <img class='inline-img' src='img/charge.png'>. Dans ce cas, prévenez 1 dégat.</div>", ability_ENG = "<div class='text'>Before a friendly X-wing or A-wing would suffer damage at range 0-1, you may spend 2 <img class='inline-img' src='img/charge.png'>. If you do, prevent 1 damage.</div>" }
