D.pilots[427] = { name_FRA = "Ahsoka Tano", name_ENG = "Ahsoka Tano", id = 426, max_per_squad = 1, faction = "New_Republic_Patrol", ship = "T-6 Shuttle", charge = {0}, force = 3, shipId = 82, skill = 5, points = 15, ability_FRA = "<div class='text'>Après avoir entièrement effectué une manoeuvre, vous pouvez choisir un vaisseau allié à portée 1-2 et dépenser 2 <img class='inline-img' src='img/fo.png'>. Ce vaisseau peut effectuer une action, même stressé.</div>", ability_ENG = "<div class='text'>After you fully execute a maneuver, you may choose a friendly ship at range 1-2 and spend 2 <img class='inline-img' src='img/fo.png'> . That ship may perform an action, even while stressed.</div>" }
