D.pilots[430] = { name_FRA = "Sabine Wren", name_ENG = "Sabine Wren", id = 429, max_per_squad = 1, faction = "New_Republic_Patrol", ship = "T-6 Shuttle", charge = {0}, force = 1, shipId = 82, skill = 3, points = 14, ability_FRA = "<div class='text'>Avant de vous activer, vous pouvez effectuer une action <img class='inline-img' src='img/Br W.png'> ou <img class='inline-img' src='img/Bo W.png'>.", ability_ENG = "<div class='text'>Before you activate, you may perform a <img class='inline-img' src='img/Br W.png'> or <img class='inline-img' src='img/Bo W.png'> action.</div>" }
