D.pilots[443] = { name_FRA = "Jarek Yaeger", name_ENG = "Jarek Yaeger", id = 442, max_per_squad = 1, faction = "Colossus", ship = "Fireball", charge = {0}, force = 0, shipId = 64, skill = 5, points = 9, ability_FRA = "<div class='text'>Tant que vous avez 2 marqueurs de stress ou moins, si vous êtes endommagé, vous pouvez exécuter des manœuvres basiques rouges, même si vous êtes stressé ; si vous êtes critiquement endommagé, vous pouvez exécuter des manœuvres avancées rouges, même si vous êtes stressé.</div>", ability_ENG = "<div class='text'>While you have 2 or fewer stress tokens, if you are damaged, you can execute red basic maneuvers even while stressed. If you are critically damaged, you can execute red advanced maneuvers even while stressed.</div>" }
D.pilots[444] = { name_FRA = "Kazuda Xiono", name_ENG = "Kazuda Xiono", id = 443, max_per_squad = 1, faction = "Colossus", ship = "Fireball", charge = {0}, force = 0, shipId = 64, skill = 4, points = 10, ability_FRA = "<div class='text'>Tant que vous défendez ou effectuez une attaque principale, si l’initiative du vaisseau ennemi est plus élevée que le nombre de cartes de dégât que vous avez, vous pouvez lancer 1 dé supplémentaire.</div>", ability_ENG = "<div class='text'>While you defend or perform a primary attack, if the enemy ship's initiative is higher than the number of damage cards you have, you may roll 1 additional die.</div>" }
