D.pilots[463] = { name_FRA = "Dark Maul", name_ENG = "Darth Maul", id = 462, max_per_squad = 1, faction = "Agents_of_Chaos", ship = "Sith Infiltrator", charge = {0}, force = 3, shipId = 55, skill = 5, points = 16, ability_FRA = "<div class='text'>Après avoir effectué une attaque, vous pouvez dépenser 2 <img class='inline-img' src='img/fo.png'> pour effectuer une attaque principale bonus contre une cible différente. Si votre attaque était ratée, vous pouvez effectuer cette attaque principale bonus contre la même cible à la place.</div>", ability_ENG = "<div class='text'>After you perform an attack, you may spend 2 <img class='inline-img' src='img/fo.png'> to perform a bonus primary attack against a different target. If your attack missed, you may perform that bonus primary attack against the same target instead</div>" }
D.pilots[464] = { name_FRA = "Comte Dooku", name_ENG = "Count Dooku", id = 463, max_per_squad = 1, faction = "Agents_of_Chaos", ship = "Sith Infiltrator", charge = {0}, force = 3, shipId = 55, skill = 3, points = 15, ability_FRA = "<div class='text'>Après avoir défendu, si l’attaquant est dans votre arc de tir, vous pouvez dépenser 1 <img class='inline-img' src='img/fo.png'> pour retirer 1 de vos marqueurs bleus ou rouges.<br>Après avoir effectué une attaque qui touche, vous pouvez dépenser 1 <img class='inline-img' src='img/fo.png'> pour effectuer une action.</div>", ability_ENG = "<div class='text'>After you defend, if the attacker is in your firing arc, you may spend 1 <img class='inline-img' src='img/fo.png'> to remove 1 of your blue or red tokens.<br>After you perform an attack that hits, you may spend 1 <img class='inline-img' src='img/fo.png'> to perform an action.</div>" }
D.pilots[465] = { name_FRA = "0-66", name_ENG = "0-66", id = 464, max_per_squad = 1, faction = "Agents_of_Chaos", ship = "Sith Infiltrator", charge = {0}, force = 0, shipId = 55, skill = 3, points = 13, ability_FRA = "<div class='text'>Après avoir défendu, vous pouvez dépenser 1 marqueur de calcul pour effectuer une action.</div>", ability_ENG = "<div class='text'>After you defend, you may spend 1 calculate token to perform an action.</div>" }
D.pilots[466] = { name_FRA = "Sun Fac", name_ENG = "Sun Fac", id = 465, max_per_squad = 1, faction = "Separatist_Government", ship = "Nantex-Class Starfighter", charge = {0}, force = 0, shipId = 62, skill = 6, points = 12, ability_FRA = "<div class='text'>Tant que vous effectuez une attaque principale, si le défenseur est tracté, lancez 1 dé d’attaque supplémentaire.</div>", ability_ENG = "<div class='text'>While you perform a primary attack, if the defender is tractored, roll 1 additional attack die.</div>" }
D.pilots[467] = { name_FRA = "Chertek", name_ENG = "Chertek", id = 466, max_per_squad = 1, faction = "Separatist_Government", ship = "Nantex-Class Starfighter", charge = {0}, force = 0, shipId = 62, skill = 4, points = 9, ability_FRA = "<div class='text'>Tant que vous effectuez une attaque principale, si le défenseur est tracté, vous pouvez relancer jusqu’à 2 dés d’attaque.</div>", ability_ENG = "<div class='text'>While you perform a primary attack, if the defender is tractored, you may reroll up to 2 attack dice.</div>" }
D.pilots[468] = { name_FRA = "Gorgol", name_ENG = "Gorgol", id = 467, max_per_squad = 1, faction = "Separatist_Government", ship = "Nantex-Class Starfighter", charge = {0}, force = 0, shipId = 62, skill = 2, points = 9, ability_FRA = "<div class='text'>Pendant la phase de système, vous pouvez gagner 1 jeton désarmement et choisir un vaisseau allié à porté 1-2. Dans ce cas, il gagne 1 marqueur de rayon tracteur, puis il répare 1 de ses cartes de dégât face visible Vaisseau.</div>", ability_ENG = "<div class='text'>During the System Phase, you may gain 1 disarm token and choose a friendly ship at range 1-2. If you do, it gains 1 tractor token, then repairs 1 of its faceup Ship trait damage cards.</div>" }
D.pilots[469] = { name_FRA = "Berwert Krek", name_ENG = "Berwert Krek", id = 468, max_per_squad = 1, faction = "Separatist_Government", ship = "Nantex-Class Starfighter", charge = {0}, force = 0, shipId = 62, skill = 5, points = 10, ability_FRA = "<div class='text'>Après avoir effectué une attaque qui touche, chaque vaisseau allié avec l'action <img class='inline-img' src='img/Cc W.png'> sur sa barre d'action à portée 1-3 peut vérouiller le défenseur.", ability_ENG = "<div class='text'>After you perform an attack that hits, each friendly ship with <img class='inline-img' src='img/Cc W.png'> on its action bar at range 1-3 may acquire a lock on the defender." }
