D.pilots[471] = { name_FRA = "Cad Bane", name_ENG = "Cad Bane", id = 470, max_per_squad = 1, faction = "Agents_of_Chaos", ship = "Rogue-class Starfighter", charge = {1, "yellow", "+"}, force = 0, shipId = 80, skill = 4, points = 11, ability_FRA = "<div class='text'>Pendant la phase d’engagement, après qu’un autre vaisseau à portée 0–3 a été détruit, vous pouvez dépenser 1 <img class='inline-img' src='img/charge.png'> pour effectuer une action, même si vous êtes stressé.", ability_ENG = "<div class='text'>During the Engagement Phase, after another ship at range 0-3 is destroyed, you may spend 1 charge to perform an action, even while stressed." }
D.pilots[472] = { name_FRA = "Protecteur Magna Garde", name_ENG = "Magnaguard Protector", id = 471, max_per_squad = 2, faction = "Agents_of_Chaos", ship = "Rogue-class Starfighter", charge = {0}, force = 0, shipId = 80, skill = 4, points = 10, ability_FRA = "<div class='text'>Mise en Place : après avoir placé les forces, assignez l'état 'Sous Protection' à 1 vaisseau allié autre que Protecteur Magna Garde.</div>", ability_ENG = "<div class='text'>Setup: After placing forces, assign the 'Guarded' condition to 1 friendly ship other than the MagnaGuard Protector</div>" }
D.pilots[473] = { name_FRA = "Durge", name_ENG = "Durge", id = 472, max_per_squad = 1, faction = "Agents_of_Chaos", ship = "Rogue-class Starfighter", charge = {1, "yellow", "0"}, force = 0, shipId = 80, skill = 5, points = 12, ability_FRA = "<div class='text'>Quand vous devriez être détruit, vous pouvez dépenser 1 <img class='inline-img' src='img/charge.png'> pour révéler toutes vos cartes de dégât face cachée. Dans ce cas, défaussez chaque Coup au But ! et chaque carte de dégât ayant le trait Pilote, puis réparez toutes vos cartes de dégât face visible.</div>", ability_ENG = "<div class='text'>When you would be destroyed, you may spend 1 <img class='inline-img' src='img/charge.png'> to reveal all of your facedown damage cards. If you do, discard each Direct Hit! and each of your damage cards with the Pilot trait, then repair all of your faceup damage cards.</div>" }
