D.pilots[475] = { name_FRA = "Jango Fett", name_ENG = "Jango Fett", id = 474, max_per_squad = 1, faction = "Agents_of_Chaos", ship = "Firespray-class Patrol Craft", charge = {0}, force = 0, shipId = 7, skill = 6, points = 20, ability_FRA = "<div class='text'>Tant que vous défendez ou effectuez une attaque principale, si la difficulté de votre manœuvre révélée est inférieure à celle du vaisseau ennemi, vous pouvez changer 1 des résultats <img class='inline-img' src='img/Fo W.png'> du vaisseau ennemi en un résultat vierge.</div>", ability_ENG = "<div class='text'>While you defend or perform a primary attack, if the difficulty of your revealed maneuver is less than that of the enemy ship's, you may change 1 of the enemy ship's <img class='inline-img' src='img/Fo W.png'> results to a blank result.</div>" }
