D.pilots[478] = { name_FRA = "Aurra Sing", name_ENG = "Aurra Sing", id = 477, max_per_squad = 1, faction = "Agents_of_Chaos", ship = "Firespray-class Patrol Craft", charge = {0}, force = 1, shipId = 7, skill = 3, points = 17, ability_FRA = "<div class='text'>Avant de vous engager, vous pouvez dépenser 1 <img class='inline-img' src='img/fo.png'> pour choisir 2 vaisseaux ennemis à portée 0-1. Transférez n'importe quel nombre de marqueurs orange et rouges entre ces 2 vaisseaux.</div>", ability_ENG = "<div class='text'>Before you engage, you may spend 1 <img class='inline-img' src='img/fo.png'> to choose 2 enemy ships at range 0-1. Transfer any number of orange and red tokens between those two ships.</div>" }
