D.pilots[491] = { name_FRA = "Kylo Ren", name_ENG = "Kylo Ren", id = 490, max_per_squad = 1, faction = "First_Order_Specialists", ship = "TIE/wi Whisper Modified Interceptor", charge = {0}, force = 3, shipId = 75, skill = 5, points = 14, ability_FRA = "<div class='text'>Avant qu'une carte de dégât face cachée ne soit attribuée à un vaisseau ennemi dans votre <img class='inline-img' src='img/bulls.png'> , vous pouvez dépenser 1 <img class='inline-img' src='img/fo.png'> . Dans ce cas, cette carte est attribuée face visible à la place.</div>", ability_ENG = "<div class='text'>Before an enemy ship in your <img class='inline-img' src='img/bulls.png'> is dealt a facedown damage card, you may spend 1 <img class='inline-img' src='img/fo.png'>. If you do, that damage card is dealt face up instead.</div>" }
D.pilots[492] = { name_FRA = "Whirlwind", name_ENG = "Whirlwind", id = 491, max_per_squad = 1, faction = "First_Order_Specialists", ship = "TIE/wi Whisper Modified Interceptor", charge = {0}, force = 0, shipId = 75, skill = 3, points = 11, ability_FRA = "<div class='text'>Avant de vous engager, vous pouvez retirer n'importe quel nombre de marqueurs de brouillage, puis vous pouvez gagner 1 marqueur de concentration pour chaque vaisseau ennemi qui vous a dans son <img class='inline-img' src='img/attackF.png'>.</div>", ability_ENG = "<div class='text'>Before you engage, you may remove any number of jam tokens, then you may gain 1 focus token for each enemy ship that has you in its <img class='inline-img' src='img/attackF.png'>.</div>" }
D.pilots[493] = { name_FRA = "Wrath", name_ENG = "Wrath", id = 492, max_per_squad = 1, faction = "First_Order_Specialists", ship = "TIE/wi Whisper Modified Interceptor", charge = {0}, force = 0, shipId = 75, skill = 5, points = 12, ability_FRA = "<div class='text'>Après avoir effectué une attaque <img class='inline-img' src='img/bulls.png'>, si vous avez au moins 1 marqueur rouge ou orange, vous pouvez effectuer une attaque bonus contre une cible différente.</div>", ability_ENG = "<div class='text'>After you perform a <img class='inline-img' src='img/bulls.png'> attack, if you have 1 or more red or orange tokens, you may perform a bonus attack against a different target.</div>" }
D.pilots[494] = { name_FRA = "Nightfall", name_ENG = "Nightfall", id = 493, max_per_squad = 1, faction = "First_Order_Specialists", ship = "TIE/wi Whisper Modified Interceptor", charge = {0}, force = 0, shipId = 75, skill = 4, points = 11, ability_FRA = "<div class='text'>Après avoir entièrement exécuté une manœuvre ou effectué une action <img class='inline-img' src='img/Bo W.png'>, chaque vaisseau que vous avez traversé gagne 2 jetons brouillage.</div>", ability_ENG = "<div class='text'>After you fully execute a maneuver or perform a <img class='inline-img' src='img/Bo W.png'> action, each ship you moved through gains 2 jam tokens.</div>" }
D.pilots[495] = { name_FRA = "Agent Tierny", name_ENG = "Agent Tierny", id = 494, max_per_squad = 1, faction = "First_Order_Specialists", ship = "Xi-class Light Shuttle", charge = {0}, force = 0, shipId = 66, skill = 3, points = 11, ability_FRA = "<div class='text'>Mise En Place : après avoir placé les forces, vous devez assigner la condition 'Confiance Brisée' à un vaisseau ennemi.</div>", ability_ENG = "<div class='text'>Setup: After placing forces, you must assign the 'Broken Trust' condition to an enemy ship.</div>" }
D.pilots[496] = { name_FRA = "Agent Terex", name_ENG = "Agent Terex", id = 495, max_per_squad = 1, faction = "First_Order_Specialists", ship = "Xi-class Light Shuttle", charge = {0}, force = 0, shipId = 66, skill = 3, points = 9, ability_FRA = "<div class='text'>Mise en Place : après avoir placé les forces, choisissez n’importe quel nombre de vos améliorations équipées <img class='inline-img' src='img/Illicit.png'> et équipez-les sur des vaisseaux alliés. Chaque vaisseau ne peut se voir assigner que 1 seule amélioration par ce biais.</div>", ability_ENG = "<div class='text'>Setup: After placing forces, choose any number of your equipped <img class='inline-img' src='img/Illicit.png'> upgrades and equip them to friendly ships. Each ship can be assigned only 1 <img class='inline-img' src='img/Illicit.png'> this way.</div>" }
D.pilots[497] = { name_FRA = "Commandante Malarus", name_ENG = "Commander Malarus", id = 496, max_per_squad = 1, faction = "First_Order_Specialists", ship = "Xi-class Light Shuttle", charge = {0}, force = 0, shipId = 66, skill = 5, points = 10, ability_FRA = "<div class='text'>Tant qu’un vaisseau allié à portée 0–2 effectue une attaque principale, s’il a au moins 1 résultat vierge, il doit gagner 1 marqueur de contrainte pour relancer 1 résultat vierge, si possible (faites-le avant l’étape « Modifier les dés de défense »).</div>", ability_ENG = "<div class='text'>While a friendly ship at range 0-2 performs a primary attack, if it has 1 or more blank results, that ship must gain 1 strain token to reroll 1 blank result, if able (Before the Step 'Modify Defense dice').</div>" }
D.pilots[498] = { name_FRA = "Gideon Hask", name_ENG = "Gideon Hask", id = 497, max_per_squad = 1, faction = "First_Order_Specialists", ship = "Xi-class Light Shuttle", charge = {0}, force = 0, shipId = 66, skill = 4, points = 9, ability_FRA = "<div class='text'>Tant que vous ou un petit vaisseau allié à portée 0–2 effectuez une attaque principale contre un défenseur endommagé, si l’attaquant a lancé 2 dés d’attaque ou moins, il peut gagner 1 marqueur de contrainte pour lancer 1 dé d’attaque supplémentaire.</div>", ability_ENG = "<div class='text'>While you or a friendly small ship at range 0-2 performs a primary attack against a damaged defender, if the attacker rolled 2 or fewer attack dice, it may gain 1 strain token to roll 1 additional attack die.</div>" }
D.pilots[499] = { name_FRA = "Major Vonreg", name_ENG = "Major Vonreg", id = 498, max_per_squad = 1, faction = "First_Order_Specialists", ship = "TIE/ba Interceptor", charge = {0}, force = 0, shipId = 65, skill = 6, points = 13, ability_FRA = "<div class='text'>A la fin de la phase d'activation, vous pouvez choisir 1 vaisseau ennemi dans votre <img class='inline-img' src='img/bulls.png'>. Ce vaisseau ennemi gagne 1 marqueur d’épuisement ou de contrainte (vous choisissez) .</div>", ability_ENG = "<div class='text'>At the end of activation Phase, you may choose 1 enemy ship in your <img class='inline-img' src='img/bulls.png'>. That ship gains 1 deplete or strain token of your choice.</div>" }
D.pilots[500] = { name_FRA = "Holo", name_ENG = "Holo", id = 499, max_per_squad = 1, faction = "First_Order_Specialists", ship = "TIE/ba Interceptor", charge = {0}, force = 0, shipId = 65, skill = 5, points = 13, ability_FRA = "<div class='text'>Au début de la phase d’engagement, vous devez transférer 1 de vos marqueurs à un autre vaisseau allié à portée 0-2.</div>", ability_ENG = "<div class='text'>At the start of the Engagement Phase, you must transfer 1 of your tokens to another friendly ship at range 0-2.</div>" }
D.pilots[501] = { name_FRA = "Ember", name_ENG = "Ember", id = 500, max_per_squad = 1, faction = "First_Order_Specialists", ship = "TIE/ba Interceptor", charge = {0}, force = 0, shipId = 65, skill = 4, points = 10, ability_FRA = "<div class='text'>Lorsqu'un vaisseau ennemi à portée 1 défend, il ne peut pas dépenser ses jetons concentration ou calcul.</div>", ability_ENG = "<div class='text'>While an enemy ship at range 1 defends, it cannot spend its focus or calculate tokens.</div>" }
D.pilots[502] = { name_FRA = "Marnia Un'la'na", name_ENG = "Marnia Un'la'na", id = 501, max_per_squad = 1, faction = "First_Order_Specialists", ship = "TIE/ba Interceptor", charge = {0}, force = 0, shipId = 65, skill = 4, points = 12, ability_FRA = "<div class='text'>Lorsque vous effectuez une attaque principale, vous pouvez dépenser votre vérouillage sur le défenseur et un jeton concentration pour modifier tous vos résultats en <img class='inline-img' src='img/crit.png'>.</div>", ability_ENG = "<div class='text'>While you perform a primary attack, you may spend your lock on the defender and a focus token to change all of your results to <img class='inline-img' src='img/crit.png'> results.</div>" }
D.pilots[503] = { name_FRA = "Ap'lek", name_ENG = "Ap'lek", id = 502, max_per_squad = 1, faction = "First_Order_Specialists", ship = "Oubliette Class Transport", charge = {1, "yellow", "0"}, force = 1, shipId = 94, skill = 3, points = 16, ability_FRA = "<div class='text'>Après avoir partiellement effectué une manoeuvre, vous pouvez dépenser 1 <img class='inline-img' src='img/charge.png'>. Dans ce cas, vous pouvez effectuer une action <img class='inline-img' src='img/Ja W.png'>.</div>", ability_ENG = "<div class='text'>After you partially execute a maneuver, you may spend 1 <img class='inline-img' src='img/charge.png'>. If you do, you may perform a <img class='inline-img' src='img/Ja W.png'> action.</div>" }
D.pilots[504] = { name_FRA = "Cardo", name_ENG = "Cardo", id = 503, max_per_squad = 1, faction = "First_Order_Specialists", ship = "Oubliette Class Transport", charge = {1, "yellow", "0"}, force = 1, shipId = 94, skill = 1, points = 16, ability_FRA = "<div class='text'>Au début de la phase d'engagement, vous pouvez dépenser 1 <img class='inline-img' src='img/charge.png'>. Dans ce cas, vous pouvez choisir 1 vaisseau à portée 0. Ce vaisseau reçoit un jeton tractage.</div>", ability_ENG = "<div class='text'>At the start of engagement phase, you may spend 1 <img class='inline-img' src='img/charge.png'>. If you do, you may choose 1 ship at range 0. That ship gains 1 tractor token.</div>" }
D.pilots[505] = { name_FRA = "Vikrul", name_ENG = "Vikrul", id = 504, max_per_squad = 1, faction = "First_Order_Specialists", ship = "Oubliette Class Transport", charge = {1, "yellow", "0"}, force = 1, shipId = 94, skill = 2, points = 16, ability_FRA = "<div class='text'>A la fin de l'étape 'Annuler les résultats', lorsque vous infligez un dégat <img class='inline-img' src='img/crit.png'>, vous pouvez dépenser 1 <img class='inline-img' src='img/charge.png'> pour annuler ce <img class='inline-img' src='img/crit.png'> pour infliger à la place 1 jeton ion.</div>", ability_ENG = "<div class='text'>At the end of Neutralize Results Step, when you deal a <img class='inline-img' src='img/crit.png'> damage, you may spend 1 <img class='inline-img' src='img/charge.png'> to cancel that <img class='inline-img' src='img/crit.png'> to deal 1 ion token instead</div>" }
D.pilots[506] = { name_FRA = "Kuruk", name_ENG = "Kuruk", id = 505, max_per_squad = 1, faction = "First_Order_Specialists", ship = "Oubliette Class Transport", charge = {1, "yellow", "0"}, force = 1, shipId = 94, skill = 4, points = 16, ability_FRA = "<div class='text'>Après qu'un vaisseau ennemi a effectué une manoeuvre, s'il est à portée 1 dans votre <img class='inline-img' src='img/attackF.png'>, vous pouvez dépenser 1 <img class='inline-img' src='img/charge.png'>. Dans ce cas, vous pouvez effectuer une attaque bonus avec 2 dé d'attaque. Si elle touche, annulez tous les résultats et infligez 1 jeton désarmement au défenseur à la place.</div>", ability_ENG = "<div class='text'>After an enemy ship executes a maneuver, if it is at range 1 in your <img class='inline-img' src='img/attackF.png'>, you may spend 1 <img class='inline-img' src='img/charge.png'>. If you do you may perform a bonus attack with 2 attack dice. If it hits, cancel all results, and deal 1 weapon disabled token to the defender instead.</div>" }
D.pilots[507] = { name_FRA = "Arliz Hadrassian", name_ENG = "Arliz Hadrassian", id = 506, max_per_squad = 1, faction = "First_Order_Specialists", ship = "BTL-A4 Y-wing", charge = {0}, force = 0, shipId = 1, skill = 4, points = 9, ability_FRA = "<div class='text'>Tant que vous effectuez une attaque <img class='inline-img' src='img/attackF.png'>, si vous êtes endommagé, vous pouvez changer 1 de vos résultats <img class='inline-img' src='img/Fo W.png'> en <img class='inline-img' src='img/crit.png'>.<br>Lorsque vous défendez, si vous êtes endommagé, vous devez changer 1 de vos résultats <img class='inline-img' src='img/Fo W.png'> en un résultat vierge (faites-le avant l’étape « Modifier les dés de défense »).</div>", ability_ENG = "<div class='text'>While you perform a <img class='inline-img' src='img/attackF.png'> attack, if you are damaged, before the Modify Dice step, you may change 1 of your <img class='inline-img' src='img/Fo W.png'> results to a <img class='inline-img' src='img/crit.png'> result.<br>While you defend, if you are damaged, you must change 1 of your <img class='inline-img' src='img/Fo W.png'> results to a blank result.</div>" }
D.pilots[508] = { name_FRA = "Padric", name_ENG = "Padric", id = 507, max_per_squad = 1, faction = "First_Order_Specialists", ship = "BTL-A4 Y-wing", charge = {0}, force = 0, shipId = 1, skill = 3, points = 8, ability_FRA = "<div class='text'>Après qu’un engin allié a explosé, chaque vaisseau ennemi à portée 0–1 de cet engin gagne 1 jeton contrainte.</div>", ability_ENG = "<div class='text'>After a friendly device detonates, each enemy ship at range 0-1 of that device gains 1 strain token.</div>" }
D.pilots[509] = { name_FRA = "Leema Kai", name_ENG = "Leema Kai", id = 508, max_per_squad = 1, faction = "First_Order_Specialists", ship = "BTL-A4 Y-wing", charge = {0}, force = 0, shipId = 1, skill = 5, points = 10, ability_FRA = "<div class='text'>Avant de vous engager, si vous êtes dans aucun <img class='inline-img' src='img/attackF.png'> de vaisseaux ennemis, vous pouvez verrouiller un vaisseau ennemi dans votre <img class='inline-img' src='img/F180.png'>.</div>", ability_ENG = "<div class='text'>Before you engage, if you are not in any enemy ship's <img class='inline-img' src='img/attackF.png'>, you may acquire a lock on an enemy ship in your <img class='inline-img' src='img/F180.png'>.</div>" }
