D.pilots[511] = { name_FRA = "Moff Gideon", name_ENG = "Moff Gideon", id = 510, max_per_squad = 1, faction = "Imperial_Remnants", ship = "TIE/ln Fighter", charge = {2, "yellow", "+"}, force = 0, shipId = 1, skill = 4, points = 9, ability_FRA = "<div class='text'>Tant qu'un vaisseau ennemi à portée 1-3 défend, avant de lancer les dés d'attaque vous pouvez dépenser 1 <img class='inline-img' src='img/charge.png'> et choisir un vaisseau allié à portée 0-1 du défenseur. Dans ce cas, les dés de défense ne peuvent pas être modifiés lors de cette attaque et le vaisseau allié choisi gagne 1 marqueur de contrainte.</div>", ability_ENG = "<div class='text'>While an enemy ship at range 1-3 defends, before attack dice are rolled, you may spend 1 charge and choose a friendly ship at range 0-1 of the defender. If you do, defense dice cannot be modified during this attack and the chosen friendly ship gains 1 strain token.</div>" }
D.pilots[512] = { name_FRA = "Va-t-en-guerre du BSI", name_ENG = "ISB Jingoist", id = 511, max_per_squad = 2, faction = "Imperial_Remnants", ship = "TIE/ln Fighter", charge = {0}, force = 0, shipId = 1, skill = 4, points = 8, ability_FRA = "<div class='text'>Avant de vous engager, vous pouvez choisir 1 vaisseau ennemi dans votre <img class='inline-img' src='img/attackF.png'> à portée 0-1. Dans ce cas, il gagne 1 marqueur d'épuisement ou de contrainte (vous choisissez) à moins qu'il ne choisisse de retirer 1 marqueur vert.</div>", ability_ENG = "<div class='text'>Before you engage, you may choose 1 enemy ship in your <img class='inline-img' src='img/attackF.png'> at range 0-1. If you do, that ship gains 1 deplete or strain token of your choice unless it chooses to remove 1 green token.</div>" }
