D.pilots[518] = { name_FRA = "Baylan Skoll", name_ENG = "Baylan Skoll", id = 517, max_per_squad = 1, faction = "Imperial_Remnants", ship = "ETA Class Shuttle", charge = {0}, force = 2, shipId = 98, skill = 5, points = 13, ability_FRA = "<div class='text'>Avant de vous activer, vous pouvez dépenser 1 <img class='inline-img' src='img/fo.png'> . Dans ce cas, votre adversaire doit deviner votre manoeuvre.<br>Si sa déduction est correcte, vous devez changer votre manoeuvre et perdre 1 <img class='inline-img' src='img/fo.png'>.<br>Si sa déduction est fausse, un vaisseau ennemi à portée 0-2 reçoit un jeton contrainte et récupérez 1 <img class='inline-img' src='img/fo.png'>.</div>", ability_ENG = "<div class='text'>Before you activate, you may spend 1 <img class='inline-img' src='img/fo.png'>. If you do, your opponent has to guess your maneuver.<br>If his guess is right, you must change your maneuver's dial and lose 1 <img class='inline-img' src='img/fo.png'> .<br>If his guess is wrong, an enemy ship at range 0-2 gains 1 strain token and you recover 1 <img class='inline-img' src='img/fo.png'>.</div>" }
