D.pilots[528] = { name_FRA = "Night Troopers", name_ENG = "Night Troopers", id = 527, max_per_squad = 1, faction = "Imperial_Remnants", ship = "Commando Team", charge = {1, "yellow", "0"}, force = 0, shipId = 81, skill = 1, points = 5, ability_FRA = "<div class='text'>Lorsque vous devriez recevoir votre 2ème carte de dégat, recevez à la place un jeton désarmement. Si votre charge est active, votre adversaire reçoit les PO comme si vous étiez détruit, puis retournez votre charge.</div>", ability_ENG = "<div class='text'>When you would take your second damage card, gain 1 disarm token instead. If your charge is active, your opponent gains PO as if you were destroyed, then flip your charge.</div>" }
