D.pilots[561] = { name_FRA = "Padme Amidala", name_ENG = "Padme Amidala", id = 560, max_per_squad = 1, faction = "Naboo_Defense_Force", ship = "J-Type Star Skiff", charge = {0}, force = 0, shipId = 99, skill = 2, points = 17, ability_FRA = "<div class='text'>Tant qu’un vaisseau ennemi dans votre <img class='inline-img' src='img/Farc.png'> défend ou effectue une attaque, ce vaisseau ennemi ne peut modifier que 1 seul résultat <img class='inline-img' src='img/Fo W.png> (les autres résultats peuvent toujours être modifiés).</div>", ability_ENG = "<div class='text'>While an enemy ship in your <img class='inline-img' src='img/Farc.png'> defends or performs an attack, that ship can modify only 1 <img class='inline-img' src='img/Fo W.png> result (other results can still be modified).</div>" }
D.pilots[562] = { name_FRA = "Qui-Gon Jinn", name_ENG = "Qui-Gon Jinn", id = 561, max_per_squad = 1, faction = "Naboo_Defense_Force", ship = "ETA Class Shuttle", charge = {0}, force = 3, shipId = 98, skill = 3, points = 14, ability_FRA = "<div class='text'>Lorsqu'un vaisseau allié à portée 0-1 devrait recevoir un jeton stress, vous pouvez dépenser 1 <img class='inline-img' src='img/fo.png>. Dans ce cas, ce jeton stress est défaussé.</div>", ability_ENG = "<div class='text'>When a friendly ship at range 0-1 would receive a stress token, you may spend 1 <img class='inline-img' src='img/fo.png>. If you do, this stress token is discarded.</div>" }
D.pilots[563] = { name_FRA = "Anakin Skywalker", name_ENG = "Anakin Skywalker", id = 562, max_per_squad = 1, faction = "Naboo_Defense_Force", ship = "ETA Class Shuttle", charge = {0}, force = 3, shipId = 98, skill = 4, points = 13, ability_FRA = "<div class='text'>Avant de révéler votre manoeuvre, vous pouvez dépenser 1 <img class='inline-img' src='img/fo.png'> pour faire un tonneau (ce n'est pas une action).</div>", ability_ENG = "<div class='text'>Before you reveal your maneuver, you may spend 1 <img class='inline-img' src='img/fo.png'> to barrel roll (this is not an action).</div>" }
D.pilots[564] = { name_FRA = "Obi-Wan Kenobi", name_ENG = "Obi-Wan Kenobi", id = 563, max_per_squad = 1, faction = "Naboo_Defense_Force", ship = "ETA Class Shuttle", charge = {0}, force = 3, shipId = 98, skill = 5, points = 13, ability_FRA = "<div class='text'>Après qu'un vaisseau allié à portée 0-2 a dépensé un jeton de concentration, vous pouvez 1<img class='inline-img' src='img/fo.png'>. Dans ce cas, ce vaisseau reçoit 1 jeton de concentration.</div>", ability_ENG = "<div class='text'>After a friendly ship at range 0-2 spends a focus token, you may spend 1 <img class='inline-img' src='img/fo.png'>. If you do, that ship gains 1 focus token.</div>" }
D.pilots[565] = { name_FRA = "Jar-Jar Binks", name_ENG = "Jar-Jar Binks", id = 564, max_per_squad = 1, faction = "Naboo_Defense_Force", ship = "ETA Class Shuttle", charge = {0}, force = 0, shipId = 98, skill = 1, points = 10, ability_FRA = "<div class='text'>Lorsque vous lancez des dés (au moins 2 lors du lancer), si tous vos résultats sont vierges, transformez les tous en résultats <img class='inline-img' src='img/crit.png'> / <img class='inline-img' src='img/Ev W.png'>.</div>", ability_ENG = "<div class='text'>When you roll dice (at least 2 during the roll), if all your results are blank, modify all of them into <img class='inline-img' src='img/crit.png'> / <img class='inline-img' src='img/Ev W.png'> results.</div>" }
D.pilots[566] = { name_FRA = "Rhys Dallows", name_ENG = "Rhys Dallows", id = 565, max_per_squad = 1, faction = "Naboo_Defense_Force", ship = "NB-1S Royal Bomber", charge = {1, "yellow", "+"}, force = 0, shipId = 100, skill = 5, points = 12, ability_FRA = "<div class='text'>Lorsqu'un engin à portée 0-2 explose, vous pouvez dépenser 1 <img class='inline-img' src='img/charge.png'> et choisir un vaisseau à portée 0-1 de cet engin. Dans ce cas, ce vaisseau reçoit 1 jeton contrainte.</div>", ability_ENG = "<div class='text'>When a payload detonates at range 0-2, you may spend 1 <img class='inline-img' src='img/charge.png'> and choose a ship at range 0-1 of this payload. If you do, this ship receive 1 strain token.</div>" }
D.pilots[567] = { name_FRA = "Essara Till", name_ENG = "Essara Till", id = 566, max_per_squad = 1, faction = "Naboo_Defense_Force", ship = "NB-1S Royal Bomber", charge = {0}, force = 0, shipId = 100, skill = 4, points = 11, ability_FRA = "<div class='text'>Lorsqu'un engin à portée 0-1 explose, vous pouvez effectuer une action <img class='inline-img' src='img/Br W.png'> ou <img class='inline-img' src='img/Bo W.png'>. Si vous deviez subir les effets de cet engin, vous pouvez recevoir 2 jetons stress pour les ignorer à la place.</div>", ability_ENG = "<div class='text'>When a payload at range 0-1 detonates, you may perform a <img class='inline-img' src='img/Br W.png'> or <img class='inline-img' src='img/Bo W.png'> action. If you had to suffer the effects of this payload, you may gain 2 stress tokens to ignore those effects instead.</div>" }
D.pilots[568] = { name_FRA = "Arven Wendik", name_ENG = "Arven Wendik", id = 567, max_per_squad = 1, faction = "Naboo_Defense_Force", ship = "NB-1S Royal Bomber", charge = {0}, force = 0, shipId = 100, skill = 3, points = 10, ability_FRA = "<div class='text'>Lorsque vous déchargez un engin, vous pouvez accélérer. Puis, vous pouvez recevoir un jeton contrainte. Dans ce cas, tournez votre vaisseau de 180°.</div>", ability_ENG = "<div class='text'>When you unload a payload, you may boost. Then, you may receive 1 strain token. If you do, rotate your ship 180°.</div>" }
D.pilots[569] = { name_FRA = "Rya Kirsch", name_ENG = "Rya Kirsch", id = 568, max_per_squad = 1, faction = "Naboo_Defense_Force", ship = "NB-1S Royal Bomber", charge = {0}, force = 0, shipId = 100, skill = 4, points = 10, ability_FRA = "<div class='text'>Vous pouvez décharger les engins en les lançant avec le gabarit de vitesse 1 <img class='inline-img' src='img/manSt2.png'>.</div>", ability_ENG = "<div class='text'>You may unload payloads by launching them with the speed 1 <img class='inline-img' src='img/manSt2.png'> template.</div>" }
D.pilots[570] = { name_FRA = "Vana Sage", name_ENG = "Vana Sage", id = 569, max_per_squad = 1, faction = "Naboo_Defense_Force", ship = "CloakShape Fighter", charge = {0}, force = 0, shipId = 101, skill = 5, points = 11, ability_FRA = "<div class='text'>Après avoir entièrement effectué une manoeuvre avancée, vous pouvez recevoir un jeton de concentration.</div>", ability_ENG = "<div class='text'>After you fully execute an advanced maneuver, you may gain 1 focus token.</div>" }
D.pilots[571] = { name_FRA = "Reti", name_ENG = "Reti", id = 570, max_per_squad = 1, faction = "Naboo_Defense_Force", ship = "CloakShape Fighter", charge = {0}, force = 0, shipId = 101, skill = 2, points = 9, ability_FRA = "<div class='text'>Après avoir subi un dégat <img class='inline-img' src='img/crit.png'>, vous pouvez effectuer une action, même si vous êtes stressé.</div>", ability_ENG = "<div class='text'>After you suffer a <img class='inline-img' src='img/charge.png'> damage, you may perform an action, even when stressed.</div>" }
D.pilots[572] = { name_FRA = "Adela Tyché", name_ENG = "Adela Tyché", id = 571, max_per_squad = 1, faction = "Naboo_Defense_Force", ship = "CloakShape Fighter", charge = {0}, force = 0, shipId = 101, skill = 2, points = 9, ability_FRA = "<div class='text'>Après avoir exécuté partiellement une manoeuvre avancée, vous pouvez repositionner votre vaisseau en le plaçant à portée 0 du vaisseau qui a gêné la manoeuvre, vers n'importe quelle direction.</div>", ability_ENG = "<div class='text'>After you partially execute an advanced maneuver, you may reposition your ship by placing it at range 0 from the ship that blocked your maneuver, facing any direction.</div>" }
D.pilots[573] = { name_FRA = "Mercious Bragg", name_ENG = "Mercious Bragg", id = 572, max_per_squad = 1, faction = "Naboo_Defense_Force", ship = "CloakShape Fighter", charge = {0}, force = 0, shipId = 101, skill = 3, points = 9, ability_FRA = "<div class='text'>Lorsque vous effectuez une attaque <img class='inline-img' src='img/Missile.png'>, après la phase 'annuler les résultats', si l'attaque touche, vous pouvez ajouter 1 résultat <img class='inline-img' src='img/crit.png'>.</div>", ability_ENG = "<div class='text'>When you perform a <img class='inline-img' src='img/Missile.png'> attack, after the 'Cancel results' phase, if the attack hits, you may add 1 <img class='inline-img' src='img/crit.png'> result.</div>" }
D.pilots[574] = { name_FRA = "Capitaine Nym", name_ENG = "Captain Nym", id = 573, max_per_squad = 1, faction = "Naboo_Defense_Force", ship = "Scurrg H-6 Bomber", force = 0, shipId = 37, skill = 5, charge = {1, "+"}, points = 14, ability_FRA = "<div class='text'>Avant qu’un engin allié n’explose, vous pouvez dépenser 1 <img class='inline-img' src='img/charge.png'> pour l’empêcher d’exploser.<br>Lorsque vous vous défendez contre une attaque obstruée par une bombe ou une mine, lancez 1 dé de défense supplémentaire.</div>", ability_ENG = "<div class='text'>Before a friendly device detonates, you may spend 1 <img class='inline-img' src='img/charge.png'> to prevent its detonation.<br>While you defend against an attack obstructed by a device, roll 1 additional defense die." }
D.pilots[575] = { name_FRA = "Sol Sixxa", name_ENG = "Sol Sixxa", id = 574, max_per_squad = 1, faction = "Naboo_Defense_Force", ship = "Scurrg H-6 Bomber", charge = {0}, force = 0, shipId = 37, skill = 3, points = 12, ability_FRA = "<div class='text'>Lorsque vous devez larguer un engin avec le gabarit 1<img class='inline-img' src='img/manSt2.png'>, vous pouvez le larguer en utilisant n’importe lequel des gabarit de vitesse 1.</div>", ability_ENG = "<div class='text'>When you would drop a device with the 1<img class='inline-img' src='img/manSt2.png'> template, you may drop it using any speed 1 template instead</div>" }
D.pilots[576] = { name_FRA = "Revenant de Lok", name_ENG = "Lok Revenant", id = 575, faction = "Naboo_Defense_Force", max_per_squad = 8, ship = "Scurrg H-6 Bomber", charge = {0}, force = 0, shipId = 37, skill = 2, points = 11 }
D.pilots[577] = { name_FRA = "Jinkins", name_ENG = "Jinkins", id = 576, max_per_squad = 1, faction = "Naboo_Defense_Force", ship = "Scurrg H-6 Bomber", force = 0, shipId = 37, skill = 1, charge = {1, "+"}, points = 12, ability_FRA = "<div class='text'>Lorsque vous larguez ou lancez une bombe, placez un marqueur « Puissance » dessus. Lorsqu’elle explose, augmentez la portée de l’explosion de 1.</div>", ability_ENG = "<div class='text'>While you drop or launch a bomb, place a 'power' token on it. When a bomb with a 'power' token detonates, increase its effect range by 1.</div>" }
D.pilots[578] = { name_FRA = "Protoype Arakyd", name_ENG = "Arakyd Prototype", id = 577, max_per_squad = 2, faction = "Trade_Federation", ship = "Scarab-Class Droid Fighter", force = 0, shipId = 102, skill = 3, charge = {1, "yellow", "0"}, points = 7, ability_FRA = "<div class='text'>Pendant la phase système, vous pouvez dépenser ou récupérer votre charge.<br><img class='inline-img' src='img/charge.png'> active : Lorque vous prenez 1 dégat, recevez 1 jeton calcul.<br><img class='inline-img' src='img/charge.png'> inactive : Lorsque vous attaquez, vous pouvez dépenser 1 jeton calcul pour modifier un résultat vierge en <img class='inline-img' src='img/hit.png'>.</div>", ability_ENG = "<div class='text'>During System Phase, you may spend or recover your charge.<br><img class='inline-img' src='img/charge.png'> active : When you receive a damage, gain 1 calculate token.<br><img class='inline-img' src='img/charge.png'> inactive : While you attack, you may spend 1 calculate token to modify 1 blank result into a <img class='inline-img' src='img/hit.png'> result.</div>" }
