D.pilots[580] = { name_FRA = "Poggle le Bref", name_ENG = "Poggle the Lesser", id = 579, max_per_squad = 1, faction = "Separatist_Government", ship = "Sheathipede-Class Shuttle", force = 0, shipId = 41, skill = 5, charge = {0}, points = 10, ability_FRA = "<div class='text'>Lorsque vous faites une action de coordination ou que vous êtes coordonné, si cela échoue, vous pouvez effectuer un tonneau et réessayer la même coordination sans changer les cibles.</div>", ability_ENG = "<div class='text'>When you perform a coordination action or you are being coordinated, if it fails, you may perform a barrel roll and try again the same coordination without changing the targets.</div>" }
D.pilots[581] = { name_FRA = "Shu Mai", name_ENG = "Shu Mai", id = 580, max_per_squad = 1, faction = "Separatist_Government", ship = "Sheathipede-Class Shuttle", force = 0, shipId = 41, skill = 3, charge = {0}, points = 9, ability_FRA = "<div class='text'>Lorsqu'un vaisseau allié à portée 0-2 dans votre arc de tir attaque ou défend, vous pouvez choisir un autre vaisseau calculateur dans votre arc de tir opposé. Dans ce cas, le premier vaisseau peut utiliser un jeton calcul du deuxième vaisseau comme si c'était le sien.</div>", ability_ENG = "<div class='text'>When a friendly ship in your firing arc at range 0-2 performs an attack or defends, you may choose another calculating ship in your opposite firing arc. If you do, the first ship may use a calculate token from the second ship as its own.</div>" }
D.pilots[582] = { name_FRA = "San Hill", name_ENG = "San Hill", id = 581, max_per_squad = 1, faction = "Separatist_Government", ship = "Sheathipede-Class Shuttle", force = 0, shipId = 41, skill = 4, charge = {0}, points = 8, ability_FRA = "<div class='text'>Lorsque vous effectuez une attaque qui touche, vous pouvez effectuer une action de coordination.</div>", ability_ENG = "<div class='text'>When you perform an attack that hits, you may perform a coordination action.</div>" }
