D.pilots[589] = { name_FRA = "Osi Sobeck", name_ENG = "Osi Sobeck", id = 588, max_per_squad = 1, faction = "Separatist_Government", ship = "Droch-class Boarding Ship", force = 0, shipId = 104, skill = 4, charge = {0}, points = 9, ability_FRA = "<div class='text'>Lorsqu'un vaisseau ennemi termine sa manoeuvre dans votre <img class='inline-img' src='img/Tarc.png'> à portée 1, vous pouvez effectuer une attaque principale bonus. Vos dés d'attaque ne peuvent pas être modifiés lors de cette attaque.</div>", ability_ENG = "<div class='text'>When an enemy ship finishes its maneuver in your <img class='inline-img' src='img/Tarc.png'> at range 1, you may perform a bonus primary attack. Your attack dice cannot be modified during this attack.</div>" }
