D.pilots[601] = { name_FRA = "Gev Hessan", name_ENG = "Gev Hessan", id = 600, max_per_squad = 1, faction = "Hutt_Cartel", ship = "HH-87 Starhopper", force = 0, shipId = 106, skill = 4, charge = {1, "red", 0}, points = 8, ability_FRA = "<div class='text'>Au début de la phase d'engagement, vous pouvez choisir un vaisseau à portée 0. Dans ce cas, choisissez une <img class='inline-img' src='img/charge.png'> parmi les améliorations de ce vaisseau et épuisez la. Récupérez 1 <img class='inline-img' src='img/charge.png'> de votre pilote.<br>ACTION : Larguez un 'Largage de Cagaison' (considéré comme un débris) avec le gabari 1<img class='inline-img' src='img/manSt2.png'>.</div>", ability_ENG = "<div class='text'>At the beginning of Engagment Phase, you may choose a ship at range 0. If you do, choose 1 <img class='inline-img' src='img/charge.png'> among this ship's upgrades and spend it. Recover 1 <img class='inline-img' src='img/charge.png'> from your pilot.<br>ACTION : Drop 1 'Rigged Cargo Chute' (considered as a debris) with the 1<img class='inline-img' src='img/manSt2.png'> template.</div>" }
D.pilots[602] = { name_FRA = "Deva Lompop", name_ENG = "Deva Lompop", id = 601, max_per_squad = 1, faction = "Hutt_Cartel", ship = "HH-87 Starhopper", charge = {2, "red", 0}, force = 0, shipId = 106, skill = 3, points = 8, ability_FRA = "<div class='text'>Lorsqu'un vaisseau ennemi est détruit, récupérez 1 <img class='inline-img' src='img/charge.png'> de votre pilote. Lorsque vos 2 charges sont actives, lancez 1 dé de plus à chaque fois que vous lancez des dés.</div>", ability_ENG = "<div class='text'>When an enemy ship is destroyed, recover 1 <img class='inline-img' src='img/charge.png'> from your pilot. When your 2 charges are active, roll 1 additional die each time you roll any dice.</div>" }
D.pilots[603] = { name_FRA = "Rel Keteris", name_ENG = "Rel Keteris", id = 602, max_per_squad = 1, faction = "Hutt_Cartel", ship = "HH-87 Starhopper", force = 0, shipId = 106, skill = 3, charge = {2, "yellow", 0}, points = 7, ability_FRA = "<div class='text'>Après avoir entièrement exécuté une manoeuvre de vitesse 3-5, you pouvez dépenser 1 <img class='inline-img' src='img/charge.png'> pour effectuer une action <img class='inline-img' src='img/Sl W.png'>.</div>", ability_ENG = "<div class='text'>After you fully execute a speed 3-5 maneuver, you may spend 1 <img class='inline-img' src='img/charge.png'> to perform a <img class='inline-img' src='img/Sl W.png'> action.</div>" }
