D.pilots[605] = { name_FRA = "Han Solo", name_ENG = "Han Solo", id = 604, max_per_squad = 1, faction = "Rebel_Alliance", ship = "YT-1300 Light Freighter", charge = {0}, force = 0, shipId = 3, skill = 6, points = 19, ability_FRA = "<div class='text'>Tant que vous attaquez ou défendez, si l’attaque est obstruée par un obstacle, vous pouvez lancer un dé supplémentaire.<br>Si vous défendez ou attaquez en étant à portée 0 d'un obstacle, vous pouvez lancer 1 dé supplémentaire</div>", ability_ENG = "<div class='text'>While you defend or perform an attack, if the attack is obstructed by an obstacle, you may roll 1 additional die.<br>If you defend or perform an attack while being at range 0 of an obstacle, you may roll 1 additional die.</div>" }
D.pilots[606] = { name_FRA = "Chewbacca", name_ENG = "Chewbacca", id = 605, max_per_squad = 1, faction = "Rebel_Alliance", ship = "YT-1300 Light Freighter", force = 0, shipId = 3, skill = 4, charge = {1, "yellow", "+"}, points = 16, ability_FRA = "<div class='text'>Lorsque vous devriez recevoir une carte de dégât face visible, vous pouvez dépenser 1 <img class='inline-img' src='img/charge.png'> pour la recevoir face cachée à la place.</div>", ability_ENG = "<div class='text'>When you would receive a face up damage card, you may spend 1 <img class='inline-img' src='img/charge.png'> to receive it facedown instead.</div>" }
D.pilots[607] = { name_FRA = "Lega Fossang", name_ENG = "Lega Fossang", id = 606, max_per_squad = 1, faction = "Heroes_of_the_Resistance", ship = "BTA-NR2-W Y-wing", charge = {0}, force = 0, shipId = 107, skill = 4, points = 11, ability_FRA = "<div class='text'>Après avoir effectué une attaque, si le défenseur a reçu une carte de dégat face ouverte, le défenseur reçoit 1 jeton contrainte à moins qu'il ne choisisse 1 <img class='inline-img' src='img/charge.png'> non récupérable de l'une des améliorations et qu'il la perde.</div>", ability_ENG = "<div class='text'>After you perform an attack, if the defender was dealt a faceup damage card, the defender gains 1 strain token unless it chooses 1 non-recurring <img class='inline-img' src='img/charge.png'> from 1 of its equipped upgrades and loses that <img class='inline-img' src='img/charge.png'>.</div>" }
D.pilots[608] = { name_FRA = "Shasa Zaro", name_ENG = "Shasa Zaro", id = 607, max_per_squad = 1, faction = "Heroes_of_the_Resistance", ship = "BTA-NR2-W Y-wing", charge = {0}, force = 0, shipId = 107, skill = 3, points = 11, ability_FRA = "<div class='text'>Après avoir défendu, vous pouvez choisir un vaisseau allié dans votre <img class='inline-img' src='img/B180.png'> à portée 0-2 et 1 de vos jetons verts. Dans ce cas, ce vaisseau gagne un jeton équivalent.</div>", ability_ENG = "<div class='text'>After you defend, you may choose a friendly ship in your <img class='inline-img' src='img/B180.png'> at range 0-2 and 1 of your green tokens. If you do, that ship gains a matching token.</div>" }
D.pilots[609] = { name_FRA = "Aftab Ackbar", name_ENG = "Aftab Ackbar", id = 608, max_per_squad = 1, faction = "Heroes_of_the_Resistance", ship = "BTA-NR2-W Y-wing", charge = {0}, force = 0, shipId = 107, skill = 2, points = 10, ability_FRA = "<div class='text'>Après avoir executé une manoeuvre basique rouge ou effectué une action rouge, si vous avez exactement 1 jeton stress, vous pouvez gagner 1 jeton contrainte pour retirer ce jeton stress.</div>", ability_ENG = "<div class='text'>After you execute a red basic maneuver or perform a red action, if you have exactly 1 stress token, you may gain 1 strain token to remove that stress token.</div>" }
D.pilots[610] = { name_FRA = "C'ai Threnalli", name_ENG = "C'ai Threnalli", id = 609, max_per_squad = 1, faction = "Heroes_of_the_Resistance", ship = "BTA-NR2-W Y-wing", charge = {0}, force = 0, shipId = 107, skill = 2, points = 10, ability_FRA = "<div class='text'>Après avoir entièrement excuté une manoeuvre, si vous vous êtes déplacé à travers un vaisseau allié, vous pouvez effectuer une action <img class='inline-img' src='img/Ev W.png'>.</div>", ability_ENG = "<div class='text'>After you fully execute a maneuver, if you moved through a friendly ship, you may perform an <img class='inline-img' src='img/Ev W.png'> action.</div>" }
