D.pilots[636] = { name_FRA = "KRONOS-327", name_ENG = "KRONOS-327", id = 635, max_per_squad = 1, faction = "Agents_of_Chaos", ship = "G9 Rigger Freighter", charge = {0}, force = 0, shipId = 105, skill = 4, points = 7, ability_FRA = "<div class='text'>Au début de la phase d'engagement, vous pouvez dépenser 1 jeton calcul. Dans ce cas, choississez un vaisseau à portée 1 dans votre arc de tir. Ce vaisseau reçoit un jeton contrainte ou épuisement de votre choix.</div>", ability_ENG = "<div class='text'>At the begining of Engagement Phase, you may spend 1 calculate token. If you do, choose a ship in your firing arc at range 1. This ship receives 1 strain ou deplete token of your choice.</div>" }
D.pilots[637] = { name_FRA = "Ziro Desilijic Tiure", name_ENG = "Ziro Desilijic Tiure", id = 636, max_per_squad = 1, faction = "Agents_of_Chaos", ship = "G9 Rigger Freighter", charge = {0}, force = 0, shipId = 105, skill = 3, points = 8, ability_FRA = "<div class='text'>Lorsque vous êtes déclaré comme étant la cible d'une attaque, le vaisseau attaquant reçoit un jeton épuisement et un jeton contrainte.</div>", ability_ENG = "<div class='text'>When you are declared as the target of an attack, the attacking ship gains 1 deplete and 1 strain tokens.</div>" }
D.pilots[638] = { name_FRA = "4-A7", name_ENG = "4-A7", id = 637, max_per_squad = 1, faction = "Agents_of_Chaos", ship = "G9 Rigger Freighter", charge = {0}, force = 0, shipId = 105, skill = 3, points = 7, ability_FRA = "<div class='text'>Au début de la phase d'engagement, vous pouvez dépenser un jeton calcul. Dans ce cas, effectuez une action d'occultation.</div>", ability_ENG = "<div class='text'>At the beginning of Engagement Phase, you may spend 1 calculate token. If you do, perform a cloak action.</div>" }
D.pilots[639] = { name_FRA = "Darts D'Nar", name_ENG = "Darts D'Nar", id = 638, max_per_squad = 1, faction = "Agents_of_Chaos", ship = "YV-865 Aurore-Class Freighter", charge = {0}, force = 0, shipId = 110, skill = 5, points = 14, ability_FRA = "<div class='text'>Lorsque vous transférez un de vos jetons tractage à un vaisseau à portée 1, vous pouvez lui assigner 2 jetons tractage supplémentaires.</div>", ability_ENG = "<div class='text'>When you transfer 1 of your tractor tokens to a ship at range 1, you may assign it 2 additionnal tractor tokens.</div>" }
D.pilots[640] = { name_FRA = "Agruss", name_ENG = "Agruss", id = 639, max_per_squad = 1, faction = "Agents_of_Chaos", ship = "YV-865 Aurore-Class Freighter", charge = {0}, force = 0, shipId = 110, skill = 3, points = 12, ability_FRA = "<div class='text'>Lorsque vous vous renforcez, vous pouvez aussi choisir de vous renforcer à gauche ou à droite.</div>", ability_ENG = "<div class='text'>When you reinforce, you may also choose to reinforce the left and the right.</div>" }
D.pilots[641] = { name_FRA = "Savage Opress", name_ENG = "Savage Opress", id = 640, max_per_squad = 1, faction = "Agents_of_Chaos", ship = "YV-865 Aurore-Class Freighter", charge = {0}, force = 2, shipId = 110, skill = 4, points = 13, ability_FRA = "<div class='text'>Lorsque vous effectuez une attaque dans votre <img class='inline-img' src='img/Tarc.png'>, vous pouvez dépenser 1 <img class='inline-img' src='img/fo.png'>. Dans ce cas, ajoutez 1 résultat <img class='inline-img' src='img/Fo W.png'>.</div>", ability_ENG = "<div class='text'>When you perform an attack in your <img class='inline-img' src='img/Tarc.png'>, you may spend 1 <img class='inline-img' src='img/fo.png'>. If you do, add 1 <img class='inline-img' src='img/Fo W.png'> result.</div>" }
D.pilots[642] = { name_FRA = "Raney", name_ENG = "Raney", id = 641, max_per_squad = 1, faction = "Agents_of_Chaos", ship = "YV-865 Aurore-Class Freighter", charge = {0}, force = 0, shipId = 110, skill = 3, points = 12, ability_FRA = "<div class='text'>Lorsque vous utilisez votre capacité 'Dispositif Tracteur De Précision', vous pouvez orienter votre <img class='inline-img' src='img/Tarc.png'> vers l'arrière ou ne pas le déplacer. Dans ce cas, recevez 1 jeton stress.</div>", ability_ENG = "<div class='text'>When you use your 'Pinpoint Tractor Array' ability, you may move your <img class='inline-img' src='img/Tarc.png'> torwards the rear or not moving it at all. If you do, receive 1 stress token.</div>" }
D.pilots[643] = { name_FRA = "Esclavagiste Zyggerien", name_ENG = "Zyggerian Slaver", id = 642, max_per_squad = 8, faction = "Agents_of_Chaos", ship = "YV-865 Aurore-Class Freighter", charge = {0}, force = 0, shipId = 110, skill = 3, points = 11, ability_FRA = "<div class='text'></div>", ability_ENG = "<div class='text'></div>" }
D.pilots[644] = { name_FRA = "Anakin Skywalker", name_ENG = "Anakin Skywalker", id = 643, max_per_squad = 1, faction = "Jedi_Order", ship = "G9 Rigger Freighter", charge = {0}, force = 3, shipId = 105, skill = 6, points = 9, ability_FRA = "<div class='text'>Après avoir entièrement exécuté une manœuvre, si il y a un vaisseau ennemi dans votre <img class='inline-img' src='img/attackF.png'> à portée 0-1 ou dans votre <img class='inline-img' src='img/bulls.png'>, vous pouvez dépenser 1<img class='inline-img' src='img/fo.png'> pour retirer un marqueur de stress.</div>", ability_ENG = "<div class='text'>After you fully execute a maneuver, if there is an enemy ship in your <img class='inline-img' src='img/attackF.png'> at range 0-1 or in your <img class='inline-img' src='img/bulls.png'>, you may spend 1 <img class='inline-img' src='img/fo.png'> to remove 1 stress token.</div>" }
D.pilots[645] = { name_FRA = "Ahsoka Tano", name_ENG = "Ahsoka Tano", id = 644, max_per_squad = 1, faction = "Jedi_Order", ship = "G9 Rigger Freighter", charge = {0}, force = 1, shipId = 105, skill = 3, points = 8, ability_FRA = "<div class='text'><img class='inline-img' src='img/forcestat.png'> Après avoir entièrement exécuté une manoeuvre, vous pouvez choisir un vaisseau allié à portée 0-1 et dépenser 1 <img class='inline-img' src='img/fo.png'>. Ce vaisseau peut effectuer une action, même s'il est stressé.</div>", ability_ENG = "<div class='text'><img class='inline-img' src='img/forcestat.png'> After you fully execute a maneuver, you may choose a friendly ship at range 0-1 and spend 1 <img class='inline-img' src='img/fo.png'>. That ship may perform an action, even if it is stressed.</div>" }
D.pilots[646] = { name_FRA = "Beezer Fortuna", name_ENG = "Beezer Fortuna", id = 645, max_per_squad = 8, faction = "Partisans", ship = "YV-865 Aurore-Class Freighter", charge = {0}, force = 0, shipId = 110, skill = 4, points = 11, ability_FRA = "<div class='text'>Lorsqu'un vaisseau allié est détruit (retiré de la partie) suite à une attaque, si l'attaquant se trouve dans votre #Tarc#, les vaisseaux alliés à portée 0-2 de l'attaquant peuvent le vérouiller. </div>", ability_ENG = "<div class='text'>When a friendly ship is destroyed (removed frome the game) after an attack, if the attacking ship is in your #Tarc#, then friendly ships at range 0-2 of the attacker may acquire locks on him.</div>" }
D.pilots[647] = { name_FRA = "Arane Oreida", name_ENG = "Arane Oreida", id = 646, max_per_squad = 8, faction = "Partisans", ship = "YV-865 Aurore-Class Freighter", charge = {0}, force = 0, shipId = 110, skill = 2, points = 10, ability_FRA = "<div class='text'>Lorsque vous exécutez partiellement une manoeuvre, si vous êtes renforcé vers l'avant, vous pouvez choisir un vaisseau dans votre #Farc# à portée 0 et subir un dégat #hit#. Dans ce cas, ce vaisseau subit 1 dégat #hit#.</div>", ability_ENG = "<div class='text'>When you partially execute a maneuver, if you are reinforced to the front, you may choose a ship in your #Farc# at range 0 and suffer 1 #hit# damage. If you do, this ship suffers 1 #hit# damage.</div>" }
