D.pilots[650] = { name_FRA = "Saesee Tiin", name_ENG = "Saesee Tiin", id = 649, max_per_squad = 1, faction = "Jedi_Order", ship = "ETA Class Shuttle", charge = {0}, force = 2, shipId = 98, skill = 4, points = 11, ability_FRA = "Après qu’un vaisseau allié à portée 0-2 a révélé son cadran, vous pouvez dépenser 1 #fo#. Dans ce cas, réglez son cadran sur une autre manœuvre de même vitesse et de même difficulté.", ability_ENG = "After a friendly ship at range 0-2 reveals its dial, you may spend 1 #fo#. If you do, set its dial to another maneuver of the same speed and difficulty." }
