D.upgrades[23] = { name_FRA = "Artilleur Hors-Pair", name_ENG = "Hotshot Gunner", id = 22, slot = "Gunner", add_Data = {0}, force = 0, charge = {0}, effect_FRA = "Après avoir effectué une attaque de <img class='inline-img' src='img/Tarc.png'>, retirez un marqueur de concentration, de calcul, ou d’évasion du défenseur.", effect_ENG = "After you perform a <img class='inline-img' src='img/Tarc.png'> attack, remove a focus, calculate or evade token from the defender." }
