D.upgrades[25] = { name_FRA = "Artilleur Vétéran", name_ENG = "Veteran Gunner", id = 24, slot = "Gunner", add_Data = {0}, force = 0, charge = {0}, effect_FRA = "Après avoir effectué une attaque, vous pouvez effectuer une attaque bonus <img class='inline-img' src='img/Tarc.png'> ou <img class='inline-img' src='img/Cannon.png'>, avec une <img class='inline-img' src='img/Tarc.png'> ou un <img class='inline-img' src='img/Cannon.png'> que vous n’avez pas encore utilisé.", effect_ENG = "After you perform an attack, you may perform a bonus <img class='inline-img' src='img/Tarc.png'> or <img class='inline-img' src='img/Cannon.png'> attack, with a <img class='inline-img' src='img/Tarc.png'> or <img class='inline-img' src='img/Cannon.png'> you haven't used yet." }
D.upgrades[26] = { name_FRA = "Officier des Systèmes d'Armement", name_ENG = "Weapons Systems Officer", id = 25, add_Data = {0}, force = 0, charge = {0}, slot = "Gunner", effect_FRA = "Après avoir effectué une attaque, vous pouvez dépenser un marqueur vert ou recevoir un marqueur de stress pour verrouiller le défenseur.", effect_ENG = "After you perform an attack, you may spend a green token or receive a stress token to lock the defender." }
D.upgrades[27] = { name_FRA = "Ciblage Prioritaire Automatisé", name_ENG = "Automated Target Priority", id = 26, slot = "Tech", add_Data = {0}, force = 0, charge = {0}, effect_FRA = "Tant que vous effectuez une attaque, vous devez choisir un défenseur à la plus courte portée d’attaque valide.<br>Après avoir effectué une attaque qui a raté, placez 1 marqueur de calcul sur cette amélioration.<br>Avant de vous engager, vous pouvez retirer 1 marqueur de calcul de cette amélioration pour gagner le marqueur correspondant", effect_ENG = "While you perform an attack, you must choose a defender within the shortest valid attack range.<br>After you perform an attack, if it missed, place 1 calculate token on this upgrade.<br>Before you engage, you may remove 1 calculate token from this upgrade to gain 1 matching token." }
D.upgrades[28] = { name_FRA = "Analyseur de Modèles", name_ENG = "Pattern Analyzer", id = 27, slot = "Tech", add_Data = {0}, force = 0, charge = {0}, effect_FRA = "Tant que vous exécutez entièrement une manœuvre rouge, avant l’étape « Vérifier la difficulté », vous pouvez effectuer 1 action.", effect_ENG = "While you fully execute a red maneuver, before the 'check the difficulty' step, you may perform an action." }
D.upgrades[29] = { name_FRA = "Optiques Avancées", name_ENG = "Advanced Optics", id = 28, slot = "Tech", add_Data = {0}, force = 0, charge = {0}, effect_FRA = "Tant que vous effectuez une attaque, vous pouvez dépenser 1 marqueur de concentration pour changer 1 de vos résultats vierges en un résultat <img class='inline-img' src='img/hit.png'>.", effect_ENG = "While you attack, you may spend 1 focus token to modify 1 blank result into a <img class='inline-img' src='img/hit.png'> result." }
D.upgrades[30] = { name_FRA = "Synchroniseur Télémétrique", name_ENG = "Targeting Synchronizer", id = 29, slot = "Tech", add_Data = {0}, force = 0, charge = {0}, effect_FRA = "Tant qu’un vaisseau allié à portée 1–3 effectue une attaque contre une cible que vous avez verrouillée, ce vaisseau allié ignore le prérequis d’attaque <img class='inline-img' src='img/Lo W.png'>, <img class='inline-img' src='img/Fo W.png'> ou <img class='inline-img' src='img/Cc W.png'>.", effect_ENG = "While a friendly ship at range 1-3 perform an attack against a target you have locked, this friendly ship ignore the <img class='inline-img' src='img/Lo W.png'>, <img class='inline-img' src='img/Fo W.png'> or <img class='inline-img' src='img/Cc W.png'> attack condition" }
D.upgrades[31] = { name_FRA = "Missile Ionique", name_ENG = "Ion Missile", id = 30, slot = "Missile", add_Data = {0}, force = 0, charge = {1, "yellow", "0"}, effect_FRA = " Attaque (<img class='inline-img' src='img/Lo W.png'>): 3<img class='inline-img' src='img/attackF.png'> portée 2-3 : dépensez 1 <img class='inline-img' src='img/charge.png'>. Si cette attaque touche, dépensez 1 résultat <img class='inline-img' src='img/hit.png'> ou <img class='inline-img' src='img/crit.png'> pour faire subir 1 dégât <img class='inline-img' src='img/hit.png'> au défenseur. Tous les résultats <img class='inline-img' src='img/hit.png'>/<img class='inline-img' src='img/crit.png'> restants infligent des marqueurs ioniques au lieu des dégâts.", effect_ENG = " Attack (<img class='inline-img' src='img/Lo W.png'>): 3<img class='inline-img' src='img/attackF.png'> range 2-3 : spend 1 <img class='inline-img' src='img/charge.png'>. If this attack hits, spend 1 <img class='inline-img' src='img/hit.png'> or <img class='inline-img' src='img/crit.png'> result to inflict 1 <img class='inline-img' src='img/hit.png'> damage to the defender. All <img class='inline-img' src='img/hit.png'>/<img class='inline-img' src='img/crit.png'> remaining results inflict ion tokens instead of damage." }
D.upgrades[32] = { name_FRA = "Missile à Tête Chercheuse", name_ENG = "Homing Missile", id = 31, slot = "Missile", add_Data = {0}, force = 0, charge = {1, "yellow", "0"}, effect_FRA = " Attaque (<img class='inline-img' src='img/Lo W.png'>) : 2<img class='inline-img' src='img/attackF.png'> Portée 2-3 : dépensez 1 <img class='inline-img' src='img/charge.png'>. Après avoir lancé les dés d'attaque, annulez tous les résultats, et ajoutez 2 résultats <img class='inline-img' src='img/hit.png'>.", effect_ENG = " Attack (<img class='inline-img' src='img/Lo W.png'>): 2<img class='inline-img' src='img/attackF.png'> range 2-3 : spend 1 <img class='inline-img' src='img/charge.png'>. After attack dice are rolled, cancel all results, then add 2 <img class='inline-img' src='img/hit.png'> results." }
D.upgrades[33] = { name_FRA = "Missiles Groupés", name_ENG = "Cluster Missiles", id = 32, slot = "Missile", add_Data = {0}, force = 0, charge = {1, "yellow", "0"}, effect_FRA = " Attaque (<img class='inline-img' src='img/Lo W.png'>) : 3<img class='inline-img' src='img/attackF.png'> Portée 1-2 : Dépensez 1 <img class='inline-img' src='img/charge.png'>. Après avoir résolu l’attaque, vous pouvez choisir un autre vaisseau à portée 0-1 du défenseur. Dans ce cas, lancez 3 dés d’attaque : assignez autant de marqueurs de contrainte que de résultats <img class='inline-img' src='img/Fo W.png'>, puis le vaisseau ciblé doit se défendre en considérant les autres résultats comme un jet d’attaque.", effect_ENG = " Attack (<img class='inline-img' src='img/Lo W.png'>): 3<img class='inline-img' src='img/attackF.png'> range 1-2 : spend 1 <img class='inline-img' src='img/charge.png'>. After this attack, you may choose another ship at range 0-1 of the defender. If you do, roll 3 attack dice : assign to this ship as many strain tokens as <img class='inline-img' src='img/Fo W.png'> results, then this ship defends itself, considering the remaining results as a an attack." }
D.upgrades[34] = { name_FRA = "Roquettes de Barrage", name_ENG = "Barrage Rockets", id = 33, slot = "Missile", add_Data = {0}, force = 0, charge = {3, "yellow", "0"}, effect_FRA = "Attaque (<img class='inline-img' src='img/Fo W.png'>): 3<img class='inline-img' src='img/attackF.png'> Portée 2-3 : Dépensez 1 <img class='inline-img' src='img/charge.png'>. Si le défenseur est dans votre <img class='inline-img' src='img/bulls.png'>, vous pouvez dépenser 1 ou plusieurs <img class='inline-img' src='img/charge.png'> pour relancer autant de dés d’attaque.", effect_ENG = "Attack (<img class='inline-img' src='img/Fo W.png'>): 3<img class='inline-img' src='img/attackF.png'> range 2-3 : Spend 1 <img class='inline-img' src='img/charge.png'>. If the defender is in your <img class='inline-img' src='img/bulls.png'>, you may spend 1 or several <img class='inline-img' src='img/charge.png'> to reroll as many attack dice." }
D.upgrades[35] = { name_FRA = "Traceurs XX-23 S", name_ENG = "XX-23 S-Thread Tracers", id = 34, slot = "Missile", add_Data = {0}, force = 0, charge = {2, "yellow", "0"}, effect_FRA = "  Attaque (<img class='inline-img' src='img/Cc W.png'>, <img class='inline-img' src='img/Fo W.png'> ou <img class='inline-img' src='img/Lo W.png'>) : 3<img class='inline-img' src='img/attackF.png'> Portée 1-3 : dépensez 1 <img class='inline-img' src='img/charge.png'>. Si cette attaque touche, chaque vaisseau allié à portée 1–3 du défenseur peut verrouiller le défenseur. Puis annulez tous les résultats.", effect_ENG = "  Attack (<img class='inline-img' src='img/Cc W.png'>, <img class='inline-img' src='img/Fo W.png'> ou <img class='inline-img' src='img/Lo W.png'>) : 3<img class='inline-img' src='img/attackF.png'> range 1-3 : spend 1 <img class='inline-img' src='img/charge.png'>. If this attack hits, each friendly ship at range 1-3 of the defender may lock the defender. Then Cancel all results." }
D.upgrades[36] = { name_FRA = "Missile Harpon", name_ENG = "Harpoon Missile", id = 35, slot = "Missile", add_Data = {0}, force = 0, charge = {1, "yellow", "0"}, effect_FRA = " Attaque (<img class='inline-img' src='img/Fo W.png'>) : 3<img class='inline-img' src='img/attackF.png'> Portée 1-2 : Dépensez 1 <img class='inline-img' src='img/charge.png'>. Si l’attaque touche, annulez tous les résultats. Puis le défenseur reçoit une carte de dégât face cachée et autant de jetons tractage qu'il faudrait pour tracter votre vaisseau. (ex: si vous êtes un gros vaisseau, vous infligez 3 jetons tractage)", effect_ENG = " Attack (<img class='inline-img' src='img/Fo W.png'>) : 3<img class='inline-img' src='img/attackF.png'> range 1-2 : Spend 1 <img class='inline-img' src='img/charge.png'>. If the attack hits, cancel all results. Then the defender receive 1 facedown damage card and as many tractor tokens as necessary if you needed to tractor your own ship. (ex : if you are a a big ship, you inflict 3 tractor tokens)." }
D.upgrades[37] = { name_FRA = "Torpille à Plasma", name_ENG = "Plasma Torpedo", id = 36, slot = "Torpedo", add_Data = {0}, force = 0, charge = {1, "yellow", "0"}, effect_FRA = " 3<img class='inline-img' src='img/bulls.png'> portée 1-2: dépensez 1 <img class='inline-img' src='img/charge.png'>. Lors de l’étape « Neutraliser les résultats », les résultats <img class='inline-img' src='img/crit.png'> sont annulés avant les résultats <img class='inline-img' src='img/hit.png'>. Après que cette attaque a touché, le défenseur perd 1 bouclier. Gagnez un jeton désarmement.", effect_ENG = " 3<img class='inline-img' src='img/bulls.png'> range 1-2: spend 1 <img class='inline-img' src='img/charge.png'>. During the 'Neutralize results' step, <img class='inline-img' src='img/crit.png'> results are canceled before <img class='inline-img' src='img/hit.png'> results. After this attack hits, the defender lose 1 shield. Receive 1 disarm token." }
D.upgrades[38] = { name_FRA = "Torpille à Proton Avancée", name_ENG = "Adv. Proton Torpedo", id = 37, slot = "Torpedo", add_Data = {0}, force = 0, charge = {1, "yellow", "0"}, effect_FRA = " 4<img class='inline-img' src='img/bulls.png'> Portée 1 : dépensez 1 <img class='inline-img' src='img/charge.png'>. Vous pouvez modifier 1 résultat <img class='inline-img' src='img/hit.png'> en <img class='inline-img' src='img/crit.png'>. Gagnez un jeton désarmement.", effect_ENG = " 4<img class='inline-img' src='img/bulls.png'> range 1 : spend 1 <img class='inline-img' src='img/charge.png'>. you may modify 1 <img class='inline-img' src='img/hit.png'> result into a <img class='inline-img' src='img/crit.png'> result. Receive a disarm token." }
D.upgrades[39] = { name_FRA = "Torpille à Concussion", name_ENG = "Concussion Torpedo", id = 38, slot = "Torpedo", add_Data = {0}, force = 0, charge = {1, "yellow", "0"}, effect_FRA = " 2<img class='inline-img' src='img/bulls.png'> Portée 2-3 : dépensez 1 <img class='inline-img' src='img/charge.png'>. Après que cette attaque a touché, chaque vaisseau à portée 0–1 du défenseur expose 1 de ses cartes de dégât. Gagnez un marqueur désarmement.", effect_ENG = " 2<img class='inline-img' src='img/bulls.png'> range 2-3 : spend 1 <img class='inline-img' src='img/charge.png'>. After this attack hits, each ship at range 0-1 of the defender exposes 1 of its damage card. Receive 1 disarm token." }
D.upgrades[40] = { name_FRA = "Roquette à Proton", name_ENG = "Proton Rocket", id = 39, slot = "Torpedo", add_Data = {0}, force = 0, charge = {1, "yellow", "0"}, effect_FRA = " 3<img class='inline-img' src='img/attackF.png'> Portée 1 : dépensez 1 <img class='inline-img' src='img/charge.png'>. Si le défenseur est dans votre <img class='inline-img' src='img/bulls.png'>, vous pouvez améliorer 1 résultat. Gagnez un jeton épuisement.", effect_ENG = " 3<img class='inline-img' src='img/attackF.png'> Range 1 : spend 1 <img class='inline-img' src='img/charge.png'>. If the defender is in your <img class='inline-img' src='img/bulls.png'>, you may upgrade a result. Receive a deplete token." }
D.upgrades[41] = { name_FRA = "Générateur de Sous-Munitions", name_ENG = "Bomblet Generator", id = 40, slot = "Payload", add_Data = {0}, force = 0, charge = {2, "yellow", "0"}, effect_FRA = "  Pendant la phase de système, vous pouvez dépenser 1 <img class='inline-img' src='img/charge.png'> pour larguer une sous-munition avec le gabarit 1<img class='inline-img' src='img/manSt2.png'>. Au début de la phase d’activation, vous pouvez dépenser 1 bouclier pour récupérer 2 <img class='inline-img' src='img/charge.png'>.<br>A la fin de la phase d'activation, tous les vaisseaux à portée 0-1 de cet engin lancent 2 dés d'attaque. Ils subissent autant de dégats <img class='inline-img' src='img/hit.png'> que de résultats <img class='inline-img' src='img/hit.png'>/<img class='inline-img' src='img/crit.png'>. Retirez ensuite cet engin.", effect_ENG = "  During System phase, you may spend 1 <img class='inline-img' src='img/charge.png'> to drop a bomblet with 1<img class='inline-img' src='img/manSt2.png'> template. At the beginning of activation phase, you may spend 1 shield to recover 2<img class='inline-img' src='img/charge.png'>.<br>At the end of activation phase, each ship at range 0-1 of this device rolls 2 attack dice. They suffer as many <img class='inline-img' src='img/hit.png'> damage as the number of <img class='inline-img' src='img/hit.png'>/<img class='inline-img' src='img/crit.png'> results. Then remove this device." }
D.upgrades[42] = { name_FRA = "Filet Conner", name_ENG = "Conner Nets", id = 41, slot = "Payload", add_Data = {0}, force = 0, charge = {1, "yellow", "0"}, effect_FRA = " Pendant la phase de système, vous pouvez dépenser 1<img class='inline-img' src='img/charge.png'> pour larguer un filet Conner en utilisant le gabarit 1<img class='inline-img' src='img/manSt2.png'>.<br>Lorsqu'un vaisseau chevauche ou se déplace à travers cet engin, il subit 1 dégat et reçoit 3 jetons ion, puis retirez le de la partie.", effect_ENG = " During System Phase, you may spend 1<img class='inline-img' src='img/charge.png'> to drop 1 Conner Nets using the 1<img class='inline-img' src='img/manSt2.png'> template. <br> When a ship moves through or overlaps this device, it suffers 1 damage and receive 3 ion tokens. Then remove this deivce." }
D.upgrades[43] = { name_FRA = "Bombe à Proton", name_ENG = "Proton Bomb", id = 42, slot = "Payload", add_Data = {0}, force = 0, charge = {1, "yellow", "0"}, effect_FRA = " Pendant la phase de système, vous pouvez dépenser 1 <img class='inline-img' src='img/charge.png'> pour larguer une bombe à protons en utilisant le gabarit 1<img class='inline-img' src='img/manSt2.png'>.<br>A la fin de la phase d'activation, tous les vaisseaux à portée 0-1 subissent 1 dégat <img class='inline-img' src='img/crit.png'>, puis retirez le de la partie.", effect_ENG = " During System Phase, you may spend 1<img class='inline-img' src='img/charge.png'> to drop a proton bomb with the 1<img class='inline-img' src='img/manSt2.png'> template.<br>At the end of activation phase, each ship at range 0-1 suffers 1 <img class='inline-img' src='img/crit.png'> result, then remove this device." }
D.upgrades[44] = { name_FRA = "Mines de Proximité", name_ENG = "Proximity Mines", id = 43, slot = "Payload", add_Data = {0}, force = 0, charge = {1, "yellow", "0"}, effect_FRA = "Pendant la phase de système, vous pouvez dépenser 1 <img class='inline-img' src='img/charge.png'> pour larguer une mine de proximité en utilisant le gabarit 1<img class='inline-img' src='img/manSt2.png'>.<br>Lorsqu'un vaisseau chevauche ou se déplace à travers cet engin, il subit 1 dégat et lance 2 dés d'attaque : il subit les dégats correspondant aux résultats <img class='inline-img' src='img/hit.png'>/<img class='inline-img' src='img/crit.png'>.", effect_ENG = " During System Phase, you may spend 1<img class='inline-img' src='img/charge.png'> to drop a proximity mine using the 1<img class='inline-img' src='img/manSt2.png'> template.<br>When a ship moves through or overlaps this device, it suffers 1 damage and rolls 2 attack dice : it suffers <img class='inline-img' src='img/hit.png'>/<img class='inline-img' src='img/crit.png'> damage matching the <img class='inline-img' src='img/hit.png'>/<img class='inline-img' src='img/crit.png'> results." }
D.upgrades[45] = { name_FRA = "Charge Sismique", name_ENG = "Seismic Charge", id = 44, slot = "Payload", add_Data = {0}, force = 0, charge = {1, "yellow", "0"}, effect_FRA = " Pendant la phase de système, vous pouvez dépenser 1 <img class='inline-img' src='img/charge.png'> pour larguer une charge sismique en utilisant le gabarit 1<img class='inline-img' src='img/manSt2.png'>.<br>A la fin de la phase d'activation, choisissez 1 obstacle à portée 0-1. Tous les vaisseaux à portée 0-1 de cet obstacle subissent 1 dégat <img class='inline-img' src='img/hit.png'>, puis retirez cet obstacle et cet engin.", effect_ENG = " During System Phase, you may spend 1<img class='inline-img' src='img/charge.png'> to drop a Seismic Charge with the 1<img class='inline-img' src='img/manSt2.png'> template.<br>At the end of activation phase, choose an obstacle at range 0-1 of this device. Each ship at range 0-1 of this obstacle suffers 1 <img class='inline-img' src='img/crit.png'> result, then remove this device and this obstacle." }
D.upgrades[46] = { name_FRA = "Bombe IEM", name_ENG = "EMP Bomb", id = 45, slot = "Payload", add_Data = {0}, force = 0, charge = {1, "yellow", "0"}, effect_FRA = " Pendant la phase de système, vous pouvez dépenser 1 <img class='inline-img' src='img/charge.png'> pour larguer une bombe IEM en utilisant le gabarit 1<img class='inline-img' src='img/manSt2.png'>.<br>A la fin de la phase d'activation, tous les vaisseaux à portée 0-1 de cet engin reçoivent 1 jeton brouillage et 1 jeton contrainte, puis retirez cet engin.", effect_ENG = " During System Phase, you may spend 1<img class='inline-img' src='img/charge.png'> to drop an EMP bomb with the 1<img class='inline-img' src='img/manSt2.png'> template.<br>At the end of activation phase, each ship at range 0-1 receives 1 jam token and 1 strain token, then remove this device." }
D.upgrades[47] = { name_FRA = "Rayon de Brouillage", name_ENG = "Jamming Beam", id = 46, slot = "Cannon", add_Data = {0}, force = 0, charge = {0}, effect_FRA = "Portée 1-3 <img class='inline-img' src='img/attackF.png'> 3 dés Attaque : si cette attaque touche, tous les résultats <img class='inline-img' src='img/hit.png'>/<img class='inline-img' src='img/crit.png'> infligent des marqueurs de brouillage au lieu des dégâts.", effect_ENG = "3<img class='inline-img' src='img/attackF.png'> range 1-3 Attack : if this attack hits, all remaining <img class='inline-img' src='img/hit.png'>/<img class='inline-img' src='img/crit.png'> results inflict jam tokens instead of damage." }
D.upgrades[48] = { name_FRA = "Rayon Tracteur", name_ENG = "Tractor Beam", id = 47, slot = "Cannon", add_Data = {0}, force = 0, charge = {0}, effect_FRA = "Portée 1-3 <img class='inline-img' src='img/attackF.png'> 3 dés, Attaque : si cette attaque touche, tous les résultats <img class='inline-img' src='img/hit.png'>/<img class='inline-img' src='img/crit.png'> infligent des marqueurs de rayon tracteur au lieu des dégâts.", effect_ENG = "3<img class='inline-img' src='img/attackF.png'> Range 1-3, Attack : If this attack hits, each remaining <img class='inline-img' src='img/hit.png'>/<img class='inline-img' src='img/crit.png'> result inflicts tractor tokens instead of damage." }
D.upgrades[49] = { name_FRA = "Canon Ionique", name_ENG = "Ion Cannon", id = 48, slot = "Cannon", add_Data = {0}, force = 0, charge = {0}, effect_FRA = "Portée 1-3 <img class='inline-img' src='img/attackF.png'> 3 dés Attaque : si cette attaque touche, dépensez 1 résultat <img class='inline-img' src='img/hit.png'> ou <img class='inline-img' src='img/crit.png'> pour faire subir 1 dégât au défenseur. Tous les résultats <img class='inline-img' src='img/hit.png'>/<img class='inline-img' src='img/crit.png'> restants infligent des marqueurs ioniques au lieu des dégâts.", effect_ENG = "3<img class='inline-img' src='img/attackF.png'> Range 1-3, Attack : If this attack hits, spend 1 <img class='inline-img' src='img/hit.png'> or <img class='inline-img' src='img/crit.png'> result to inflict 1 <img class='inline-img' src='img/hit.png'> damage to the defender. All <img class='inline-img' src='img/hit.png'>/<img class='inline-img' src='img/crit.png'> remaining results inflict ion tokens instead of damage." }
D.upgrades[50] = { name_FRA = "Canon Laser Lourd", name_ENG = "Heavy Laser Cannon", id = 49, slot = "Cannon", add_Data = {0}, force = 0, charge = {0}, effect_FRA = "Portée 2-3 <img class='inline-img' src='img/attackF.png'> 4 dés. Si le défenseur n’est pas dans le <img class='inline-img' src='img/bulls.png'>, alors dégradez 4 dés d'attaque.", effect_ENG = "4<img class='inline-img' src='img/attackF.png'> Range 2-3, Attack : if the defender is not in your <img class='inline-img' src='img/bulls.png'>, downgrade 4 attack dice." }
D.upgrades[51] = { name_FRA = "Canons Laser Jumelés", name_ENG = "Synced Laser Cannons", id = 50, slot = "Cannon", add_Data = {0}, force = 0, charge = {0}, effect_FRA = "Portée 2-3 <img class='inline-img' src='img/attackF.png'> 3 dés Attaque : si vous êtes calculateur, vous pouvez améliorer 1 dé d’attaque", effect_ENG = "3<img class='inline-img' src='img/attackF.png'> range 2-3, Attack : if you are calculating, you may upgrade 1 attack die." }
D.upgrades[52] = { name_FRA = "Tourelle à Canon Ionique", name_ENG = "Ion Cannon Turret", id = 51, slot = "Turret", add_Data = {0}, force = 0, charge = {1, "addRaWAction", ""}, effect_FRA = "Portée 1-2 <img class='inline-img' src='img/Tarc.png'> 3 dés Attaque : si cette attaque touche, dépensez 1 résultat <img class='inline-img' src='img/hit.png'> ou <img class='inline-img' src='img/crit.png'> pour faire subir 1 dégât <img class='inline-img' src='img/hit.png'> au défenseur. Tous les résultats <img class='inline-img' src='img/hit.png'>/<img class='inline-img' src='img/crit.png'> restants infligent des marqueurs ioniques au lieu des dégâts.", effect_ENG = "3<img class='inline-img' src='img/attackF.png'> range 1-2, Attack : If this attack hits, spend 1 <img class='inline-img' src='img/hit.png'> or <img class='inline-img' src='img/crit.png'> result to inflict 1 <img class='inline-img' src='img/hit.png'> damage to the defender. All <img class='inline-img' src='img/hit.png'>/<img class='inline-img' src='img/crit.png'> remaining results inflict ion tokens instead of damage." }
