D.upgrades[55] = { name_FRA = "Tourelle Laser Jumelé", name_ENG = "Twin Laser Turrets", id = 54, slot = "Turret", add_Data = {0}, force = 0, charge = {1, "addRaWAction", ""}, effect_FRA = "Portée 2-3 <img class='inline-img' src='img/Tarc.png'> 3 dés Attaque : dégradez 3 dés d'attaque<br>puis Attaque: dégradez 2 dés d'attaque.", effect_ENG = "3<img class='inline-img' src='img/Tarc.png'> range 2-3, Attack : downgrade 3 attack dice<br>Then Attack : downgrade 2 attack dice." }
D.upgrades[56] = { name_FRA = "Support pour Canon Rotatif", name_ENG = "Cannon Turret Support", id = 55, slot = "Turret", add_Data = {0}, force = 0, charge = {1, "addRaWAction", ""}, effect_FRA = "Choisissez une amélioration <img class='inline-img' src='img/Cannon.png'> équipée et placez un marqueur canon rotatif dessus. La restriction <img class='inline-img' src='img/attackF.png'> de votre <img class='inline-img' src='img/Cannon.png'> devient <img class='inline-img' src='img/Tarc.png'>. Vous pouvez tourner l’arc de votre <img class='inline-img' src='img/Cannon.png'> avec l’action <img class='inline-img' src='img/Ra W.png'>.", effect_ENG = "Choose an equipped <img class='inline-img' src='img/Cannon.png'> upgrade and place a cannon turret token on it. The <img class='inline-img' src='img/attackF.png'> restriction of your <img class='inline-img' src='img/Cannon.png'> becomes a <img class='inline-img' src='img/Tarc.png'> restriction. You may rotate the arc of your <img class='inline-img' src='img/Cannon.png'> with the <img class='inline-img' src='img/Ra W.png'> action." }
D.upgrades[57] = { name_FRA = "Appareil d'Occultation", name_ENG = "Cloaking Device", id = 56, slot = "Illicit", add_Data = {0}, force = 0, charge = {2, "yellow", "0"}, effect_FRA = "Action : Dépensez 1 <img class='inline-img' src='img/charge.png'> pour effectuer une action <img class='inline-img' src='img/Ck W.png'>.<br>Au début de la phase de planification, lancez 1 dé d’attaque. Sur un résultat <img class='inline-img' src='img/Fo W.png'>, désoccultez-vous ou défaussez votre marqueur d’occultation.", effect_ENG = "Action : spend 1 <img class='inline-img' src='img/charge.png'> to perform a <img class='inline-img' src='img/Ck W.png'> action.<br>At the start of planification, roll 1 attack die. If there's an <img class='inline-img' src='img/Fo W.png'> result, decloak or lose your cloak token." }
D.upgrades[58] = { name_FRA = "Cybernétiques de Contrebande", name_ENG = "Contraband Cybernetics", id = 57, slot = "Illicit", add_Data = {0}, force = 0, charge = {1, "yellow", "0"}, effect_FRA = "Avant votre activation, vous pouvez dépenser 1 <img class='inline-img' src='img/charge.png'>. Dans ce cas, jusqu’à la fin du round, vous pouvez effectuer des actions et exécuter des manœuvres rouges, même si vous êtes stressé.", effect_ENG = "Before you activate, you may spend 1<img class='inline-img' src='img/charge.png'>. If you do, until the end of the round, you may perform actions and execute red maneuvers, even if you are stressed." }
D.upgrades[59] = { name_FRA = "Salve Automatique", name_ENG = "Deadman's Switch", id = 58, slot = "Illicit", add_Data = {0}, force = 0, charge = {0}, effect_FRA = "Après que vous avez été détruit, chaque autre vaisseau à portée 0–1 subit 1 dégât <img class='inline-img' src='img/hit.png'>.", effect_ENG = "After you are destroyed, each other ship at range 0-1 suffers 1 <img class='inline-img' src='img/hit.png'> damage." }
D.upgrades[60] = { name_FRA = "Hypercarburant Coaxium", name_ENG = "Coaxium Hyperfuel", id = 59, slot = "Illicit", add_Data = {0}, force = 0, charge = {1, "yellow", "0"}, effect_FRA = "ACTION : dépensez 1 <img class='inline-img' src='img/charge.png'>. Vous pouvez effectuer une action <img class='inline-img' src='img/Sl W.png'>. Vous pouvez effectuer cette action même après avoir partiellement effectué une manoeuvre ou sous l’effet du stress. Puis exposez 1 carte de dégât ou prenez 1 dégât critique.", effect_ENG = "ACTION : spend 1<img class='inline-img' src='img/charge.png'>. You may perform a <img class='inline-img' src='img/Sl W.png'> action. You may perform this action even after you partially exectute a maneuver or if you are stressed. Then expose a damage card or suffer 1 <img class='inline-img' src='img/crit.png'> damage." }
D.upgrades[61] = { name_FRA = "Codes Transpondeur Falsifiés", name_ENG = "False Transponder Codes", id = 60, add_Data = {0}, force = 0, charge = {1, "yellow", "0"}, slot = "Illicit", effect_FRA = "Après avoir verrouillé un objet ou qu'un objet vous a verrouillé, vous pouvez dépenser 1 <img class='inline-img' src='img/charge.png'> pour brouiller cet objet, en ignorant les restrictions de portée.", effect_ENG = "After you lock an object, or an object locks you, you may spend 1<img class='inline-img' src='img/charge.png'> to jam this object ignoring range restrictions." }
D.upgrades[62] = { name_FRA = "Blindage Ablatif", name_ENG = "Ablative Plating", id = 61, slot = "Modification", add_Data = {0}, force = 0, charge = {2, "yellow", "0"}, effect_FRA = "  Avant de subir des dégâts à cause d’un obstacle ou de l’explosion d’une bombe alliée, vous pouvez dépenser 1 <img class='inline-img' src='img/charge.png'>. Dans ce cas, prévenez 1 dégât.", effect_ENG = "  Before you suffer damage because of an obstacle or a friendly bomb, you may spend 1<img class='inline-img' src='img/charge.png'>. If you do, prevent 1 damage." }
D.upgrades[63] = { name_FRA = "Postcombustion", name_ENG = "Afterburners", id = 62, slot = "Modification", add_Data = {0}, force = 0, charge = {2, "yellow", "0"}, effect_FRA = "  Après avoir entièrement exécuté une manœuvre à vitesse 3–5, vous pouvez dépenser 1 <img class='inline-img' src='img/charge.png'> pour effectuer une action <img class='inline-img' src='img/Bo W.png'>, même tant que vous êtes stressé.", effect_ENG = "  After you fully execute a speed 3-5 maneuver, you may spend 1<img class='inline-img' src='img/charge.png'> to perform a <img class='inline-img' src='img/Bo W.png'> action, even if you are stressed." }
D.upgrades[64] = { name_FRA = "Moteur Amélioré", name_ENG = "Engine Upgrade", id = 63, slot = "Modification", add_Data = {0}, force = 0, charge = {1, "addBoWAction", ""}, effect_FRA = "Nécessite que votre vaisseau dispose de l'action <img class='inline-img' src='img/Bo W.png'> rouge. Donne l'action <img class='inline-img' src='img/Bo W.png'> blanche", effect_ENG = "You need the red <img class='inline-img' src='img/Bo W.png'> action to equip this card. You gain the white <img class='inline-img' src='img/Bo W.png'> action." }
D.upgrades[65] = { name_FRA = "Munitions à Sûreté Intégrée", name_ENG = "Munitions Failsafe", id = 64, slot = "Modification", add_Data = {0}, force = 0, charge = {0}, effect_FRA = "Tant que vous effectuez une attaque <img class='inline-img' src='img/missile.png'> ou <img class='inline-img' src='img/Torpedo.png'>, après avoir lancé les dés d’attaque, vous pouvez annuler tous les résultats des dés pour récupérer 1 <img class='inline-img' src='img/charge.png'> que vous avez dépensée comme coût pour l’attaque.", effect_ENG = "While you perform a <img class='inline-img' src='img/missile.png'> or <img class='inline-img' src='img/Torpedo.png'> attack, after you roll attack dice, you may cancel all dice results to recover 1<img class='inline-img' src='img/charge.png'> you have spent as a cost for the attack." }
D.upgrades[66] = { name_FRA = "Brouilleur Tactique", name_ENG = "Tactical Scrambler", id = 65, slot = "Modification", add_Data = {0}, force = 0, charge = {0}, effect_FRA = "Tant que vous gênez l’attaque d’un vaisseau ennemi, le défenseur lance 1 dé de défense supplémentaire.", effect_ENG = "While you obstruct an enemy ship attack, the defender rolls 1 additional defense die." }
D.upgrades[67] = { name_FRA = "Coque Améliorée", name_ENG = "Hull Upgrade", id = 66, slot = "Modification", add_Data = {0}, force = 0, charge = {1, "yellow", "0"}, effect_FRA = " Lorsque vous devriez recevoir une carte de dégat face cachée, vous pouvez dépenser 1<img class='inline-img' src='img/charge.png'> pour la défausser à la place.", effect_ENG = "img class='inline-img' src='img/chargestat.png'> When you would receive a facedown damage card, you may spend 1<img class='inline-img' src='img/charge.png'> instead." }
D.upgrades[68] = { name_FRA = "Bouclier Amélioré", name_ENG = "Shield Upgrade", id = 67, slot = "Modification", add_Data = {0}, force = 0, charge = {1, "yellow", "0"}, effect_FRA = " Lorsque vous devriez recevoir votre premier dégat, dépensez 1<img class='inline-img' src='img/charge.png'> pour l'annuler.", effect_ENG = " When you would receive your first damage, spend 1<img class='inline-img' src='img/charge.png'> to cancel it." }
D.upgrades[69] = { name_FRA = "Système d'Occultation", name_ENG = "Stealth Device", id = 68, slot = "Modification", add_Data = {0}, force = 0, charge = {1, "yellow", "0"}, effect_FRA = " Tant que vous défendez, si votre <img class='inline-img' src='img/charge.png'> est active, lancez 1 dé de défense supplémentaire. Après avoir subi des dégâts, perdez 1<img class='inline-img' src='img/charge.png'>.", effect_ENG = " While you defend, if your <img class='inline-img' src='img/charge.png'> is active, roll 1 additional defense die. After you suffer damage, lose 1<img class='inline-img' src='img/charge.png'>." }
D.upgrades[70] = { name_FRA = "Détonateur à Retardement", name_ENG = "Delayed Fuses", id = 69, slot = "Modification", add_Data = {0}, force = 0, charge = {0}, effect_FRA = "Après avoir largué ou lancé une bombe ou une mine, vous pouvez placer dessus 1 marqueur d’amorce. Lorsque cet engin doit exploser, retirez 1 marqueur d'amorce à la place.", effect_ENG = "After you launch or drop a bomb or a mine, you may place 1 delay token on it. When this device would explose, remove 1 delay token instead." }
D.upgrades[71] = { name_FRA = "Ordinateur de Visée", name_ENG = "Targeting Computer", id = 70, slot = "Modification", add_Data = {0}, force = 0, charge = {1, "addLoWAction", ""}, effect_FRA = "Donne accès l'action <img class='inline-img' src='img/Lo W.png'>. Vous pouvez vérifier toutes les portées autour de votre vaisseau avant de choisir la cible de l'acquisition.", effect_ENG = "Gain the <img class='inline-img' src='img/Lo W.png'> action. You may check all ranges around you before choosing the target to lock." }
