D.upgrades[73] = { name_FRA = "Détecteur Anticollision", name_ENG = "Collision Detector", id = 72, slot = "Sensor", add_Data = {0}, force = 0, charge = {2, "yellow", "0"}, effect_FRA = "  Tant que vous accélérez ou que vous effectuez un tonneau, vous pouvez vous déplacer à travers ou chevaucher les obstacles. Après vous être déplacé à travers ou avoir chevauché un obstacle, vous pouvez dépenser 1 <img class='inline-img' src='img/charge.png'> pour ignorer ses effets jusqu’à la fin du round.", effect_ENG = "  While you boost or barrel roll, you may move through or overlap obstacles. After you move through or overlap obstacles, you may spend 1<img class='inline-img' src='img/charge.png'> to ignore its effects until the end of the round." }
