D.upgrades[76] = { name_FRA = "Brouilleur de Senseur", name_ENG = "Sensor Jammer", id = 75, slot = "Sensor", add_Data = {0}, force = 0, charge = {2, "yellow", "+"}, effect_FRA = "  <img class='inline-img' src='img/chargeplus.png'>Augmentez les portées de l’action brouillage de 1. Lorsque vous défendez, vous pouvez dépenser 1 <img class='inline-img' src='img/charge.png'> pour dégrader 1 dé d’attaque.", effect_ENG = "img class='inline-img' src='img/chargestat.png'>  <img class='inline-img' src='img/chargeplus.png'> Increase the range of the jam action by 1. While you defend, you may spend 1<img class='inline-img' src='img/charge.png'> to downgrade 1 attack die." }
D.upgrades[77] = { name_FRA = "Patience", name_ENG = "Patience", id = 76, slot = "Force-Light", add_Data = {0}, force = 0, charge = {0}, effect_FRA = " Vous pouvez dépenser 1 <img class='inline-img' src='img/charge.png'> à la place d'une <img class='inline-img' src='img/fo.png'>. Au début de la phase d'engagement, vous pouvez gagner 1 marqueur d’épuisement pour récupérer 1 <img class='inline-img' src='img/charge.png'>.", effect_ENG = " You may spend 1<img class='inline-img' src='img/charge.png'> instead of 1<img class='inline-img' src='img/fo.png'>. At the start of engagement phase, you may  receive 1 deplete token to recover 1<img class='inline-img' src='img/charge.png'>." }
D.upgrades[78] = { name_FRA = "Réflexes Surnaturels", name_ENG = "Supernatural Reflexes", id = 77, slot = "Force-Base", add_Data = {0}, force = 0, charge = {0}, effect_FRA = "Après avoir révélé votre cadran, vous pouvez dépenser 3 <img class='inline-img' src='img/fo.png'> pour effectuer une action <img class='inline-img' src='img/Br W.png'> ou <img class='inline-img' src='img/Bo W.png'>. Puis, si vous avez effectué une action qui n’est pas sur votre barre d’action, recevez 2 marqueurs de contrainte. Dans ce cas, vous ne pouvez pas effectuer une autre action pendant votre activation.", effect_ENG = "After you reveal your dial, you may spend 3 <img class='inline-img' src='img/fo.png'> to perform a <img class='inline-img' src='img/Br W.png'> or <img class='inline-img' src='img/Bo W.png'> action. Then, if you have performed an action which is not on your action bar, receive 2 strain tokens. In this case, you cannot perform an other action during your activation." }
D.upgrades[79] = { name_FRA = "As de la Manoeuvre", name_ENG = "Brilliant Evasion", id = 78, slot = "Force-Base", add_Data = {0}, force = 0, charge = {0}, effect_FRA = "Lorsque vous défendez, vous pouvez dépenser 1 <img class='inline-img' src='img/fo.png'>. Dans ce cas, améliorez 1 dé de défense.", effect_ENG = "While you defend, you may spend 1 <img class='inline-img' src='img/fo.png'>. If you do, upgrade 1 defense die." }
D.upgrades[80] = { name_FRA = "Sens", name_ENG = "Sense", id = 79, slot = "Force-Light", add_Data = {0}, force = 0, charge = {0}, effect_FRA = "Pendant la phase de système, vous pouvez dépenser 2 <img class='inline-img' src='img/fo.png'>. Dans ce cas, vous pouvez regarder le cadran de manoeuvre d'un ennemi à portée 0-2. Puis vous pouvez modifier votre manoeuvre", effect_ENG = "During System Phase, you may spend 2 <img class='inline-img' src='img/fo.png'>. If you do, you may look at an enemy ship dial at range 0-2. Then you may change you maneuver." }
D.upgrades[81] = { name_FRA = "Visée Instinctive", name_ENG = "Instinctive Aim", id = 80, slot = "Force-Base", add_Data = {0}, force = 0, charge = {0}, effect_FRA = "Tant que vous effectuez une attaque spéciale, vous pouvez dépenser 1 <img class='inline-img' src='img/fo.png'> pour ignorer le prérequis <img class='inline-img' src='img/Lo W.png'> ou <img class='inline-img' src='img/Fo W.png'>. Dans ce cas, vous pouvez améliorer 1 dé d'attaque.", effect_ENG = "While you perform a special attack, you may spend 1 <img class='inline-img' src='img/fo.png'> to ignore <img class='inline-img' src='img/Lo W.png'> or <img class='inline-img' src='img/Fo W.png'> restriction. If you do, you may upgrade 1 attack die" }
D.upgrades[82] = { name_FRA = "Système de Tir Automatique", name_ENG = "Automatic Gunning System", id = 81, slot = "Calculator", add_Data = {0}, force = 0, charge = {0}, effect_FRA = "Après avoir effectué une attaque principale, vous pouvez effectuer une attaque bonus d’arme spéciale. Lors de cette attaque, vous ne pouvez pas ajouter ou modifier des dés d’attaque.", effect_ENG = "After you perform a primary attack, you may perform a bonus attack with a special weapon. During this attack, you cannot add or modify attack dice." }
D.upgrades[83] = { name_FRA = "Calculs en Réseau Avancés", name_ENG = "Advanced Networked Calculations", id = 82, slot = "Calculator", add_Data = {0}, force = 0, charge = {0}, effect_FRA = "Lorsque vous défendez ou attaquez, vous pouvez dépenser 1 marqueur de calcul d’un vaisseau allié à portée 0-2 pour changer 1 résultat <img class='inline-img' src='img/Fo W.png'> en résultat <img class='inline-img' src='img/Ev W.png'> ou <img class='inline-img' src='img/hit.png'>.", effect_ENG = "While you attack  or defend, you may spend 1 calculate token from a friendly ship at range 0-2 to modifiy 1 <img class='inline-img' src='img/Fo W.png'> result into an <img class='inline-img' src='img/Ev W.png'> or <img class='inline-img' src='img/hit.png'> result." }
D.upgrades[84] = { name_FRA = "Données de Pistage Hyperspatial", name_ENG = "Hyperspace Tracking Data", id = 83, slot = "Calculator", add_Data = {0}, force = 0, charge = {0}, effect_FRA = "Mise en place : vous pouvez considérer votre initiative comme étant 0 ou 7. A la fin de la phase de mise en place, tous les vaisseaux alliés à portée 0-2 de vous gagne 1 marqueur de calcul. Ces marqueurs de calcul ne sont pas nettoyés en phase de fin.", effect_ENG = "SETUP : You may consider your initiative as 0 or 7. At the end of Setup phase, each friendly ship at range 0-2 of you gains 1 calculate token. Those tokens are not removed during End Phase." }
D.upgrades[85] = { name_FRA = "Ordinateur de Vol Avancé", name_ENG = "Advanced Flight Computer", id = 84, slot = "Calculator", add_Data = {0}, force = 0, charge = {3, "yellow", "-"}, effect_FRA = "   <img class='inline-img' src='img/chargeminus.png'> Mise en place : vous commencez en réserve. Vous pouvez dépenser entre 0 et 2 <img class='inline-img' src='img/charge.png'>.<br>Au début de la phase de planification, s’il n’y a plus de <img class='inline-img' src='img/charge.png'> active, placez votre vaisseau intégralement à portée 1 d’un bord de l’aire de jeu.", effect_ENG = "img class='inline-img' src='img/chargestat.png'>   <img class='inline-img' src='img/chargeminus.png'> SETUP : you begin in reserve. You may spend between 0 or 2<img class='inline-img' src='img/charge.png'>.<br>At the start of planification phase, if there's no active <img class='inline-img' src='img/charge.png'>, place your ship within range 1 of a map edge." }
D.upgrades[86] = { name_FRA = "Crypteur de Données", name_ENG = "Encrypter", id = 85, slot = "Calculator", add_Data = {0}, force = 0, charge = {0}, effect_FRA = "Vous pouvez coordonner jusqu’à la portée 3. Lorsque vous coordonnez un vaisseau, recevez 1 marqueur de calcul.", effect_ENG = "You may coordinate up to range 3. When you coordinate a ship, receive 1 calculate token." }
D.upgrades[87] = { name_FRA = "R2-D2", name_ENG = "R2-D2", id = 86, slot = "Astromech", add_Data = {0}, force = 0, charge = {2, "yellow", "0"}, effect_FRA = "  Après votre activation, vous pouvez dépenser 1 <img class='inline-img' src='img/charge.png'> et gagner 1 marqueur d’épuisement pour réparer 1 carte de dégât, récupérer 1 bouclier ou retirer 1 engin à portée 0–1.", effect_ENG = "  After you activate, you may spend 1<img class='inline-img' src='img/charge.png'> and gain 1 deplete token to repair 1 damage card, recover1 shield, or remove 1 devicie at range 0-1." }
D.upgrades[88] = { name_FRA = "R5-D8", name_ENG = "R5-D8", id = 87, slot = "Astromech", add_Data = {0}, force = 0, charge = {3, "yellow", "0"}, effect_FRA = "   Action : dépensez 1 <img class='inline-img' src='img/charge.png'> pour réparer 1 carte de dégât face cachée.<br>Action : réparez 1 carte de dégât Vaisseau face visible.", effect_ENG = "   ACTION : Spend 1 <img class='inline-img' src='img/charge.png'> to repair 1 facedown damage card.<br>ACTION : repair 1 faceup ship damage card." }
D.upgrades[89] = { name_FRA = "C-3PO", name_ENG = "C-3PO", id = 88, slot = "Crew", add_Data = {0}, force = 0, charge = {1, "addCcWAction", ""}, effect_FRA = "Avant de lancer les dés de défense, vous pouvez dépenser 1 marqueur de calcul pour dire à voix haute un nombre supérieur ou égal à 1. Dans ce cas et si vous obtenez exactement cette quantité de résultats <img class='inline-img' src='img/Ev W.png'> sur votre lancer, ajoutez 1 résultat <img class='inline-img' src='img/Ev W.png'>.", effect_ENG = "Before rolling defense dice, you may spend 1 calculate token to guess aloud a number 1 or higher. If you do and you roll exactly that many <img class='inline-img' src='img/Ev W.png'> results, add 1 <img class='inline-img' src='img/Ev W.png'> result.<br>After you perform the <img class='inline-img' src='img/Cc W.png'> action, gain 1 calculate token." }
D.upgrades[90] = { name_FRA = "Cassian Andor", name_ENG = "Cassian Andor", id = 89, slot = "Crew", add_Data = {0}, force = 0, charge = {0}, effect_FRA = "Pendant la phase de système, vous pouvez choisir 1 vaisseau ennemi à portée 1–2, et deviner à voix haute sa direction et sa vitesse. Votre adversaire vous confirme si la direction puis la vitesse sont correctes. Si les 2 sont correctes, vous pouvez modifier votre manœuvre.", effect_ENG = "During System Phase, you may choose 1 enemy ship at range 1-2, and guess aloud its direction and its speed. Your opponent confirms if the direction then the speed are correct. If both are correct, you may modify you maneuver." }
