D.upgrades[92] = { name_FRA = "R2-D2", name_ENG = "R2-D2", id = 91, slot = "Crew", add_Data = {0}, force = 0, charge = {0}, effect_FRA = "Pendant la phase de fin, si vous êtes endommagé et n’êtes pas protégé, vous pouvez lancer 1 dé d’attaque pour récupérer 1 bouclier. Sur un résultat <img class='inline-img' src='img/hit.png'>, exposez 1 de vos cartes de dégât.", effect_ENG = "During End Phase, if you are damaged and not protected, you may roll 1 attack die to recover 1 shield. On a <img class='inline-img' src='img/hit.png'> result, expose 1 damage card." }
