D.upgrades[95] = { name_FRA = "*Altruisme", name_ENG = "*Selfless", id = 94, slot = "Talent-special", add_Data = {0}, force = 0, charge = {0}, effect_FRA = "Tant qu’un autre vaisseau allié à portée 0–1 défend, avant l’étape « Neutraliser les résultats », si vous êtes dans l’arc de l’attaque, vous pouvez subir 1 dégât <img class='inline-img' src='img/crit.png'> pour annuler 1 résultat <img class='inline-img' src='img/crit.png'>.", effect_ENG = "While an other friendly ship at range 0-1 defends, before the 'Neutralize results' step, if you are in the attack arc, you may suffer 1 <img class='inline-img' src='img/crit.png'> damage to cancel 1 <img class='inline-img' src='img/crit.png'> result." }
D.upgrades[96] = { name_FRA = "K-2SO", name_ENG = "K-2SO", id = 95, slot = "Crew", effect_FRA = "Pendant la phase de système, vous pouvez choisir un vaisseau allié à portée 0–3. Ce vaisseau gagne 1 marqueur de calcul et 1 marqueur de stress.<br>Ajoute les actions <img class='inline-img' src='img/Cc W.png'>-><img class='inline-img' src='img/Ja W.png'>", effect_ENG = "During System Phase, you may choose a friendly ship at range 0-3. This ship receives 1 calculate token and 1 stress token.<br>Adds the <img class='inline-img' src='img/Cc W.png'>-><img class='inline-img' src='img/Ja W.png'> actions.", add_Data = {0}, force = 0, charge = {1, "addCcWAction", "linkJaRAction"} }
