D.upgrades[98] = { name_FRA = "Grand Moff Tarkin", name_ENG = "Grand Moff Tarkin", id = 97, slot = "Crew", effect_FRA = "Pendant la phase de système, vous pouvez dépenser 2 <img class='inline-img' src='img/charge.png'>. Dans ce cas, chaque vaisseau allié peut verrouiller un vaisseau que vous avez verrouillé.", effect_ENG = "During System Phase, you may spend 2 <img class='inline-img' src='img/charge.png'>. If you do, each friendly ship may lock a ship you have locked.", add_Data = {0}, force = 0, charge = {2, "yellow", "+"} }
D.upgrades[99] = { name_FRA = "*Impitoyable", name_ENG = "*Ruthless", id = 98, slot = "Talent-special", effect_FRA = "Tant que vous effectuez une attaque, vous pouvez choisir un autre vaisseau allié à portée 0–1 du défenseur. Dans ce cas, le vaisseau choisi subit 1 dégât <img class='inline-img' src='img/hit.png'> et vous pouvez changer 1 de vos résultats de dé en un résultat <img class='inline-img' src='img/hit.png'>.", effect_ENG = "While you attack, you may choose an other friendly ship at range 0-1 of the defender. If you do, this friendly ship suffers 1 <img class='inline-img' src='img/hit.png'>, and you may modify 1 of your dice results into a <img class='inline-img' src='img/hit.png'> result.", add_Data = {0}, force = 0, charge = {0} }
