D.upgrades[113] = { name_FRA = "***Capteur de Positionnement", name_ENG = "***Tracking Fob", id = 112, add_Data = {0}, force = 0, charge = {0}, slot = "Illicit", effect_FRA = "Mise en Place : avant de placer les forces, choisissez un adversaire ; il assigne la condition 'Désigné pour Mourir' à 1 de ses vaisseaux. Il doit l'assigner à un vaisseau limité, si possible.<br>Vous ignorez les restrictions de portée lorsque vous verrouillez le vaisseau qui a la condition 'Désigné pour Mourir'.", effect_ENG = "SETUP :  before placing forces, choose an opponent ; he assigns the condition 'Marked for Elimination' to 1 of its ships. He must assign it to a limited ship if possible.<br>You ignore range restrictions when you lock the ship with the 'Marked for Elimination' condition." }
D.upgrades[114] = { name_FRA = "*Célèbre", name_ENG = "*Notorious", id = 113, add_Data = {0}, force = 0, charge = {2, "yellow", "+"}, effect_ENG = "After you defend, if the attacker is in your firing arc, you may spend 1<img class='inline-img' src='img/charge.png'>. If you do, the attacker receives 1 strain token.<br>When you attack, if the defender is strained, you may reroll 1 blank result.", effect_FRA = "Après que vous avez défendu, si l'attaquant est dans votre arc de tir, vous pouvez dépenser 1<img class='inline-img' src='img/charge.png'> . Dans ce cas, l'attaquant gagne 1 marqueur de contrainte.<br> Tant que vous effectuez une attaque, si le défenseur est contraint, vous pouvez relancer 1 résultat vierge.", slot = "Talent-special" }
