D.upgrades[116] = { name_FRA = "*Intrépide", name_ENG = "*Fearless", id = 115, slot = "Talent-special", add_Data = {0}, force = 0, charge = {0}, effect_FRA = "Lorsque vous effectuez une attaque principale <img class='inline-img' src='img/attackF.png'>, si la portée de l’attaque est 1 et que vous êtes dans le <img class='inline-img' src='img/attackF.png'> du défenseur, vous pouvez modifier l’un de vos résultats en <img class='inline-img' src='img/hit.png'>.", effect_ENG = "While you perform a primary <img class='inline-img' src='img/attackF.png'> attack, if the attack range is 1 and you are in the <img class='inline-img' src='img/attackF.png'> of the defender, you may modify one of your results into a <img class='inline-img' src='img/hit.png'> result. " }
D.upgrades[117] = { name_FRA = "Bo-Katan Kryze", name_ENG = "Bo-Katan Kryze", id = 116, add_Data = {0}, force = 0, charge = {0}, slot = "Crew", effect_FRA = "Après avoir effectué une attaque, si le défenseur a été détruit, tous les vaisseaux alliés à portée 0-2 de vous peuvent retirer un marqueur orange ou rouge.", effect_ENG = "After you perform an attack, if the defender is destroyed, each friendly ship at range 0-2 of you may remove an orange or red token." }
