D.upgrades[119] = { name_FRA = "Gar Saxon", name_ENG = "Gar Saxon", id = 118, add_Data = {0}, force = 0, charge = {0}, slot = "Crew", effect_ENG = "While you perform a <img class='inline-img' src='img/Lo W.png'> action, you can only choose an object in your <img class='inline-img' src='img/attackF.png'> or <img class='inline-img' src='img/attackB.png'>. While you perform a primary attack, if the defender in in your <img class='inline-img' src='img/attackF.png'> or your <img class='inline-img' src='img/attackB.png'>, you may remove 1 red or orange token from the defender to roll 1 additional attack die, to a maximum of 4 dice.", effect_FRA = "Tant que vous effectuez l'action <img class='inline-img' src='img/Lo W.png'> vous pouvez choisir uniquement un objet dans votre <img class='inline-img' src='img/attackF.png'> ou votre <img class='inline-img' src='img/attackB.png'>. Tant que vous effectuez une attaque principale, si le défenseur est dans votre <img class='inline-img' src='img/attackF.png'> ou votre <img class='inline-img' src='img/attackB.png'>, vous pouvez retirer 1 marqueur rouge ou orange du défenseur pour lancer 1 de supplémentaire, pour un maximum de 4." }
D.upgrades[120] = { name_FRA = "Korkie Kryze", name_ENG = "Korkie Kryze", id = 119, add_Data = {0}, force = 0, charge = {0}, slot = "Crew", effect_ENG = "After a friendly ship in your <img class='inline-img' src='img/attack180.png'> at range 1-2 becomes the defender, you may transfer it 1 green token. While a a friendly ship in your <img class='inline-img' src='img/attack180.png'> at range 1-2 defends, if you obstruct the attack, the defender roll 1 additional defense die.", effect_FRA = "Après qu’un vaisseau allié dans votre <img class='inline-img' src='img/attack180.png'> à portée 1-2 est devenu le défenseur, vous pouvez lui transférer 1 marqueur vert. Tant qu'un vaisseau allié dans votre <img class='inline-img' src='img/attack180.png'> à portée 1-2 défend, si vous gênez l'attaque, le défenseur lance 1 dé de défense supplémentaire." }
D.upgrades[121] = { name_FRA = "Pre Vizsla", name_ENG = "Pre Vizsla", id = 120, add_Data = {0}, force = 0, charge = {1, "addCoWAction", ""}, slot = "Crew", effect_ENG = "ACTION : deploy a Super Commando docked with you.<br>ACTION : choose a Super Commando at range 0-3. He may perform a boost, even partially.", effect_FRA = "ACTION : Déployez un Super Commando qui est arrimé avec vous.<br>ACTION : Choisissez un Super Commando à portée 0-3. Il peut alors accélérer, même partiellement." }
D.upgrades[122] = { name_FRA = "Ursa Wren", name_ENG = "Ursa Wren", id = 121, add_Data = {0}, force = 0, charge = {0}, slot = "Crew", effect_FRA = "Vous pouvez maintenir 2 verrouillages qui doivent être sur des objets différents. Lorsqu’un vaisseau allié à portée 0-3 est verrouillé par un ennemi, vous pouvez effectuer une action de verrouillage.", effect_ENG = "You may maintain up to 2 locks (on different objects). When a friendly ship at range 0-3 is locked by an enemy ship, you may perform a <img class='inline-img' src='img/Lo W.png'> action." }
D.upgrades[123] = { name_FRA = "Tiber Saxon", name_ENG = "Tiber Saxon", id = 122, add_Data = {0}, force = 0, charge = {2, "yellow", "+"}, slot = "Gunner", effect_FRA = "Après avoir effectué une attaque à portée 1-2 qui a touché, si le défenseur n’a pas de carte de dégât face visible, vous pouvez dépenser 1 ou plusieurs charges. Pour chaque charge dépensée, le défenseur gagne un marqueur de contrainte.", effect_ENG = "After you perform an attack at range 1-2 that hits, if the defender has no faceup damage card, you may spend 1 or more charges. For each spent charge, the defender receives a strain token." }
D.upgrades[124] = { name_FRA = "Blindage Renforcé en Beskar", name_ENG = "Beskar Reinforced Plating", id = 123, slot = "Modification", add_Data = {0}, force = 0, charge = {2, "yellow", "0"}, effect_FRA = "  Tant que vous défendez si l'attaquant est dans votre <img class='inline-img' src='img/attackF.png'> , avant qu'une carte de dégât ne vous soit attribuée face visible, vous pouvez dépenser 1 <img class='inline-img' src='img/charge.png'> pour recevoir cette carte face cachée à la place ou dépenser 2 <img class='inline-img' src='img/charge.png'> pour la défausser.", effect_ENG = "  While you defend, if the attacker is in your <img class='inline-img' src='img/attackF.png'>, before a faceup damage card is assigned to you, you may spend 1<img class='inline-img' src='img/charge.png'> to receive this card facedown instead, or spend 2<img class='inline-img' src='img/charge.png'> to discard it instead." }
D.upgrades[125] = { name_FRA = "Optiques Mandaloriennes", name_ENG = "Mandalorian Optics", id = 124, slot = "Modification", add_Data = {0}, force = 0, charge = {2, "yellow", "0"}, effect_FRA = "  Pendant la phase de système, vous pouvez dépenser 1<img class='inline-img' src='img/charge.png'> pour verrouiller un objet dans votre <img class='inline-img' src='img/attackF.png'>. Tant que vous effectuez une attaque principale, si vous avez un verrouillage sur le défenseur, ignorez les obstacles au-delà de la portée O qui gênent cette attaque.", effect_ENG = "  During System phase, you may spend 1<img class='inline-img' src='img/charge.png'> to lock an object in your <img class='inline-img' src='img/attackF.png'>. While you perform a primary attack, if you have a lock on the defender, ignore obstacles beyond range 0 which obstruct this attack." }
D.upgrades[126] = { name_FRA = "Chewbacca", name_ENG = "Chewbacca", id = 125, slot = "Gunner", effect_ENG = "  <img class='inline-img' src='img/chargeplus.png'> After you attack, you may spend 2<img class='inline-img' src='img/charge.png'> to perform a bonus attack from a different firing arc. You may upgrade 1 of your results.", effect_FRA = "  <img class='inline-img' src='img/chargeplus.png'> Après avoir effectué une attaque, vous pouvez dépenser 2<img class='inline-img' src='img/charge.png'> pour effectuer une attaque bonus depuis un arc de tir qui n’a pas encore été utilisé ce tour. Vous pouvez améliorer l'un de vos résultats.", add_Data = {0}, force = 0, charge = {2, "yellow", "+"} }
D.upgrades[127] = { name_FRA = "Cikatro Vizago", name_ENG = "Cikatro Vizago", id = 126, slot = "Crew", add_Data = {0}, force = 0, charge = {0}, effect_FRA = "Pendant la phase de fin, vous pouvez choisir 2 améliorations <img class='inline-img' src='img/Illicit.png'> équipant des vaisseaux alliés à portée 0–2. Dans ce cas, vous pouvez échanger ces améliorations.", effect_ENG = "During End Phase, you may choose 2 <img class='inline-img' src='img/Illicit.png'> upgrades equipped by 2 different ships at range 0-2. If you do, you may exchange these upgrades." }
D.upgrades[128] = { name_FRA = "L3-37", name_ENG = "L3-37", id = 127, slot = "Crew", add_Data = {0}, force = 0, charge = {1, "yellow", "0"}, effect_FRA = " Tant que vous défendez, vous pouvez dépenser 1 <img class='inline-img' src='img/charge.png'>. Dans ce cas, l’attaquant doit relancer tous les dés d’attaque.<br>Si votre charge est inactive, diminuez la difficulté de vos manœuvres <img class='inline-img' src='img/manBl2.png'> et <img class='inline-img' src='img/manBr2.png'>.", effect_ENG = " When you defend, you may spend 1<img class='inline-img' src='img/charge.png'>. If you do, the attacker must reroll all his attack dice.<br>If you charge is inactive, reduce the difficulty of your <img class='inline-img' src='img/manBl2.png'> and <img class='inline-img' src='img/manBr2.png'> maneuvers." }
D.upgrades[129] = { name_FRA = "Han Solo", name_ENG = "Han Solo", id = 128, slot = "Gunner", add_Data = {0}, force = 0, charge = {0}, effect_FRA = "Avant de vous engager, vous pouvez effectuer une action <img class='inline-img' src='img/Fo W.png'> rouge.", effect_ENG = "Before you engage, you may perform a red <img class='inline-img' src='img/Fo W.png'> action." }
D.upgrades[130] = { name_FRA = "Largage de Cargaison", name_ENG = "Rigged Cargo Chute", id = 129, slot = "Illicit", add_Data = {0}, force = 0, charge = {1, "yellow", "0"}, effect_FRA = "Action : dépensez 1 <img class='inline-img' src='img/charge.png'>. Larguez 1 cargaison égarée en utilisant le gabarit 1<img class='inline-img' src='img/manSt2.png'>. Le cargaison égarée est considérée comme un obstacle débris.", effect_ENG = "ACTION : spend 1 <img class='inline-img' src='img/charge.png'>. Drop 1 cargo chute using the 1<img class='inline-img' src='img/manSt2.png'> template. The cargo chute is considered as a debris obstacle." }
D.upgrades[131] = { name_FRA = "Havoc", name_ENG = "Havoc", id = 130, slot = "Title", add_Data = {0}, force = 0, charge = {0}, effect_ENG = "Remove a <img class='inline-img' src='img/Crew.png'> slot. Add a <img class='inline-img' src='img/Tech.png'> and <img class='inline-img' src='img/Astromech.png'> slot.", effect_FRA = "Retire en emplacement <img class='inline-img' src='img/Crew.png'>. Ajoute <img class='inline-img' src='img/Tech.png'> et <img class='inline-img' src='img/Astromech.png'>." }
D.upgrades[132] = { name_FRA = "Lando Calrissian", name_ENG = "Lando Calrissian", id = 131, slot = "Crew", add_Data = {0}, force = 0, charge = {0}, effect_FRA = "Action : lancez 2 dés de défense. Pour chaque résultat <img class='inline-img' src='img/Fo W.png'> obtenu, gagnez 1 marqueur de concentration. Pour chaque résultat <img class='inline-img' src='img/Ev W.png'> obtenu, gagnez 1 marqueur d’évasion. Si les deux résultats sont vierges, le joueur adverse choisit concentration ou évasion. Vous gagnez 1 marqueur de ce type.", effect_ENG = "ACTION : Roll 2 defense dice. For each <img class='inline-img' src='img/Fo W.png'> result, receive 1 focus token. For each <img class='inline-img' src='img/Ev W.png'> result, receive 1 evade token. If both results are blank results, the opponent player chooses focus or evade. You receive 1 matching token." }
D.upgrades[133] = { name_FRA = "Hondo Ohnaka", name_ENG = "Hondo Ohnaka", id = 132, slot = "Crew", add_Data = {0}, force = 0, charge = {0}, effect_FRA = "Action : choisissez 2 vaisseaux à portée 1–3 de vous qui sont alliés entre eux. Coordonnez l’un des vaisseaux choisis, puis brouillez l’autre, en ignorant les restrictions de portée.", effect_ENG = "ACTION : choose 2 ships at range 1-3 of you that are friendly to each other. Coordinate one then jam the other one ignoring range restrictions." }
