D.upgrades[149] = { name_FRA = "Simulateur de Trajectoire", name_ENG = "Trajectory Simulator", id = 148, slot = "Tech", add_Data = {0}, force = 0, charge = {0}, effect_ENG = "During System phase, if you would drop or launch a bomb, you may launch it instead using the 5<img class='inline-img' src='img/manSt2.png'> template.", effect_FRA = "Pendant la phase de système, si vous êtes censé larguer ou lancer une bombe, vous pouvez la lancer en utilisant le gabarit 5<img class='inline-img' src='img/manSt2.png'> à la place." }
D.upgrades[150] = { name_FRA = "*Courageux", name_ENG = "*Brave", id = 149, slot = "Talent-special", add_Data = {0}, force = 0, charge = {0}, effect_FRA = "Quand vous défendez à portée 0-1, vous pouvez relancer un dé de défense.", effect_ENG = "While defending at range 0-1, you can reroll a defense die." }
D.upgrades[151] = { name_FRA = "Chopper", name_ENG = "Chopper", id = 150, slot = "Crew", add_Data = {0}, force = 0, charge = {0}, effect_FRA = "Action : Vous pouvez utiliser 1 <img class='inline-img' src='img/charge.png'> pour récupérer un bouclier.<br>Action : Dépenser un bouclier pour récupérer 1 <img class='inline-img' src='img/charge.png'>.", effect_ENG = "Action : You can use 1 <img class='inline-img' src='img/charge.png'> to recover a shield.<br>Action : Spend a Shield to recover 1 <img class='inline-img' src='img/charge.png'>." }
D.upgrades[152] = { name_FRA = "C1-10P", name_ENG = "C1-10P", id = 151, slot = "Astromech", add_Data = {0}, force = 0, charge = {2, "yellow", "0"}, effect_FRA = "  Après que vous exécutez entièrement une manoeuvre, si vos toutes vos <img class='inline-img' src='img/charge.png'> sont inactives, alors vous devez choisir un vaisseau à portée 0-1 qui gagne 1 jeton brouillage. Sinon, vous pouvez dépenser 1 <img class='inline-img' src='img/charge.png'> pour effectuer une action <img class='inline-img' src='img/Ev W.png'> rouge, même stressé. ", effect_ENG = "  After you fully execute a maneuver, if all your <img class='inline-img' src='img/charge.png'> are inactive, you must choose a ship at range 0-1 which gains 1 jam token. Otherwise, you may spend 1 <img class='inline-img' src='img/charge.png'> to perform a red <img class='inline-img' src='img/Ev W.png'> action, even while stressed." }
D.upgrades[153] = { name_FRA = "Ezra Bridger", name_ENG = "Ezra Bridger", id = 152, slot = "Gunner", force = 1, add_Data = {0}, charge = {0}, effect_FRA = "<img class='inline-img' src='img/forcestat.png'> Après avoir attaqué, vous pouvez dépenser 1 <img class='inline-img' src='img/fo.png'>. Dans ce cas, vous pouvez effectuer une attaque bonus de tourelle et améliorer jusqu'à 3 dés.", effect_ENG = "<img class='inline-img' src='img/forcestat.png'> After you perform an attack, you can spend 1 <img class='inline-img' src='img/fo.png'>. If you do, you can perform a bonus Turret attack and upgrade up to 3 dice." }
D.upgrades[154] = { name_FRA = "Kanan Jarrus", name_ENG = "Kanan Jarrus", id = 153, slot = "Crew", force = 1, add_Data = {0}, charge = {0}, effect_FRA = "<img class='inline-img' src='img/forcestat.png'> Après qu'un vaisseau allié à portée 0-2 exécute entièrement une manoeuvre blanche, vous pouvez dépenser 1 <img class='inline-img' src='img/fo.png'> pour retirer 1 jeton stress de ce vaisseau.", effect_ENG = "<img class='inline-img' src='img/forcestat.png'> After a friendly ship at range 0-2 fully executes a white maneuver, you may spend 1 <img class='inline-img' src='img/fo.png'> to remove 1 stress token from that ship." }
D.upgrades[155] = { name_FRA = "Hera Syndulla", name_ENG = "Hera Syndulla", id = 154, slot = "Crew", add_Data = {0}, force = 0, charge = {0}, effect_FRA = "Vous pouvez exécuter des manoeuvres rouges même stressé. Après avoir entièrement exécuté une manoeuvre rouge, si vous avez 3 jetons stress ou plus, retirez 1 jeton stress et subissez 1 dégat.", effect_ENG = "You can execute red maneuvers even while stressed. After you fully execute a red maneuver, if you have 3 or more stress tokens, remove 1 stress token and suffer 1 damage." }
D.upgrades[156] = { name_FRA = "Zeb Orellios", name_ENG = "Zeb Orellios", id = 155, slot = "Crew", add_Data = {0}, force = 0, charge = {0}, effect_FRA = "Vous pouvez attaquer à portée 0. Les vaisseaux ennemis peuvent effectuer des attaques <img class='inline-img' src='img/attackF.png'> à portée 0 contre vous.", effect_ENG = "You may perform attacks at range 0. Enemy ships may perform <img class='inline-img' src='img/attackF.png'> attacks at range 0 against you." }
D.upgrades[157] = { name_FRA = "Sabine Wren", name_ENG = "Sabine Wren", id = 156, slot = "Gunner", add_Data = {0}, force = 0, charge = {0}, effect_FRA = "Lorsque vous effectuez une attaque <img class='inline-img' src='img/Tarc.png'> ou <img class='inline-img' src='img/Barc.png'>, si l'attaque touche, chaque vaisseau allié à portée 0-2 du défenseur retire 1 jeton rouge ou orange.", effect_ENG = "When you perform a <img class='inline-img' src='img/Tarc.png'> or <img class='inline-img' src='img/Barc.png'> attack, if the attack hits, each ally ship at range 0-2 of the defender loses 1 red or orange Token." }
D.upgrades[158] = { name_FRA = "*Infatigable", name_ENG = "*Relentless", id = 157, slot = "Talent-special", add_Data = {0}, force = 0, charge = {0}, effect_FRA = "Lorsque vous recevez 1 jeton rouge (non-Acquisition), vous pouvez le placer sur cette amélioration à la place pour l'ignorer (1 max). Lorsque vous exécutez une manoeuvre bleue, vous ne pouvez retirer qu'un seul marqueur rouge. Vous pouvez retirer le marqueur présent sur cette amélioration.", effect_ENG = "When you would receive 1 red token (non Lock), you may place it on this upgrade instead to ignore it (max 1)). When you execute a blue maneuver, you may remove only one red token. You may remove the red token on this upgrade." }
D.upgrades[159] = { name_FRA = "Nute Gunray", name_ENG = "Nute Gunray", id = 158, slot = "Crew", add_Data = {0}, force = 0, charge = {0}, effect_FRA = "A la fin de la partie, si votre vaisseau est toujours en jeu, gagnez 3 points de scénario.", effect_ENG = "At the end of the game, if your ship is still in the play area, win 3 PO." }
D.upgrades[160] = { name_FRA = "Poggle le Bref", name_ENG = "Poggle the Lesser", id = 159, slot = "Crew", add_Data = {0}, force = 0, charge = {0}, effect_FRA = "ACTION : Si vous êtes à portée 0-1 d'un élément de scénario, vous pouvez le déplacer ou le relocaliser en utilisant le gabarit 2 <img class='inline-img' src='img/manSt2.png'>.", effect_ENG = "ACTION : If you are at range 0-1 of a scenario element, you may move it or relocate it using a 2<img class='inline-img' src='img/manSt2.png'> template." }
D.upgrades[161] = { name_FRA = "Missile Discorde", name_ENG = "Discord Missile", id = 160, slot = "Missile", add_Data = {0}, force = 0, charge = {1, "yellow", "0"}, effect_FRA = "Au début de la phase d’engagement, vous pouvez dépenser 1 marqueur de calcul et 1 <img class='inline-img' src='img/charge.png'> pour lancer 1 nuée de droïdes buzz (Agilité : 1, Coque : 1) en utilisant le gabarit 3 <img class='inline-img' src='img/manBl2.png'>, <img class='inline-img' src='img/manSt2.png'> ou <img class='inline-img' src='img/manBr2.png'>.<br>Après qu'un vaisseau ennemi traverse ou chevauche une nuée de droïdes buzz, relocalisez la dans la glissière avant ou arrière de ce vaisseau (il est à portée 0). La nuée de droides buzz ne peut pas chevaucher un objet de cette façon. Si la nuée ne peut pas être placée dans une glissière, la nuée et le vaisseau subissent 1 <img class='inline-img' src='img/hit.png'>.<br>Phase d'Engagement : à initiative 0, chaque vaisseau ennemi à portée 0 subit 1 <img class='inline-img' src='img/crit.png'> damage.", effect_ENG = "At the start of engagement phase, you may spend 1 calculate token and 1<img class='inline-img' src='img/charge.png'> to launch 1 buzz droid swarm (Agility : 1, Hull  : 1) using the 3 <img class='inline-img' src='img/manBl2.png'>, <img class='inline-img' src='img/manSt2.png'> or <img class='inline-img' src='img/manBr2.png'> template.<br>After an enemy ship moves through or overlaps the buzz droid swarm, relocate to its front or rear guides (you are at range 0 of this ship). The buzz droid swarm cannot overlap an object this way. If the swarm cannot be placed at either set of guides, the swarm and that ship each suffer 1 <img class='inline-img' src='img/hit.png'>.<br>Engagement Phase: At initiative 0, each enemy ship at range 0 of the swarm suffers 1 <img class='inline-img' src='img/crit.png'> damage." }
D.upgrades[162] = { name_FRA = "Droïde Sonde DRK1", name_ENG = "DRK1 Probe Droid", id = 161, slot = "Missile", add_Data = {0}, force = 0, charge = {2, "yellow", "0"}, effect_FRA = "  Pendant la phase de fin, vous pouvez dépenser 1 <img class='inline-img' src='img/charge.png'> pour larguer ou lancer 1 droïde sonde DRK1 (Agilité : 3, Coque : 1) en utilisant un gabarit de vitesse 3.<br>Lorsqu'un vaisseau allié verrouille un objet ou brouille un vaisseau, il peut mesurer la portée depuis le Droïde sonde DRK1.<br> Phase système : A initiative 0, vous pouvez vous relocaliser en utilisant 2<img class='inline-img' src='img/manBl2.png'>, 2<img class='inline-img' src='img/manSt2.png'>, or 2<img class='inline-img' src='img/manBr2.png'>.", effect_ENG = "  During End Phase, you may spend 1<img class='inline-img' src='img/charge.png'> to launch or drop 1 DRK1 Probe Droid (Agility : 3, Hull : 1) using the 3<img class='inline-img' src='img/manSt2.png'> template.<br>While a friendly ship locks an object or jams an enemy ship, it may measure range from DRK1 probe droid.<br>System Phase : At initiative 0, you may relocate using a 2<img class='inline-img' src='img/manBl2.png'>, 2 <img class='inline-img' src='img/manSt2.png'>, or 2<img class='inline-img' src='img/manBr2.png'>." }
D.upgrades[163] = { name_FRA = "Obus Energétiques", name_ENG = "Energy Cell Charge", id = 162, slot = "Missile", add_Data = {0}, force = 0, charge = {1, "yellow", "0"}, effect_FRA = " Attaque <img class='inline-img' src='img/Cc W.png'> : 3<img class='inline-img' src='img/attackF.png'> Portée 2-3 : dépensez 1 <img class='inline-img' src='img/charge.png'>. Tant que vous effectuez cette attaque, vous pouvez dépenser 1 marqueur de calcul pour changer 1 résultat <img class='inline-img' src='img/Fo W.png'> en un résultat <img class='inline-img' src='img/crit.png'>.<br>Action : récupérez la <img class='inline-img' src='img/charge.png'>.", effect_ENG = " Attack <img class='inline-img' src='img/Cc W.png'> : 3<img class='inline-img' src='img/attackF.png'> Range 2-3 : spend 1<img class='inline-img' src='img/charge.png'>. During this attack, you may spend 1 calculate token to modify 1 <img class='inline-img' src='img/Fo W.png'> result into a <img class='inline-img' src='img/crit.png'> result.<br>ACTION : recover the <img class='inline-img' src='img/charge.png'>." }
D.upgrades[164] = { name_FRA = "Calculs Indépendants", name_ENG = "Independant Calculation", id = 163, slot = "Calculator", add_Data = {0}, force = 0, charge = {0}, effect_FRA = "Tant que vous effectuez une action rouge <img class='inline-img' src='img/Cc W.png'>, gagnez 1 marqueur de calcul supplémentaire. Lorsque vous effectuez une action <img class='inline-img' src='img/Cc W.png'>, vous pouvez faire une action <img class='inline-img' src='img/Cc W.png'> rouge à la place. Les autres vaisseaux ne peuvent pas dépenser vos marqueurs de calcul.", effect_ENG = "While you perform a red <img class='inline-img' src='img/Cc W.png'> action, gain 1 additional calculate token. When you perform a <img class='inline-img' src='img/Cc W.png'> action, you may perform a red <img class='inline-img' src='img/Cc W.png'> action instead. Other ships cannot spend your calculate tokens." }
D.upgrades[165] = { name_FRA = "Kalani (Solitaire)", name_ENG = "Kalani (Solitary)", id = 164, slot = "Crew", add_Data = {0}, force = 0, charge = {1, "addCcWAction", ""}, effect_FRA = "Après qu’un vaisseau ennemi a exécuté une manœuvre, s’il est dans le <img class='inline-img' src='img/bulls.png'> d’un vaisseau allié à portée 0–3, vous pouvez dépenser 1 <img class='inline-img' src='img/charge.png'>. Dans ce cas, ce vaisseau allié verrouille ce vaisseau ennemi, puis gagne 1 marqueur de stress.<br>Ajoute l'action <img class='inline-img' src='img/Cc W.png'>", effect_ENG = "After an enemy ship executes a maneuver, if it is in the <img class='inline-img' src='img/bulls.png'> of a friendly ship at range 0-3, you may spend 1 <img class='inline-img' src='img/charge.png'>. If you do, this friendly ship locks this enemy ship, then receive 1 stress token.<br>Add the <img class='inline-img' src='img/Cc W.png'> action." }
D.upgrades[166] = { name_FRA = "Kraken (Solitaire)", name_ENG = "Kraken (Solitary)", id = 165, slot = "Crew", add_Data = {0}, force = 0, charge = {1, "addCcWAction", ""}, effect_FRA = "Pendant la phase de fin, vous pouvez choisir jusqu’à 3 vaisseaux alliés à portée 0-3. Dans ce cas, chacun de ces vaisseaux ne retire pas 1 marqueur de calcul.<br>Ajoute l'action <img class='inline-img' src='img/Cc W.png'>.", effect_ENG = "During End Phase, you may choose up to 3 friendly ships at range 0-3. If you do, each of these ships don't remove 1 calculate token.<br>Add the <img class='inline-img' src='img/Cc W.png'> action." }
D.upgrades[167] = { name_FRA = "AUT-0 (Solitaire)", name_ENG = "AUT-0 (Solitary)", id = 166, slot = "Crew", add_Data = {0}, force = 0, charge = {1, "addCcWAction", ""}, effect_FRA = "Avant de vous engager, vous pouvez transférer un jeton calcul à un vaisseau calculateur à portée 0-3. Dans ce cas, ce vaisseau effectue une attaque bonus. Vous gagnez 1 jeton désarmé.<br>Ajoute l'action <img class='inline-img' src='img/Cc W.png'>.", effect_ENG = "Before you engage, you may transfer 1 calculate token to a calculating ship at range 0-3. If you do, this ship performs a bonus attack. Receive 1 disarm token.<br>Add the <img class='inline-img' src='img/Cc W.png'> action." }
D.upgrades[168] = { name_FRA = "Linwodo (Solitaire)", name_ENG = "Linwodo (Solitary)", id = 167, slot = "Crew", add_Data = {0}, force = 0, charge = {1, "addCcWAction", ""}, effect_FRA = "Après qu'un vaisseau allié à portée 0-3 avec <img class='inline-img' src='img/Cc W.png'> dans sa barre d'action a été détruit, chaque vaisseau allié à portée 0-3 avec <img class='inline-img' src='img/Cc W.png'> dans sa barre d'action gagne 1 marqueur de calcul.<br>Ajoute l'action <img class='inline-img' src='img/Cc W.png'>.", effect_ENG = "After a friendly ship at range 0-3 with <img class='inline-img' src='img/Cc W.png'> in its action bar has been destroyed, each friendly ship at range 0-3 with <img class='inline-img' src='img/Cc W.png'> in its action bar receives 1 calculate token.<br>Add the <img class='inline-img' src='img/Cc W.png'> action." }
D.upgrades[169] = { name_FRA = "Général Grievous", name_ENG = "General Grievous", id = 168, slot = "Crew", add_Data = {0}, force = 0, charge = {1, "yellow", "0"}, effect_FRA = "Tant que vous défendez, après l’étape « Neutraliser les résultats », s’il y a au moins 2 résultats <img class='inline-img' src='img/hit.png'>/<img class='inline-img' src='img/crit.png'>, vous pouvez dépenser 1 <img class='inline-img' src='img/charge.png'> pour annuler 1 résultat <img class='inline-img' src='img/hit.png'> ou <img class='inline-img' src='img/crit.png'>.<br>Après qu’un vaisseau allié a été détruit, récupérez 1 <img class='inline-img' src='img/charge.png'>.", effect_ENG = "While you defend, after the 'Neutralize Results' step, if there are at least 2 results <img class='inline-img' src='img/hit.png'>/<img class='inline-img' src='img/crit.png'>, you may spend 1 <img class='inline-img' src='img/charge.png'> to cancel 1 <img class='inline-img' src='img/hit.png'> or <img class='inline-img' src='img/crit.png'> result.<br>After a friendly ship is destroyed, recover 1 <img class='inline-img' src='img/charge.png'>." }
D.upgrades[170] = { name_FRA = "*Héroïque", name_ENG = "*Heroic", id = 169, slot = "Talent-special", add_Data = {0}, force = 0, charge = {0}, effect_FRA = "Tant que vous défendez ou effectuez une attaque, si vous n'avez que des résultats vierges et au moins 2 résultats, vous pouvez relancer n'importe quel nombre de vos dés.", effect_ENG = "When you defend or perform an attack, if all of your results are blank and there are at least 2 results, you may reroll any number of your dice." }
D.upgrades[171] = { name_FRA = "Kaydel Connix", name_ENG = "Kaydel Connix", id = 170, slot = "Crew", add_Data = {0}, force = 0, charge = {0}, effect_FRA = "Après avoir révélé votre cadran, vous pouvez régler votre cadran sur une manoeuvre basique de vitesse +1. Lorsque vous exécutez cette manoeuvre, augmentez sa difficulté.", effect_ENG = "After you reveal your dial, you may set your dial to a basic maneuver of the next higher speed. While you execute that maneuver, increase its difficulty." }
D.upgrades[172] = { name_FRA = "Rose Tico", name_ENG = "Rose Tico", id = 171, slot = "Crew", add_Data = {0}, force = 0, charge = {0}, effect_FRA = "Lorsque vous défendez ou attaquez, vous pouvez dépenser 1 de vos résultats pour verrouiller l'adversaire.", effect_ENG = "While you defend or perform an attack, you may spend 1 of your results to acquire a lock on the enemy ship." }
D.upgrades[173] = { name_FRA = "Peinture Ferrosphère", name_ENG = "Ferrosphere Paint", id = 172, slot = "Tech", add_Data = {0}, force = 0, charge = {0}, effect_FRA = "Après qu'un ennemi vous a verrouillé, il doit choisir de gagner un jeton stress ou de retirer son verrouillage.", effect_ENG = "After an enemy ship locks you, that ship gains 1 stress token unless it chooses to break its lock." }
D.upgrades[174] = { name_FRA = "Finn", name_ENG = "Finn", id = 173, slot = "Gunner", add_Data = {0}, force = 0, charge = {0}, effect_FRA = "Lorsque vous attaquez ou effectuez une attaque principale, si le vaisseau ennemi est dans votre <img class='inline-img' src='img/attackF.png'>, vous pouvez ajouter 1 résultat vierge (ce dé peut être relancé ou modifié)", effect_ENG = "While you defend or perform a primary attack, if the enemy ship is in your <img class='inline-img' src='img/attackF.png'>, you may add 1 blank result to your roll (this die can be rerolled or otherwise modified)" }
D.upgrades[175] = { name_FRA = "Rey", name_ENG = "Rey", id = 174, slot = "Gunner", force = 1, add_Data = {0}, charge = {0}, effect_FRA = "<img class='inline-img' src='img/forcestat.png'> Lorsque vous défendez ou attaquez, si le vaisseau ennemi est dans votre <img class='inline-img' src='img/Tarc.png'>, vous pouvez dépenser 1 <img class='inline-img' src='img/fo.png'> pour modifier l'un de vos résultats vierges en <img class='inline-img' src='img/hit.png'> ou <img class='inline-img' src='img/Ev W.png'>.", effect_ENG = "<img class='inline-img' src='img/forcestat.png'> While you defend or perform an attack, if the enemy ship is in your <img class='inline-img' src='img/Tarc.png'>, you may spend 1 <img class='inline-img' src='img/fo.png'> to change 1 of your blank results to a <img class='inline-img' src='img/hit.png'> or <img class='inline-img' src='img/Ev W.png'> result." }
D.upgrades[176] = { name_FRA = "M9-G8", name_ENG = "M9-G8", id = 175, slot = "Astromech", add_Data = {0}, force = 0, charge = {0}, effect_FRA = "Lorsqu'un vaisseau que vous avez verrouillé attaque, vous pouvez choisir 1 dé d'attaque. Dans ce cas, l'attaquant relance ce dé.", effect_ENG = "While a ship you are locking performs an attack, you may choose 1 attack die. If you do, the attacker rerolls that die." }
D.upgrades[177] = { name_FRA = "Astromech BB", name_ENG = "BB Astromech", id = 176, slot = "Astromech", add_Data = {0}, force = 0, charge = {2, "yellow", "0"}, effect_FRA = "  Pendant la phase de système, vous pouvez dépenser 1 <img class='inline-img' src='img/charge.png'> pour effectuer une action <img class='inline-img' src='img/Br W.png'>.", effect_ENG = "  During System Phase, you may spend 1 <img class='inline-img' src='img/charge.png'> to perform a <img class='inline-img' src='img/Br W.png'> action." }
D.upgrades[178] = { name_FRA = "BB-8", name_ENG = "BB-8", id = 177, slot = "Astromech", add_Data = {0}, force = 0, charge = {2, "yellow", "0"}, effect_FRA = "  Avant d'excuter une manoeuvre, vous pouvez dépenser 1 <img class='inline-img' src='img/charge.png'> pour effectuer une action <img class='inline-img' src='img/Br W.png'> ou <img class='inline-img' src='img/Bo W.png'>", effect_ENG = "  Before executing a maneuver, you may spend 1 <img class='inline-img' src='img/charge.png'> to perform a <img class='inline-img' src='img/Br W.png'> or <img class='inline-img' src='img/Bo W.png'> action" }
D.upgrades[179] = { name_FRA = "R6-D8", name_ENG = "R6-D8", id = 178, slot = "Astromech", add_Data = {0}, force = 0, charge = {0}, effect_FRA = "Tant que vous effectuez une attaque, vous pouvez relancer un nombre de dés d’attaque inférieur ou égal au nombre de vaisseaux alliés à portée 0–3 qui ont le défenseur dans leur <img class='inline-img' src='img/bulls.png'>.", effect_ENG = "While you perform an attack, you may reroll as many attack dice as the number of friendly ships which has the defender in their <img class='inline-img' src='img/bulls.png'> at range 0-3." }
D.upgrades[180] = { name_FRA = "R5-X3", name_ENG = "R5-X3", id = 179, slot = "Astromech", add_Data = {0}, force = 0, charge = {2, "yellow", "0"}, effect_FRA = "  Avant votre activation ou avant de vous engager, vous pouvez dépenser 1 <img class='inline-img' src='img/charge.png'> pour ignorer les obstacles jusqu’à la fin de cette phase.", effect_ENG = "  Before you activate or engage, you may spend 1 <img class='inline-img' src='img/charge.png'> to ignore obstacles until the end of this phase." }
D.upgrades[181] = { name_FRA = "*Fanatique", name_ENG = "*Fanatical", id = 180, slot = "Talent-special", add_Data = {0}, force = 0, charge = {0}, effect_FRA = "Lorsque vous effectuez une attaque principale, si vous n'êtes pas protégé, vous pouvez modifier 1 résultat <img class='inline-img' src='img/Fo W.png'> en <img class='inline-img' src='img/hit.png'>", effect_ENG = "While you perform a primary attack, if you are not shielded, you may change 1 <img class='inline-img' src='img/Fo W.png'> result to a <img class='inline-img' src='img/hit.png'> result." }
D.upgrades[182] = { name_FRA = "Général Hux", name_ENG = "General Hux", id = 181, slot = "Crew", add_Data = {0}, force = 0, charge = {0}, effect_FRA = "Lorsque vous effectuez une action blanche <img class='inline-img' src='img/Co W.png'>, vous pouvez la traiter comme rouge. Dans ce cas, vous pouvez coordonner jusqu'à 2 vaisseaux supplémentaires du même type, et chaque vaisseau coordonné doit effectuer la même action en la considérant comme rouge.", effect_ENG = "While you perform a white <img class='inline-img' src='img/Co W.png'> action, you may treat it as red. If you do, you may coordinate up to 2 additional ships of the same ship type, and each ship you coordinate must perform the same action, treating that action as red." }
D.upgrades[183] = { name_FRA = "Jace Rucklin", name_ENG = "Jace Rucklin", id = 182, slot = "Gunner", add_Data = {0}, force = 0, charge = {0}, effect_FRA = "Au début de la phase d'engagement, vous pouvez choisir un vaisseau allié dans votre arc de tir. Dans ce cas, ce vaisseau gagne 1 jeton contrainte.<br>Lorsque vous attaquez, vous pouvez relancer jusqu'à 1 dé pour chaque vaisseau dans votre arc de tir avec 1 ou plusieurs jeton rouge ou orange (non lock).", effect_ENG = "At the start of the Engagement Phase, you may choose a friendly ship in your firing arc. If you do, that ship gains 1 strain token.<br>While you perform an attack, you may reroll up to 1 die for each ship in the attack arc with 1 or more non-lock red or orange tokens." }
D.upgrades[184] = { name_FRA = "Technicien en Munition du Premier Ordre", name_ENG = "First Order Ordnance Tech", id = 183, slot = "Gunner", add_Data = {0}, force = 0, charge = {1, "addLoWAction", "linkUnWAction"}, effect_FRA = "ajoute <img class='inline-img' src='img/Lo W.png'> -> <img class='inline-img' src='img/UN W.png'>", effect_ENG = "Adds <img class='inline-img' src='img/Lo W.png'> -> <img class='inline-img' src='img/UN W.png'>" }
D.upgrades[185] = { name_FRA = "Artilleur des Forces Spéciales", name_ENG = "Special Forces Gunner", id = 184, slot = "Gunner", add_Data = {0}, force = 0, charge = {0}, effect_FRA = "Lorsque vous effectuez une attaque principale <img class='inline-img' src='img/attackF.png'>, si votre <img class='inline-img' src='img/Tarc.png'> est dans votre <img class='inline-img' src='img/attackF.png'>, vous pouvez lancer 1 dé d'attaque supplémentaire.<br>Après avoir effectué une attaque principale <img class='inline-img' src='img/attackF.png'>, si votre <img class='inline-img' src='img/Tarc.png'> est dans votre <img class='inline-img' src='img/attackB.png'>, vous pouvez effectuer une attaque bonus principale <img class='inline-img' src='img/Tarc.png'>", effect_ENG = "While you perform a primary <img class='inline-img' src='img/attackF.png'> attack, if your <img class='inline-img' src='img/Tarc.png'> is in your <img class='inline-img' src='img/attackF.png'> , you may roll 1 additional attack die.<br>After you perform a primary <img class='inline-img' src='img/attackF.png'> attack, if your <img class='inline-img' src='img/Tarc.png'> is in your <img class='inline-img' src='img/attackB.png'>, you may perform a bonus primary <img class='inline-img' src='img/Tarc.png'> attack." }
D.upgrades[186] = { name_FRA = "Kylo Ren", name_ENG = "Kylo Ren", id = 185, slot = "Crew", force = 1, add_Data = {0}, charge = {0}, effect_FRA = "<img class='inline-img' src='img/forcestat.png'> Action: Choisissez 1 vaisseau ennemi à portée 1-3. Dans ce cas, dépensez 1 <img class='inline-img' src='img/fo.png'> pour assigner la condition 'Je vais te montrer le côté obscur' à ce vaisseau", effect_ENG = "<img class='inline-img' src='img/forcestat.png'> Action: Choose 1 enemy ship at range 1-3. If you do, spend 1 <img class='inline-img' src='img/fo.png'> to assign the I'll Show You The Dark Side condition to the ship." }
D.upgrades[187] = { name_FRA = "Cellules Energétiques au Deuterium", name_ENG = "Deuterium Power Cells", id = 186, slot = "Tech", add_Data = {0}, force = 0, charge = {2, "yellow", "0"}, effect_FRA = "  Pendant la phase système, vous pouvez dépenser 1 <img class='inline-img' src='img/charge.png'> et gagner 1 jeton désarmé pour récupérer 1 bouclier.<br>Lorsque vous devriez recevoir 1 jeton non lock, si vous n'êtes pas stressé, vous pouvez dépenser 1 <img class='inline-img' src='img/charge.png'> pour gagner 1 jeton stress à la place.", effect_ENG = "  During the System Phase, you may spend 1 <img class='inline-img' src='img/charge.png'> and gain 1 disarm token to recover 1 shield.<br>Before you would gain 1 non-lock token, if you are not stressed, you may spend 1 <img class='inline-img' src='img/charge.png'> to gain 1 stress token instead." }
D.upgrades[188] = { name_FRA = "Codes Biohexacrypt", name_ENG = "Biohexacrypt Codes", id = 187, slot = "Calculator", add_Data = {0}, force = 0, charge = {0}, effect_FRA = "Lorsque vous coordonnez ou brouillez, si vous avez un verrouillage sur un vaisseau, vous pouvez choisir ce vaisseau en ignorant les restrictions de portée.", effect_ENG = "While you coordinate or jam, if you have a lock on a ship, you may choose that ship, ignoring range restrictions." }
D.upgrades[189] = { name_FRA = "Capitaine Phasma", name_ENG = "Captain Phasma", id = 188, slot = "Crew", add_Data = {0}, force = 0, charge = {0}, effect_FRA = "A la fin de la phase d'engagement, chaque vaisseau ennemi à portée 0-1 qui n'est pas stressé reçoit un jeton stress", effect_ENG = "At the end of the Engagement Phase, each enemy ship at range 0-1 that is not stressed gains 1 stress token." }
D.upgrades[190] = { name_FRA = "Officier de Pont Thanison", name_ENG = "Petty Officer Thanison", id = 189, slot = "Crew", add_Data = {0}, force = 0, charge = {0}, effect_FRA = "Pendant la phase d'activation ou d'engagement, après qu'un vaisseau ennemi dans votre <img class='inline-img' src='img/attackF.png'> à portée 0-1 reçoit 1 jeton rouge ou orange, si vous n'êtes pas stressé, vous pouvez recevoir 1 jeton stress. Dans ce cas, ce vaisseau reçoit 1 jeton supplémentaire du même type.", effect_ENG = "During the Activation or Engagement Phase, after an enemy ship in your <img class='inline-img' src='img/attackF.png'> at range 0-1 gains a red or orange token, if you are not stressed, you may gain 1 stress token. If you do, that ship gains 1 additional token of the type that it gained." }
D.upgrades[191] = { name_FRA = "*Efficace", name_ENG = "*Efficient", id = 190, slot = "Talent-special", add_Data = {0}, force = 0, charge = {0}, effect_FRA = "Lorsque vous détruisez un vaisseau ennemi après l'avoir attaqué, vous pouvez retirer un jeton orange ou rouge, puis vous pouvez effectuer une action.", effect_ENG = "When you destroy an enemy ship, you may remove an orange or red token from yourself, then perform an action." }
D.upgrades[192] = { name_FRA = "Rukh", name_ENG = "Rukh", id = 191, slot = "Crew", add_Data = {0}, force = 0, charge = {0}, effect_FRA = "Mise en place : Assignez la condition 'Proie' à un vaisseau. A la fin de la phase d'activation, si vous êtes à portée 0-1 du vaisseau avec la condition 'Proie', il gagne 1 jeton épuisement et 1 jeton contrainte.", effect_ENG = "SETUP : assign the 'Prey' condition to a ship. At the end of activation phase, if you are at range 0-1 of the ship with the prey condition, it gains 1 deplete and 1 strain token." }
D.upgrades[193] = { name_FRA = "Grand Inquisiteur", name_ENG = "Grand Inquisitor", id = 192, slot = "Crew", force = 1, add_Data = {0}, charge = {0}, effect_FRA = "<img class='inline-img' src='img/forcestat.png'> Après qu'un vaisseau ennemi à portée 0-2 a révélé son cadran, vous pouvez dépenser 1 <img class='inline-img' src='img/fo.png'> pour effectuer 1 action blanche de votre barre d'action, en considérant cette action comme rouge.", effect_ENG = "<img class='inline-img' src='img/forcestat.png'>After an enemy ship at range 0-2 revealed its dial, you may spend 1 <img class='inline-img' src='img/fo.png'> to perform a white action of your action bar, considering it as red." }
D.upgrades[194] = { name_FRA = "Ciena Ree", name_ENG = "Ciena Ree", id = 193, slot = "Crew", add_Data = {0}, force = 0, charge = {0}, effect_FRA = "Après avoir attaqué, vous pouvez verrouiller le défenseur", effect_ENG = "After you perform an attack, you may acquire a lock on the defender" }
