D.upgrades[206] = { name_FRA = "Calculs en Réseau", name_ENG = "Networked Calculations", id = 205, slot = "Calculator", add_Data = {0}, force = 0, charge = {0}, effect_FRA = "Lorsque vous défendez ou attaquez, you pouvez dépenser 1 jeton calcul d'un vaisseau allié à portée 0-1 pour modifier 1 résultat <img class='inline-img' src='img/Fo W.png'> en résultat <img class='inline-img' src='img/hit.png'> ou <img class='inline-img' src='img/Ev W.png'>.", effect_ENG = "When you defend or attack, you may spend 1 calculate token from an allied ship at range 0-1 to change 1 <img class='inline-img' src='img/Fo W.png'> result to a <img class='inline-img' src='img/hit.png'> or <img class='inline-img' src='img/Ev W.png'> result." }
D.upgrades[207] = { name_FRA = "Missile Ionique", name_ENG = "Ion Missile", id = 206, slot = "Weapon", add_Data = {0}, force = 0, charge = {1, "yellow", "0"}, effect_FRA = " Attaque (<img class='inline-img' src='img/Lo W.png'>) : 3<img class='inline-img' src='img/attackF.png'> portée 2-3  : dépensez 1 <img class='inline-img' src='img/charge.png'>. Si cette attaque touche, dépensez 1 résultat <img class='inline-img' src='img/hit.png'> ou <img class='inline-img' src='img/crit.png'> pour faire subir 1 dégât <img class='inline-img' src='img/hit.png'> au défenseur. Tous les résultats <img class='inline-img' src='img/hit.png'>/<img class='inline-img' src='img/crit.png'> restants infligent des marqueurs ioniques au lieu des dégâts.", effect_ENG = " Attack (<img class='inline-img' src='img/Lo W.png'>): 3<img class='inline-img' src='img/attackF.png'> range 2-3: spend 1 <img class='inline-img' src='img/charge.png'>. If this attack hits, spend 1 <img class='inline-img' src='img/hit.png'> or <img class='inline-img' src='img/crit.png'> result to deal 1 <img class='inline-img' src='img/hit.png'> damage to the defender. All remaining <img class='inline-img' src='img/hit.png'>/<img class='inline-img' src='img/crit.png'> results deal ion tokens instead of damage." }
D.upgrades[208] = { name_FRA = "Missile à Tête Chercheuse", name_ENG = "Homing Missile", id = 207, slot = "Weapon", add_Data = {0}, force = 0, charge = {1, "yellow", "0"}, effect_FRA = " Attaque (<img class='inline-img' src='img/Lo W.png'>) : 2<img class='inline-img' src='img/attackF.png'> Portée 2-3 : dépensez 1 <img class='inline-img' src='img/charge.png'>. Après avoir lancé les dés d'attaque, annulez tous les résultats, et ajoutez 2 résultats <img class='inline-img' src='img/hit.png'>.", effect_ENG = " Attack (<img class='inline-img' src='img/Lo W.png'>): 2<img class='inline-img' src='img/attackF.png'> Range 2-3: spend 1 <img class='inline-img' src='img/charge.png'>. After rolling attack dice, cancel all results and add 2 <img class='inline-img' src='img/hit.png'> results." }
D.upgrades[209] = { name_FRA = "Missiles Groupés", name_ENG = "Cluster Missiles", id = 208, slot = "Weapon", add_Data = {0}, force = 0, charge = {1, "yellow", "0"}, effect_FRA = " Attaque (<img class='inline-img' src='img/Lo W.png'>) : 3<img class='inline-img' src='img/attackF.png'> Portée 1-2 : Après avoir résolu l’attaque, vous pouvez choisir un autre vaisseau à portée 0-1 du défenseur. Lancez 3 dés d’attaque : assignez autant de marqueurs de contrainte que de résultats <img class='inline-img' src='img/Fo W.png'>, puis le vaisseau ciblé doit se défendre en considérant les autres résultats comme un jet d’attaque.", effect_ENG = " Attack (<img class='inline-img' src='img/Lo W.png'>): 3<img class='inline-img' src='img/attackF.png'> Range 1-2: After the attack is resolved, you may choose another ship at range 0-1 of the defender. Roll 3 attack dice: assign as many strain tokens as <img class='inline-img' src='img/Fo W.png'> results, then the targeted ship defends considering the other results as an attack roll." }
D.upgrades[210] = { name_FRA = "Traceurs XX-23 S", name_ENG = "XX-23 S-Thread Tracers", id = 209, slot = "Weapon", add_Data = {0}, force = 0, charge = {2, "yellow", "0"}, effect_FRA = "  Attaque (<img class='inline-img' src='img/Cc W.png'>, <img class='inline-img' src='img/Fo W.png'> ou <img class='inline-img' src='img/Lo W.png'>) : 3<img class='inline-img' src='img/attackF.png'> Portée 1-3 : dépensez 1 <img class='inline-img' src='img/charge.png'>. Si cette attaque touche, chaque vaisseau allié à portée 1–3 du défenseur peut verrouiller le défenseur. Puis annulez tous les résultats des dés.", effect_ENG = "  Attack (<img class='inline-img' src='img/Cc W.png'>, <img class='inline-img' src='img/Fo W.png'> or <img class='inline-img' src='img/Lo W.png'>): 3<img class='inline-img' src='img/attackF.png'> Range 1-3: spend 1 <img class='inline-img' src='img/charge.png'>. If this attack hits, each friendly ship at range 1-3 of the defender may acquire a lock on the defender. Then cancel all dice results." }
D.upgrades[211] = { name_FRA = "Missile Harpon", name_ENG = "Harpoon Missile", id = 210, slot = "Weapon", add_Data = {0}, force = 0, charge = {1, "yellow", "0"}, effect_FRA = " Attaque (<img class='inline-img' src='img/Fo W.png'>) : 3<img class='inline-img' src='img/attackF.png'> Portée 1-2 : Si l’attaque touche, annulez tous les dés. Puis le défenseur reçoit une carte de dégât face cachée et autant de jetons tractage qu'il faudrait pour tracter votre vaisseau. (ex: si vous êtes un gros vaisseau, vous infligez 3 jetons tractage)", effect_ENG = " Attack (<img class='inline-img' src='img/Fo W.png'>): 3<img class='inline-img' src='img/attackF.png'> Range 1-2: If the attack hits, cancel all dice. Then the defender receives 1 face-down damage card and as many tractor tokens as needed to tractor your ship. (ex: if you are a large ship, you deal 3 tractor tokens)" }
D.upgrades[212] = { name_FRA = "Torpille à Plasma", name_ENG = "Plasma Torpedo", id = 211, slot = "Weapon", add_Data = {0}, force = 0, charge = {1, "yellow", "0"}, effect_FRA = " 3<img class='inline-img' src='img/bulls.png'> portée 1-2: dépensez 1 <img class='inline-img' src='img/charge.png'>. Lors de l’étape « Neutraliser les résultats », les résultats <img class='inline-img' src='img/crit.png'> sont annulés avant les résultats <img class='inline-img' src='img/hit.png'>. Après que cette attaque a touché, le défenseur perd 1 bouclier. Gagnez un jeton de désarmement.", effect_ENG = " 3<img class='inline-img' src='img/bulls.png'> range 1-2: spend 1 <img class='inline-img' src='img/charge.png'>. During the 'Neutralize Results' step, <img class='inline-img' src='img/crit.png'> results are canceled before <img class='inline-img' src='img/hit.png'> results. After this attack hits, the defender loses 1 shield. Gain 1 disarm token." }
D.upgrades[213] = { name_FRA = "Torpille à Proton Avancée", name_ENG = "Adv. Proton Torpedo", id = 212, slot = "Weapon", add_Data = {0}, force = 0, charge = {1, "yellow", "0"}, effect_FRA = " 4<img class='inline-img' src='img/attackBULL.png'> Portée 1 : dépensez 1 <img class='inline-img' src='img/charge.png'>. Modifiez un <img class='inline-img' src='img/hit.png'> en <img class='inline-img' src='img/crit.png'>. Gagnez un marqueur désarmement.", effect_ENG = " 4<img class='inline-img' src='img/attackBULL.png'> Range 1: spend 1 <img class='inline-img' src='img/charge.png'>. Change 1 <img class='inline-img' src='img/hit.png'> to <img class='inline-img' src='img/crit.png'>. Gain 1 disarm token." }
D.upgrades[214] = { name_FRA = "Torpille à Concussion", name_ENG = "Concussion Torpedo", id = 213, slot = "Weapon", add_Data = {0}, force = 0, charge = {1, "yellow", "0"}, effect_FRA = " 2<img class='inline-img' src='img/bulls.png'> Portée 2-3 : dépensez 1 <img class='inline-img' src='img/charge.png'>. Après que cette attaque a touché, chaque vaisseau à portée 0–1 du défenseur expose 1 de ses cartes de dégât. Gagnez un jeton désarmement.", effect_ENG = " 2<img class='inline-img' src='img/bulls.png'> Range 2-3: spend 1 <img class='inline-img' src='img/charge.png'>. After this attack hits, each ship at range 0-1 of the defender reveals 1 of its damage cards. Gain 1 disarm token." }
D.upgrades[215] = { name_FRA = "Roquette à Proton", name_ENG = "Proton Rocket", id = 214, slot = "Weapon", add_Data = {0}, force = 0, charge = {1, "yellow", "0"}, effect_FRA = " Attaque :  3<img class='inline-img' src='img/attackF.png'> Portée 1: dépensez 1 <img class='inline-img' src='img/charge.png'>. Si le défenseur est dans votre <img class='inline-img' src='img/bulls.png'>, vous pouvez améliorer 1 résultat <img class='inline-img' src='img/hit.png'> en <img class='inline-img' src='img/crit.png'>. Gagnez un jeton épuisement.", effect_ENG = " Attack (<img class='inline-img' src='img/Lo W.png'>): 3<img class='inline-img' src='img/attackF.png'> Range 1: spend 1 <img class='inline-img' src='img/charge.png'>. If the defender is in your <img class='inline-img' src='img/bulls.png'>, you may upgrade 1 <img class='inline-img' src='img/hit.png'> result to a <img class='inline-img' src='img/crit.png'>. Gain 1 deplete token." }
D.upgrades[216] = { name_FRA = "Rayon de Brouillage", name_ENG = "Jamming Beam", id = 215, slot = "Weapon", add_Data = {0}, force = 0, charge = {0}, effect_FRA = " 3<img class='inline-img' src='img/attackF.png'> Portée 1-2, Attaque : si cette attaque touche, tous les résultats <img class='inline-img' src='img/hit.png'>/<img class='inline-img' src='img/crit.png'> infligent des marqueurs de brouillage au lieu des dégâts.", effect_ENG = "3<img class='inline-img' src='img/attackF.png'> Range 1-2, Attack: if this attack hits, all <img class='inline-img' src='img/hit.png'>/<img class='inline-img' src='img/crit.png'> results deal jam tokens instead of damage." }
D.upgrades[217] = { name_FRA = "Rayon Tracteur", name_ENG = "Tractor Beam", id = 216, slot = "Weapon", add_Data = {0}, force = 0, charge = {0}, effect_FRA = " 3<img class='inline-img' src='img/attackF.png'> Portée 1-3, Attaque : si cette attaque touche, tous les résultats <img class='inline-img' src='img/hit.png'>/<img class='inline-img' src='img/crit.png'> infligent des marqueurs de rayon tracteur au lieu des dégâts.", effect_ENG = "3<img class='inline-img' src='img/attackF.png'> Range 1-3, Attack: if this attack hits, all <img class='inline-img' src='img/hit.png'>/<img class='inline-img' src='img/crit.png'> results deal tractor beam tokens instead of damage." }
D.upgrades[218] = { name_FRA = "Canon Ionique", name_ENG = "Ion Cannon", id = 217, slot = "Weapon", add_Data = {0}, force = 0, charge = {0}, effect_FRA = "3<img class='inline-img' src='img/attackF.png'> Portée 1-3 , Attaque : si cette attaque touche, dépensez 1 résultat <img class='inline-img' src='img/hit.png'> ou <img class='inline-img' src='img/crit.png'> pour faire subir 1 dégât au défenseur. Tous les résultats <img class='inline-img' src='img/hit.png'>/<img class='inline-img' src='img/crit.png'> restants infligent des marqueurs ioniques au lieu des dégâts.", effect_ENG = "3<img class='inline-img' src='img/attackF.png'> Range 1-3, Attack: if this attack hits, spend 1 <img class='inline-img' src='img/hit.png'> or <img class='inline-img' src='img/crit.png'> result to deal 1 damage to the defender. All remaining <img class='inline-img' src='img/hit.png'>/<img class='inline-img' src='img/crit.png'> results deal ion tokens instead of damage." }
D.upgrades[219] = { name_FRA = "Canon Laser Lourd", name_ENG = "Heavy Laser Cannon", id = 218, slot = "Weapon", add_Data = {0}, force = 0, charge = {0}, effect_FRA = "4<img class='inline-img' src='img/attackF.png'> Portée 2-3, Attaque : Si le défenseur n’est pas dans le <img class='inline-img' src='img/bulls.png'>, alors dégradez 4 dés d'attaque.", effect_ENG = "4<img class='inline-img' src='img/attackF.png'> Range 2-3, Attack: If the defender is not in the <img class='inline-img' src='img/bulls.png'>, then downgrade 4 attack dice." }
D.upgrades[220] = { name_FRA = "Tir Habile", name_ENG = "Trick Shot", id = 219, slot = "Talent-shooting", add_Data = {0}, force = 0, charge = {0}, effect_FRA = "Lorsque vous attaquez, si l'attaque qui est obstruée par un obstacle ou si la cible est à portée 0 d'un obstacle, lancez 1 dé d’attaque supplémentaire.", effect_ENG = "While you attack, if the attack is obstructed by an obstacle or if the target is at range 0 of an obstacle, roll 1 additional attack die." }
D.upgrades[221] = { name_FRA = "Feinte", name_ENG = "Juke", id = 220, slot = "Talent-piloting", add_Data = {0}, force = 0, charge = {0}, effect_FRA = "Lorsque vous attaquez, si vous avez un marqueur d'évasion, vous pouvez changer 1 des résultats <img class='inline-img' src='img/Ev W.png'> du défenseur en un résultat <img class='inline-img' src='img/Fo W.png'>.", effect_ENG = "While you perform an attack, if you are evading, you may modify 1 of the <img class='inline-img' src='img/Ev W.png'> results of the defender into an <img class='inline-img' src='img/Fo W.png'> result." }
D.upgrades[222] = { name_FRA = "Insaisissable", name_ENG = "Elusive", id = 221, slot = "Talent-piloting", effect_FRA = "<img class='inline-img' src='img/chargeplus.png'>Lorsque vous défendez contre une attaque à portée 3 ou contre une attaque de <img class='inline-img' src='img/Tarc.png'>, vous pouvez dépenser 1<img class='inline-img' src='img/charge.png'> pour améliorer un dé de défense.", effect_ENG = "<img class='inline-img' src='img/chargeplus.png'> While you defend against an attack at range 3 or against a <img class='inline-img' src='img/Tarc.png'> attack, you may spend 1 <img class='inline-img' src='img/charge.png'> to upgrade a defense die.", add_Data = {0}, force = 0, charge = {2, "yellow", "+"} }
D.upgrades[223] = { name_FRA = "Chef d'Escouade", name_ENG = "Squad Leader", id = 222, slot = "Talent-leadership", add_Data = {0}, force = 0, charge = {1, "addCoRAction", ""}, effect_FRA = "Tant que vous coordonnez, le vaisseau que vous avez choisi peut effectuer une action seulement si celle-ci est également dans votre barre d’action.<br>Ajoute l'action rouge <img class='inline-img' src='img/Co W.png'>", effect_ENG = "While you coordinate, the ship you chose may perform an action only if it is also on your action bar.<br>Add the red <img class='inline-img' src='img/Co W.png'> action." }
D.upgrades[224] = { name_FRA = "Casse-Cou", name_ENG = "Daredevil", id = 223, slot = "Talent-piloting", add_Data = {0}, force = 0, charge = {0}, effect_FRA = "Lorsque vous accélérez, vous pouvez utiliser des gabarits <img class='inline-img' src='img/manTr2.png'> de même vitesse et de même direction à la place", effect_ENG = "While you boost, you may use <img class='inline-img' src='img/manTr2.png'> templates of the same speed and same direction instead." }
D.upgrades[225] = { name_FRA = "Manoeuvre Improbable", name_ENG = "Outmaneuver", id = 224, slot = "Talent-elite", add_Data = {0}, force = 0, charge = {0}, effect_FRA = "Tant que vous effectuez une attaque <img class='inline-img' src='img/attackF.png'>, si vous n’êtes pas dans l’arc de tir du défenseur, il lance 1 dé de défense en moins.", effect_ENG = "While you perform a <img class='inline-img' src='img/attackF.png'> attack, if you are not in the defender's firing arc, it rolls 1 fewer defense die." }
D.upgrades[226] = { name_FRA = "As de l'Espace", name_ENG = "Expert Handling", id = 225, slot = "Talent-piloting", add_Data = {0}, force = 0, charge = {1, "addBrWAction", ""}, effect_FRA = "Ajoute l'action <img class='inline-img' src='img/Br W.png'>. Si vous la possédiez déjà, et vous pouvez la lier avec une action <img class='inline-img' src='img/Fo W.png'> rouge. Si vous effectuez une action <img class='inline-img' src='img/Br W.png'>, si vous ne la possédiez pas, recevez 1 jeton contrainte, et si vous êtes un socle large, exposez en plus une carte de dégat.", effect_ENG = "Add the <img class='inline-img' src='img/Br W.png'> action. If you already had it, you can link it with a red <img class='inline-img' src='img/Fo W.png'> action.<br>When you perform a <img class='inline-img' src='img/Br W.png'> action, if you didn't have it initially, receive a strain token, and if you are a large base ship, in addition to that, expose a damage card." }
D.upgrades[227] = { name_FRA = "Expertise", name_ENG = "Expetise", id = 226, slot = "Talent-elite", effect_FRA = " Lorsque vous lancez des dés, si vous n'êtes pas stressé, vous pouvez dépenser 1 <img class='inline-img' src='img/charge.png'>. Si vous le faites, améliorez ou dégradez 1 dé. Durant la phase de fin, vous pouvez recevoir un jeton épuisement pour récupérer 1 <img class='inline-img' src='img/charge.png'>.", effect_ENG = " When you roll any dice, if you are not stressed, you may spend 1 <img class='inline-img' src='img/charge.png'>. If you do, upgrade or downgrade a die. During the end phase, you may receive 1 deplete token to recover 1 <img class='inline-img' src='img/charge.png'>.", add_Data = {0}, force = 0, charge = {1, "yellow", "0"} }
D.upgrades[228] = { name_FRA = "*Discret", name_ENG = "*Secretive", id = 227, slot = "Talent-special", add_Data = {0}, force = 0, charge = {1, "yellow", "0"}, effect_FRA = "Placez 1 jeton avec une valeur de 1 à 4 face cachée sur votre pilote, pour indiquer la capacité secrète disponible.<br>1 : Lorsque vous vous engagez, dépensez 1 <img class='inline-img' src='img/charge.png'> pour effectuer une attaque à portée 0.<br>2 : Lorsque vous défendez contre une attaque <img class='inline-img' src='img/missile.png'> ou <img class='inline-img' src='img/Torpedo.png'>, vous pouvez dépenser 1 <img class='inline-img' src='img/charge.png'> pour brouiller l'attaquant.<br>3 : Pendant la phase Système, dépensez 1 <img class='inline-img' src='img/charge.png'> pour effectuer une action <img class='inline-img' src='img/Br W.png'> ou <img class='inline-img' src='img/Bo W.png'> de votre barre d'action.<br>4 : Lorsque vous révélez une manoeuvre rouge, dépensez 1 <img class='inline-img' src='img/charge.png'> pour réduire la difficulté de la manoeuvre.", effect_ENG = "Place 1 token with a value from 1 to 4 face down on your pilot, to remember the secret ability available.<br>1 : When you engage, spend 1 <img class='inline-img' src='img/charge.png'> to perform an attack at range 0.<br>2 : When you defend against a <img class='inline-img' src='img/missile.png'> or <img class='inline-img' src='img/Torpedo.png'> attack, you may spend 1 <img class='inline-img' src='img/charge.png'> to jam the attacker.<br>3 : During System Phase, spend 1 <img class='inline-img' src='img/charge.png'> to perform a <img class='inline-img' src='img/Br W.png'> or <img class='inline-img' src='img/Bo W.png'> action on your action bar.<br>4 : When you reveal a red maneuver, spend 1 <img class='inline-img' src='img/charge.png'> to reduce the maneuver difficulty." }
D.upgrades[229] = { name_FRA = "*Egorgeur", name_ENG = "*Cutthroat", id = 228, slot = "Talent-special", add_Data = {0}, force = 0, charge = {0}, effect_FRA = "Après qu'un vaisseau allié à portée 0-3 est détruit, si ce vaisseau est limité or possède l'amélioration <i>Egorgeur</i>, vous pouvez retirer 1 de vos marqueurs orange ou rouge, ou récupérer 1 <img class='inline-img' src='img/charge.png'> non récursive sur l'une de vos améliorations, sur votre pilote, ou sur votre leader.", effect_ENG = "After another friendly ship at range 0-3 is destroyed, if that ship is limited or has the Cutthroat upgrade, you may remove 1 of your orange or red tokens, or recover 1 non-recurring  on your ship card or one of your equipped upgrade cards, on your pilot card, or on your leader card." }
D.upgrades[230] = { name_FRA = "*Confiance Fragile", name_ENG = "*Fragile Trust", id = 229, slot = "Talent-special", add_Data = {0}, force = 0, charge = {1, "yellow", "0"}, effect_FRA = "CONFIANCE FRAGILE : Tant que la <img class='inline-img' src='img/charge.png'> sur cette amélioration est active, lorsque vous attaquez ou défendez, vous pouvez changer un résultat <img class='inline-img' src='img/Fo W.png'> en un résultat <img class='inline-img' src='img/hit.png'> ou <img class='inline-img' src='img/Ev W.png'>. <br> MEFIANCE : Si votre charge est inactive, durant la phase système, recevez 1 jeton contrainte. Lorsque vous effectuez une action <img class='inline-img' src='img/Fo W.png'>, recevez 1 jeton de contrainte. <br>ACTION : récupérez 1 <img class='inline-img' src='img/charge.png'>", effect_ENG = "FRAGILE TRUST : While the <img class='inline-img' src='img/charge.png'> on this upgrade is active, when you attack or defend, you may change an <img class='inline-img' src='img/Fo W.png'> result into a <img class='inline-img' src='img/hit.png'> or <img class='inline-img' src='img/Ev W.png'> result.<br>DISTRUST : If your charge is inactive, during System phase, gain 1 strain token. When you perform a <img class='inline-img' src='img/Fo W.png'> action gain 1 strain token. <br>ACTION : recover 1 <img class='inline-img' src='img/charge.png'>." }
D.upgrades[231] = { name_FRA = "*Discipliné", name_ENG = "*Disciplined", id = 230, slot = "Talent-special", add_Data = {0}, force = 0, charge = {0}, effect_FRA = "Après qu'un vaisseau allié à portée 0-3 est détruit, si ce vaisseau est limité or possède le talent <i>Discipliné</i>, vous pouvez effectuer une action <img class='inline-img' src='img/Lo W.png'> ou <img class='inline-img' src='img/Br W.png'>.", effect_ENG = "After another friendly ship at range 0-3 is destroyed, if that ship is limited or has the Disciplined upgrade, you may perform a <img class='inline-img' src='img/Lo W.png'> or <img class='inline-img' src='img/Br W.png'> action." }
D.upgrades[232] = { name_FRA = "*Extrémiste", name_ENG = "*Extremist", id = 231, slot = "Talent-special", effect_FRA = "Avant de lancer des dés d'attaque, vous pouvez subir un <img class='inline-img' src='img/hit.png'> pour donner un marqueur de contrainte à votre cible.", effect_ENG = "Before you roll attack dice, you may suffer a <img class='inline-img' src='img/hit.png'> to strain your target.", add_Data = {0}, force = 0, charge = {0} }
D.upgrades[233] = { name_FRA = "Perception Renforcée", name_ENG = "Heightened Perception", id = 232, slot = "Force-Light", add_Data = {0}, force = 0, charge = {0}, effect_FRA = "En phase Système, vous pouvez dépensez 1 <img class='inline-img' src='img/fo.png'>. Si vous le faites :<br>- Activez-vous à Initiative +1 ou -1<br>- Engagez-vous à Initiative 7.", effect_ENG = "During System Phase, you may spend 1 <img class='inline-img' src='img/fo.png'>. If you do:<br>- Activate with an Initiative +1 or -1<br>- Engage at Initiative 7." }
D.upgrades[234] = { name_FRA = "Tir Précis", name_ENG = "Sharp Shot", id = 233, slot = "Force-Base", add_Data = {0}, force = 0, charge = {0}, effect_FRA = "Lorsque vous attaquez, vous pouvez dépenser 1 <img class='inline-img' src='img/fo.png'> pour améliorer 1 dé d'attaque.", effect_ENG = "While you attack, you may spend 1 <img class='inline-img' src='img/fo.png'> to upgrade 1 of your attack die." }
D.upgrades[235] = { name_FRA = "Clairvoyance", name_ENG = "Foresight", id = 234, slot = "Force-Dark", add_Data = {0}, force = 0, charge = {0}, effect_FRA = "Après qu'un vaisseau ennemi a effectué une manoeuvre, vous pouvez dépenser 1 <img class='inline-img' src='img/fo.png'> pour effectuer contre lui cette attaque (attaque bonus).<br>Attaque 2 <img class='inline-img' src='img/attackF.png'> range 1-2 : Vous pouvez améliorer 1 dé d'attaque si la cible est dans votre <img class='inline-img' src='img/bulls.png'>", effect_ENG = "After an enemy ship executes a maneuver, you may spend 1 <img class='inline-img' src='img/fo.png'> to perform this attack against it as a bonus attack.<br>Attack 2 <img class='inline-img' src='img/attackF.png'> Range 1-2: You may upgrade 1 of your attack die if target ship is in your <img class='inline-img' src='img/bulls.png'>." }
D.upgrades[236] = { name_FRA = "Tir Prophétique", name_ENG = "Predictive Shot", id = 235, slot = "Force-Dark", add_Data = {0}, force = 0, charge = {0}, effect_FRA = "Lorsque vous attaquez, vous pouvez dépenser jusqu'à 3<img class='inline-img' src='img/fo.png'>. Dans ce cas, améliorez autant de vos résultats.", effect_ENG = "While you perform an attack, you may spend up to 3<img class='inline-img' src='img/fo.png'>. If you do, upgrade that many of your attack results." }
D.upgrades[237] = { name_FRA = "Cellules Énergétiques Bidouillées", name_ENG = "Rigged Energy Cells", id = 236, slot = "Special", add_Data = {"changeChassis", "C1", "<em><strong>Copilote 2: </strong></em>MISE EN PLACE : Vous <mark>devez</mark> être arrimé à un vaisseau YT-1300 Light Freighter. "}, force = 0, charge = {0}, effect_FRA = "À la fin de la phase d’activation, si vous n'êtes pas arrimé perdez 1 <img class='inline-img' src='img/charge.png'>. Vous êtes détruit si vous avez 0 <img class='inline-img' src='img/charge.png'>. Avant de retirer votre figurine, chaque vaisseau à porté 0–1 subit 1 dégât <img class='inline-img' src='img/crit.png'> ", effect_ENG = "At the end of Activation phase, if you are not docked, lose 1 <img class='inline-img' src='img/charge.png'>. You are destroyed if you have 0 <img class='inline-img' src='img/charge.png'>. Before removing your ship, each ship at range 0-1 suffers 1 <img class='inline-img' src='img/crit.png'> damage." }
D.upgrades[238] = { name_FRA = "Type : Droid", name_ENG = "Type : Droid", id = 237, slot = "Droid", add_Data = {"droid"}, force = 0, charge = {0}, effect_FRA = "Toute action <img class='inline-img' src='img/Fo W.png'> devient <img class='inline-img' src='img/Cc W.png'>", effect_ENG = "<img class='inline-img' src='img/Fo W.png'> actions become <img class='inline-img' src='img/Cc W.png'>" }
D.upgrades[239] = { name_FRA = "Marauder", name_ENG = "Marauder", id = 238, slot = "Title", add_Data = {0}, force = 0, charge = {0}, effect_FRA = "", effect_ENG = "" }
D.upgrades[240] = { name_FRA = "Hyperspace Ring", name_ENG = "Hyperspace Ring", id = 239, slot = "Hyperspace Ring", add_Data = {0}, force = 0, charge = {1, "yellow", "0"}, effect_FRA = "<img class='inline-img' src='img/charge.png'> Mise en Place : Vous devez arrimer un Syliure-class Hyperspace Ring avec vous.<br>Tant que votre charge est active, augmentez la difficulté de vos virages sur l'aile. Lorsque vous devriez prendre 1 dégat, vous pouvez dépenser 1 <img class='inline-img' src='img/charge.png'> pour l'annuler, et placer une carte de dégat sur l'anneau qui est arrimé. Dans ce cas, larguez et retirez du jeu le Hyperspace Ring arrimé avec vous.", effect_ENG = "<img class='inline-img' src='img/charge.png'> Setup : You MUST dock a Syliure-class Hyperspace Ring with you.<br>While your charge is active, increase the difficulty of your turn maneuvers. When you would take a damage, you may spend 1 <img class='inline-img' src='img/charge.png'> to cancel it, and place a damage card on the ring docked with you. Then, undock and remove your docked ring from the game." }
D.upgrades[241] = { name_FRA = "*Stoïque", name_ENG = "*Stoic", id = 240, slot = "Talent-special", add_Data = {0}, force = 0, charge = {1, "yellow", "0"}, effect_FRA = "Lorsque vous recevez 1 jeton orange ou rouge, vous pouvez dépenser 1 <img class='inline-img' src='img/charge.png'> pour recevoir un jeton concentration.", effect_ENG = "When you receive 1 red or orange token, you can spend 1 <img class='inline-img' src='img/charge.png'> to receive 1 Focus token." }
D.upgrades[242] = { name_FRA = "*Dévoué", name_ENG = "*Dedicated", id = 241, slot = "Talent-special", add_Data = {0}, force = 0, charge = {0}, effect_FRA = "Tant qu’un autre vaisseau allié situé dans votre <img class='inline-img' src='img/Larc.png'> ou <img class='inline-img' src='img/Rarc.png'> à portée 0-2 défend, s’il est limité ou possède l’amélioration Dévoué et que vous n’êtes pas contraint, vous pouvez gagner 1 marqueur de contrainte. Dans ce cas, le défenseur relance 1 de ses résultats vierges.", effect_ENG = "While another friendly ship in your <img class='inline-img' src='img/Larc.png'> or <img class='inline-img' src='img/Rarc.png'> at range 0-2 defends, if it is limited or has the Dedicated upgrade and you are not strained, you may gain 1 strain token. If you do, the defender rerolls 1 of their blank results." }
D.upgrades[243] = { name_FRA = "Capitaine Clone Rex", name_ENG = "Clone Captain Rex", id = 242, slot = "Crew", add_Data = {0}, force = 0, charge = {0}, effect_FRA = "Début de la Mise en Place : Votre adversaire assigne la condition 'Mission Sauvetage d'Otage' à l'un de ses vaisseaux.", effect_ENG = "Beginning of Setup : Your opponent assign the 'Hostage Rescue Mission' condition to one of his ships." }
D.upgrades[244] = { name_FRA = "Omega", name_ENG = "Omega", id = 243, slot = "Crew", add_Data = {0}, force = 0, charge = {0}, effect_FRA = "Fin de Partie : Si vous n'êtes pas détruit, gagnez 3 PO.<br>ACTION : Choisissez un vaisseau ennemi à portée 1-2 dans votre arc de tir. Il gagne 2 jetons épuisement.", effect_ENG = "End Game : If you are not destroyed, gain 3 PO.<br>ACTION : Choose an enemy ship at range 1-2 in your firing arc. It gains 2 deplete tokens." }
D.upgrades[245] = { name_FRA = "Artilleur de la 7ème Flotte", name_ENG = "7th Fleet Gunner", id = 244, slot = "Gunner", add_Data = {0}, force = 0, charge = {0}, effect_FRA = "Tant qu’un autre vaisseau allié effectue une attaque principale, si le défenseur est dans votre arc de tir, vous pouvez dépenser 1 <img class='inline-img' src='img/charge.png'>. Dans ce cas, l’attaquant lance 1 dé supplémentaire, pour un maximum de 4. Pendant la phase de système, vous pouvez gagner 1 marqueur de désarmement pour récupérer 1 <img class='inline-img' src='img/charge.png'>.", effect_ENG = "While another allied ship performs a primary attack, if the defender is in your firing arc, you may spend 1 <img class='inline-img' src='img/charge.png'>. If you do, the attacker rolls 1 additional die, up to a maximum of 4. During the system phase, you may gain 1 disarm token to recover 1 <img class='inline-img' src='img/charge.png'>." }
D.upgrades[246] = { name_FRA = "Commandant Clone Cody", name_ENG = "Clone Commander Cody", id = 245, slot = "Gunner", add_Data = {0}, force = 0, charge = {0}, effect_FRA = "Après avoir effectué une attaque qui a raté, si au moins 1 résultat <img class='inline-img' src='img/hit.png'>/<img class='inline-img' src='img/crit.png'> a été neutralisé, le défenseur gagne 1 marqueur de contrainte.", effect_ENG = "After you perform an attack that missed, if at least 1 <img class='inline-img' src='img/hit.png'>/<img class='inline-img' src='img/crit.png'> result was canceled, the defender gains 1 strain token." }
D.upgrades[247] = { name_FRA = "'Fives''", name_ENG = "'Fives'", id = 246, slot = "Crew", add_Data = {0}, force = 0, charge = {0}, effect_FRA = "Après que vous avez effectué une attaque ratée, si l’initiative du défenseur est supérieure ou égale à votre initiative, placez 1 marqueur d’évasion ou de concentration sur cette amélioration.<br>Avant de vous engager, vous pouvez retirer 1 marqueur de cette amélioration pour gagner 1 marqueur correspondant.", effect_ENG = "After you perform a missed attack, if the defender's initiative is greater than or equal to your initiative, place 1 evade or focus token on this upgrade.<br>Before you engage, you may remove 1 token from this upgrade to gain 1 matching token." }
D.upgrades[248] = { name_FRA = "R2-C4", name_ENG = "R2-C4", id = 247, slot = "Astromech", add_Data = {0}, force = 0, charge = {0}, effect_FRA = "Tant que vous effectuez une attaque, vous pouvez dépenser 1 marqueur d’évasion pour changer 1 résultat <img class='inline-img' src='img/Fo W.png'> en un résultat <img class='inline-img' src='img/hit.png'>.", effect_ENG = "While you perform an attack, you may spend 1 evade token to change 1 <img class='inline-img' src='img/Fo W.png'> result to a <img class='inline-img' src='img/hit.png'> result." }
D.upgrades[249] = { name_FRA = "Message Prioritaire", name_ENG = "Priority Message", id = 248, slot = "Modification", add_Data = {0}, force = 0, charge = {0}, effect_FRA = "ACTION : Ajoutez 1 <img class='inline-img' src='img/charge.png'> à 'Message Prioritaire'. Si vous recevez votre 5ème <img class='inline-img' src='img/charge.png'>, gagnez 4 PO, et vous pouvez retirez votre vaisseau de la partie, sans que l'adversaire ne remporte de PO.", effect_ENG = "ACTION: Add 1 <img class='inline-img' src='img/charge.png'> to 'Priority Message'. If you receive your 5th <img class='inline-img' src='img/charge.png'>, gain 4 PO, and you may remove your ship from the game without the opponent gaining PO." }
D.upgrades[250] = { name_FRA = "Console Synchronisée", name_ENG = "Synchronised Console", id = 249, slot = "Calculator", add_Data = {0}, force = 0, charge = {0}, effect_FRA = "Après avoir effectué une attaque, vous pouvez choisir un vaisseau allié à portée 1 ou un vaisseau allié qui possède l’amélioration Console Synchronisée à portée 1-3 et dépenser un verrouillage que vous avez sur le défenseur. Dans ce cas, le vaisseau allié que vous avez choisi peut verrouiller le défenseur.", effect_ENG = "After you perform an attack, you may choose a friendly ship at range 1 or a friendly ship that has the Synchronised Console upgrade at range 1-3 and spend a lock you have on the defender. If you do, the friendly ship you chose may lock the defender." }
D.upgrades[251] = { name_FRA = "Chancellier Palpatine", name_ENG = "Chancellor Palpatine", id = 250, slot = "Crew", add_Data = {0}, force = 1, charge = {1, "addCoFAction", ""}, effect_FRA = "<img class='inline-img' src='img/forcestat.png'> Après avoir défendu, si l’attaquant est à portée 0-2, vous pouvez dépenser 1 <img class='inline-img' src='img/charge.png'>. Dans ce cas, l’attaquant gagne 1 marqueur de stress.<br> Ajoute l'action <img class='inline-img' src='img/Co W.png'> violette.", effect_ENG = "<img class='inline-img' src='img/forcestat.png'> After you defend, if the attacker is at range 0-2, you may spend 1 <img class='inline-img' src='img/charge.png'>. If you do, the attacker gains 1 stress token.<br> Add the purple <img class='inline-img' src='img/Co W.png'> action." }
D.upgrades[252] = { name_FRA = "Kit Fisto", name_ENG = "Kit Fisto", id = 251, slot = "Crew", add_Data = {0}, force = 1, charge = {0}, effect_FRA = "<img class='inline-img' src='img/forcestat.png'> Au début de la phase d’engagement, vous pouvez choisir 1 vaisseau allié à portée 0–1 et dépenser 1<img class='inline-img' src='img/fo.png'> . Dans ce cas, il peut effectuer une action <img class='inline-img' src='img/Ev W.png'> rouge.", effect_ENG = "<img class='inline-img' src='img/forcestat.png'> At the start of the engagement phase, you may choose 1 friendly ship at range 0-1 and spend 1 <img class='inline-img' src='img/fo.png'>. If you do, it may perform a red <img class='inline-img' src='img/Ev W.png'> action." }
D.upgrades[253] = { name_FRA = "Wolfpack", name_ENG = "Wolfpack", id = 252, slot = "Gunner", add_Data = {0}, force = 0, charge = {0}, effect_FRA = "Après qu’un vaisseau allié à portée 0–3 a défendu, si l’attaquant est dans votre arc de tir, le défenseur peut gagner 1 marqueur de contrainte pour verrouiller l’attaquant.", effect_ENG = "After a friendly ship at range 0-3 defends, if the attacker is in your firing arc, the defender may gain 1 stress token to lock the attacker." }
D.upgrades[254] = { name_FRA = "Plo Koon", name_ENG = "Plo Koon", id = 253, slot = "Crew", add_Data = {0}, force = 1, charge = {1, "addReFAction", ""}, effect_FRA = "<img class='inline-img' src='img/forcestat.png'>Au début de la phase de dénouement, si vous êtes renforcé, vous pouvez choisir 1 vaisseau allié à portée 0 ou qui est situé dans votre <img class='inline-img' src='img/Larc.png'> ou <img class='inline-img' src='img/Rarc.png'> à portée 1. Ce vaisseau retire 1 marqueur d’épuisement ou de contrainte ou répare 1 carte de dégât face visible. Ajoute l'action violette <img class='inline-img' src='img/Re W.png'>", effect_ENG = "<img class='inline-img' src='img/forcestat.png'>At the start of the end phase, if you are reinforced, you may choose 1 friendly ship at range 0 or in your <img class='inline-img' src='img/Larc.png'> or <img class='inline-img' src='img/Rarc.png'> at range 1. That ship removes 1 deplete or strain token or repairs 1 faceup damage card. Add the purple <img class='inline-img' src='img/Re W.png'> action." }
D.upgrades[255] = { name_FRA = "Yoda", name_ENG = "Yoda", id = 254, slot = "Crew", add_Data = {0}, force = 2, charge = {0}, effect_FRA = "<img class='inline-img' src='img/forcestat.png'><img class='inline-img' src='img/forcestat.png'>Après qu’un autre vaisseau allié à portée 0–2 a entièrement exécuté une manœuvre violette ou effectué une action violette, vous pouvez dépenser 1 <img class='inline-img' src='img/fo.png'>. Dans ce cas, cet autre vaisseau allié récupère 1 <img class='inline-img' src='img/fo.png'>.", effect_ENG = "<img class='inline-img' src='img/forcestat.png'><img class='inline-img' src='img/forcestat.png'>After another friendly ship at range 0-2 has fully executed a purple maneuver or performed a purple action, you may spend 1 <img class='inline-img' src='img/fo.png'>. If you do, that other friendly ship recovers 1 <img class='inline-img' src='img/fo.png'>." }
D.upgrades[256] = { name_FRA = "Ahsoka Tano", name_ENG = "Ahsoka Tano", id = 255, slot = "Gunner", add_Data = {0}, force = 1, charge = {0}, effect_FRA = "Après avoir exécuté une manœuvre, vous pouvez dépenser 1 <img class='inline-img' src='img/fo.png'> et choisir un vaisseau allié dans votre arc de tir à portée 1-3. Dans ce cas, il peut effectuer une action <img class='inline-img' src='img/Fo W.png'> rouge, même s’il est stressé.", effect_ENG = "Après avoir exécuté une manœuvre, vous pouvez dépenser 1 <img class='inline-img' src='img/fo.png'> et choisir un vaisseau allié dans votre arc de tir à portée 1-3. Dans ce cas, il peut effectuer une action <img class='inline-img' src='img/Fo W.png'> rouge, même s’il est stressé." }
D.upgrades[257] = { name_FRA = "Q7 Astromech", name_ENG = "Q7 Astromech", id = 256, slot = "Astromech", add_Data = {0}, force = 0, charge = {0}, effect_FRA = "Tant que vous effectuez un tonneau ou accélérez, vous pouvez vous déplacer à travers les obstacles et les chevaucher.", effect_ENG = "While you perform a barrel roll or boost, you may move through and overlap obstacles." }
D.upgrades[258] = { name_FRA = "R4-P44", name_ENG = "R4-P44", id = 257, slot = "Astromech", add_Data = {0}, force = 0, charge = {0}, effect_FRA = "Après avoir entièrement exécuté une manœuvre rouge, s’il y a un vaisseau ennemi dans votre <img class='inline-img' src='img/bulls.png'>, gagnez 1 marqueur de calcul.", effect_ENG = "After you fully execute a red maneuver, if there is an enemy ship in your <img class='inline-img' src='img/bulls.png'>, gain 1 calculate token." }
D.upgrades[259] = { name_FRA = "Astromech R4-P", name_ENG = "R4-P Astromech", id = 258, slot = "Astromech", add_Data = {0}, force = 0, charge = {2, "yellow", "0"}, effect_FRA = "Avant d’exécuter une manœuvre de base, vous pouvez dépenser 1 <img class='inline-img' src='img/charge.png'>. Dans ce cas, tant que vous exécutez cette manœuvre, diminuez sa difficulté.", effect_ENG = "Before you execute a basic maneuver, you may spend 1 <img class='inline-img' src='img/charge.png'>. If you do, while you execute that maneuver, reduce its difficulty." }
D.upgrades[260] = { name_FRA = "R7-A7", name_ENG = "R7-A7", id = 259, slot = "Astromech", add_Data = {0}, force = 0, charge = {3, "yellow", "0"}, effect_FRA = "Tant que vous effectuez une attaque, vous pouvez dépenser 1 <img class='inline-img' src='img/charge.png'> pour changer 1 résultat <img class='inline-img' src='img/hit.png'> en un résultat <img class='inline-img' src='img/crit.png'>.", effect_ENG = "While you perform an attack, you may spend 1 <img class='inline-img' src='img/charge.png'> to change 1 <img class='inline-img' src='img/hit.png'> result to a <img class='inline-img' src='img/crit.png'> result." }
D.upgrades[261] = { name_FRA = "R4-P17", name_ENG = "R4-P17", id = 260, slot = "Astromech", add_Data = {0}, force = 0, charge = {2, "yellow", "0"}, effect_FRA = "Après avoir entièrement exécuté une manœuvre rouge, vous pouvez dépenser 1 <img class='inline-img' src='img/charge.png'> pour effectuer une action, même si vous êtes stressé.", effect_ENG = "After you fully execute a red maneuver, you may spend 1 <img class='inline-img' src='img/charge.png'> to perform an action, even if you are stressed." }
D.upgrades[262] = { name_FRA = "Compagnie Fantôme", name_ENG = "Ghost Company", id = 261, slot = "Gunner", add_Data = {0}, force = 0, charge = {1, "addRaWAction", "linkFoRAction"}, effect_FRA = "Après avoir effectué une attaque principale, si vous êtes concentré, vous pouvez effectuer une attaque <img class='inline-img' src='img/Tarc.png'>, en tant qu’attaque bonus, contre un vaisseau que vous n’avez pas attaqué à ce round. Ajoute <img class='inline-img' src='img/Ra W.png'> -> <img class='inline-img' src='img/Fo W.png'> rouge", effect_ENG = "After you perform a primary attack, if you are focused, you may perform a <img class='inline-img' src='img/Tarc.png'> attack as a bonus attack against a ship you have not attacked this round. Adds <img class='inline-img' src='img/Ra W.png'> -> red <img class='inline-img' src='img/Fo W.png'>" }
D.upgrades[263] = { name_FRA = "Aayla Secura", name_ENG = "Aayla Secura", id = 262, slot = "Crew", add_Data = {0}, force = 1, charge = {1, "addFoWAction", "linkCoFAction"}, effect_FRA = "<img class='inline-img' src='img/forcestat.png'>Tant qu’un vaisseau ennemi dans votre <img class='inline-img' src='img/bulls.png'> effectue une attaque, si le défenseur est allié et à portée 0–2, ce dernier peut changer 1 résultat vierge en un résultat <img class='inline-img' src='img/Fo W.png'>. Ajoute <img class='inline-img' src='img/Fo W.png'> -> <img class='inline-img' src='img/Co W.png'> violet", effect_ENG = "<img class='inline-img' src='img/forcestat.png'>While an enemy ship in your <img class='inline-img' src='img/bulls.png'> performs an attack, if the defender is an ally and at range 0-2, the defender may change 1 blank result to a <img class='inline-img' src='img/Fo W.png'> result. Adds <img class='inline-img' src='img/Fo W.png'> -> purple <img class='inline-img' src='img/Co W.png'>" }
D.upgrades[264] = { name_FRA = "Qi'Ra", name_ENG = "Qi'Ra", id = 263, slot = "Crew", add_Data = {0}, force = 0, charge = {0}, effect_FRA = "Tant que vous vous déplacez et effectuez des attaques, vous ignorez les obstacles que vous verrouillez.", effect_ENG = "While you move and perform attacks, you ignore obstacles you have locked." }
D.upgrades[265] = { name_FRA = "Tobias Becket", name_ENG = "Tobias Becket", id = 264, slot = "Crew", add_Data = {0}, force = 0, charge = {0}, effect_FRA = "Mise en Place : après avoir placé les forces, vous pouvez choisir 1 obstacle dans la zone de jeu. Dans ce cas, placez-le n’importe où dans la zone de jeu au-delà de la portée 2 de tout bord ou vaisseau et au-delà de la portée 1 de tout autre obstacle.", effect_ENG = "Setup: After placing forces, you may choose 1 obstacle in the play area. If you do, place it anywhere in the play area beyond range 2 of any edge or ship and beyond range 1 of any other obstacle." }
D.upgrades[266] = { name_FRA = "Latts Razzi", name_ENG = "Latts Razzi", id = 265, slot = "Crew", add_Data = {0}, force = 0, charge = {0}, effect_FRA = "Lorsque vous défendez, si l'attaquant est stressé, vous pouvez retirer 1 jeton de stress de l'attaquant pour modifier 1 résultat vierge/oeil en résultat <img class='inline-img' src='img/Ev W.png'>.", effect_ENG = "While you defend, if the attacker is stressed, you may remove 1 stress from the attacker to change 1 of your blank/eye results to an <img class='inline-img' src='img/Ev W.png'> result." }
D.upgrades[267] = { name_FRA = "Dispositif de Retour", name_ENG = "Feedback Array", id = 266, slot = "Illicit", add_Data = {0}, force = 0, charge = {0}, effect_FRA = "Avant de vous engagez, vous pouvez recevoir 1 jeton ion et 1 jeton désarmement. Chaque autre vaisseau à portée 0 subit 1 dégat <img class='inline-img' src='img/hit.png'>.", effect_ENG = "Before you engage, you may gain 1 ion token and 1 disarm token. Each other ship at range 0 suffers 1 <img class='inline-img' src='img/hit.png'> damage." }
D.upgrades[268] = { name_FRA = "Amortisseurs Inertiels", name_ENG = "Inertial Dampeners", id = 267, slot = "Illicit", add_Data = {0}, force = 0, charge = {0}, effect_FRA = "Avant d’exécuter une manœuvre, vous pouvez dépenser 1 bouclier. Dans ce cas, exécutez une manœuvre 0<img class='inline-img' src='img/manOp2.png'> blanche à la place de celle que vous avez révélée, puis gagnez 1 marqueur de stress.", effect_ENG = "Before you would execute a maneuver, you may spend 1 shield. If you do, execute a white 0<img class='inline-img' src='img/manOp2.png'> instead of the maneuver you revealed, then gain 1 stress token." }
D.upgrades[269] = { name_FRA = "Banshee", name_ENG = "Banshee", id = 268, slot = "Title", add_Data = {0}, force = 0, charge = {0}, effect_FRA = "Ajoute 1 emplacement <img class='inline-img' src='img/Sensor.png'>, retire 1 emplacement <img class='inline-img' src='img/Modification.png'>.", effect_ENG = "Add 1 <img class='inline-img' src='img/Sensor.png'> slot, remove 1 <img class='inline-img' src='img/Modification.png'> slot." }
D.upgrades[270] = { name_FRA = "Virago", name_ENG = "Virago", id = 269, slot = "Title", add_Data = {0}, force = 0, charge = {0}, effect_FRA = "ajoute 1 emplacement <img class='inline-img' src='img/Sensor.png'> et <img class='inline-img' src='img/Illicit.png'>.", effect_ENG = "add 1 <img class='inline-img' src='img/Sensor.png'> slot and 1 <img class='inline-img' src='img/Illicit.png'> slot." }
D.upgrades[271] = { name_FRA = "Guri", name_ENG = "Guri", id = 270, slot = "Crew", add_Data = {0}, force = 0, charge = {0}, effect_FRA = "A la fin de la phase d'activation, s'il y a un vaisseau ennemi à portée 0-1, recevez 1 jeton calcul. S'il n'y a pas de vaisseau ennemi à portée 0-2, recevez 1 jeton brouillage.", effect_ENG = "At the end of activation phase, if there's an enemy ship at range 0-1, gain a calculate token. If there isn't any enemy ship at range 0-2, gain a jam token." }
D.upgrades[272] = { name_FRA = "Module NS-9 Starpath", name_ENG = "NS-9 Starpath Module", id = 271, slot = "Illicit", add_Data = {0}, force = 0, charge = {1, "yellow", "0"}, effect_FRA = "Si votre charge est active, vous ne pouvez pas être ciblé par une attaque. Si vous attaquez, ou si vous êtes le dernier vaisseau en jeu de votre escadron, dépensez 1<img class='inline-img' src='img/charge.png'>.", effect_ENG = "If your charge is active, you cannot be targeted by attacks. If you perform an attack, or if you are the last ship of your squadron in battle, lose 1 <img class='inline-img' src='img/charge.png'>." }
D.upgrades[273] = { name_FRA = "Kestu Onyo", name_ENG = "Ketsu Onyo", id = 272, slot = "Crew", add_Data = {0}, force = 0, charge = {0}, effect_FRA = "Au début de la phase de Fin, vous pouvez choisir 1 vaisseau ennemi à portée 0-2 dans votre arc de tir. Dans ce cas, ce vaisseau ne retire pas ses jetons tractage.", effect_ENG = "At the start of the End Phase, you may choose 1 enemy ship at range 0-2 in your firing arc. If you do, that ship does not remove its tractor tokens." }
D.upgrades[274] = { name_FRA = "Modulateurs Surrégulés", name_ENG = "Overtuned Modulators", id = 273, slot = "Illicit", add_Data = {0}, force = 0, charge = {0}, effect_FRA = "Pendant la phase Système, si vous n'êtes pas stressé, vous pouvez dépenser 1 <img class='inline-img' src='img/charge.png'> pour recevoir 3 jetons calcul. Pendant la phase de fin, si votre <img class='inline-img' src='img/charge.png'> est inactive, pour chaque jeton vert que vous retirez, recevez 1 jeton contrainte.", effect_ENG = "During the System Phase, if you are not stressed, you may spend 1 <img class='inline-img' src='img/charge.png'> to gain 3 calculate tokens. During the End Phase, if your <img class='inline-img' src='img/charge.png'> is inactive, for each green token you remove, gain 1 strain token." }
D.upgrades[275] = { name_FRA = "Faisceau Laser Tranchant", name_ENG = "Cutting Laser Beam", id = 274, slot = "Illicit", add_Data = {0}, force = 0, charge = {1, "yellow", "0"}, effect_FRA = "Après avoir partiellement exécuté une manoeuvre, vous pouvez dépenser 1 <img class='inline-img' src='img/charge.png'>. Dans ce cas, chaque autre vaisseau à portée 0 recoivent 1 carte de dégat face visible.", effect_ENG = "After you partially execute a maneuver, you may spend 1 <img class='inline-img' src='img/charge.png'>. If you do, every other ships at range 0 take 1 faceup damage card." }
D.upgrades[276] = { name_FRA = "Vaksaï (**)", name_ENG = "Vaksaï (**)", id = 275, slot = "Title", add_Data = {0}, force = 0, charge = {0}, effect_FRA = "ajoute 1 emplacement, <img class='inline-img' src='img/Modification.png'> et <img class='inline-img' src='img/Illicit.png'>. Les améliorations Modification et Illicit équipées coûtent -1 point chacune.", effect_ENG = "add 1 <img class='inline-img' src='img/Modification.png'> slot and <img class='inline-img' src='img/Illicit.png'> slot. Equipped Modification and Illicit upgrades cost 1 less point each." }
D.upgrades[277] = { name_FRA = "Unkar Plutt", name_ENG = "Unkar Plutt", id = 276, slot = "Crew", add_Data = {0}, force = 0, charge = {0}, effect_FRA = "Après avoir exécuté partiellement une manoeuvre, vous pouvez subir 1 dégat <img class='inline-img' src='img/hit.png'> pour effectuer 1 action blanche.", effect_ENG = "After you partially execute a maneuver, you may suffer 1 <img class='inline-img' src='img/hit.png'> damage to perform 1 white action." }
D.upgrades[278] = { name_FRA = "Gamut Key", name_ENG = "Gamut Key", id = 277, slot = "Crew", add_Data = {0}, force = 0, charge = {2, "yellow", "+"}, effect_FRA = "Au début de la phase de Fin, vous pouvez dépenser 2 <img class='inline-img' src='img/charge.png'> pour choisir un vaisseau à portée 0-1 avec 1 ou plusieurs jetons ronds. Pendant la phase de fin, ces jetons ronds ne sont pas retirés.", effect_ENG = "At the start of the End Phase, you may spend 2 <img class='inline-img' src='img/charge.png'> to choose a ship at range 0-1 with 1 or more circular tokens. During the End Phase, circular tokens are not removed from that ship." }
D.upgrades[279] = { name_FRA = "Greedo (existe déjà en 111)", name_ENG = "Greedo(already exists in 111)", id = 278, slot = "Special2", add_Data = {0}, force = 0, charge = {1, "yellow", "+"}, effect_FRA = "Lorsque vous attaquez, vous pouvez dépenser 1 <img class='inline-img' src='img/charge.png'> pour modifier 1 résultat <img class='inline-img' src='img/hit.png'> en <img class='inline-img' src='img/crit.png'>. Lorsque vous défendez, si votre charge est active, l'attaquant peut modifier 1 résultat <img class='inline-img' src='img/hit.png'> en <img class='inline-img' src='img/crit.png'>.", effect_ENG = "While you perform an attack, you may spend 1 <img class='inline-img' src='img/charge.png'> to change 1 <img class='inline-img' src='img/hit.png'> result to a <img class='inline-img' src='img/crit.png'> result. While you defend, if your <img class='inline-img' src='img/charge.png'> is active, the attacker may change 1 <img class='inline-img' src='img/hit.png'> result to a <img class='inline-img' src='img/crit.png'> result." }
D.upgrades[280] = { name_FRA = "0-0-0", name_ENG = "0-0-0", id = 279, slot = "Crew", add_Data = {0}, force = 0, charge = {0}, effect_FRA = "Au début de la phase d'engagement, vous pouvez choisir 1 vaisseau ennemi à portée 0-1. Dans ce cas, vous recevez 1 jeton calcul à moins que ce vaisseau ne choississe de recevoir 1 jeton stress.", effect_ENG = "At the start of the Engagement Phase, you may choose 1 enemy ship at range 0-1. If you do, you gain 1 calculate token unless that ship chooses to gain 1 stress token." }
D.upgrades[281] = { name_FRA = "BT-1", name_ENG = "BT-1", id = 280, slot = "Gunner", add_Data = {0}, force = 0, charge = {0}, effect_FRA = "Lorsque vous attaquez, vous pouvez modifier 1 résultat <img class='inline-img' src='img/hit.png'> en <img class='inline-img' src='img/crit.png'> pour chaque jeton stress que le défenseur possède.", effect_ENG = "While you perform an attack, you may change 1 <img class='inline-img' src='img/hit.png'> result to a <img class='inline-img' src='img/crit.png'> result for each stress token the defender has." }
D.upgrades[282] = { name_FRA = "Peli Motto", name_ENG = "Peli Motto", id = 281, slot = "Crew", add_Data = {0}, force = 0, charge = {0}, effect_FRA = "Pendant la phase Système, vous pouvez effectuer une action sur l'une de vos cartes de dégat, même stressé. Après avoir réparé une carte de dégat face visible, vous pouvez lancer 1 dé d'attaque. Sur un résultat <img class='inline-img' src='img/hit.png'>, réparez une autre carte de dégat face visible. Sur un résultat <img class='inline-img' src='img/crit.png'>, exposez 1 carte de dégat.", effect_ENG = "During the System Phase, you may perform an action on 1 of your damage cards, even while stressed. After you repair a faceup Ship damage card, you may roll 1 attack die. On a <img class='inline-img' src='img/hit.png'> result, repair another faceup Ship damage card. On a <img class='inline-img' src='img/crit.png'> result, expose 1 damage card." }
D.upgrades[283] = { name_FRA = "Shadow Caster", name_ENG = "Shadow Caster", id = 282, slot = "Title", add_Data = {0}, force = 0, charge = {0}, effect_FRA = "Retire un emplacement <img class='inline-img' src='img/Modification.png'> et ajoute un emplacement <img class='inline-img' src='img/Gunner.png'>.", effect_ENG = "Add 1 <img class='inline-img' src='img/Gunner.png'> slot, and remove 1 <img class='inline-img' src='img/Modification.png'> slot." }
D.upgrades[284] = { name_FRA = "Intrus", name_ENG = "Intruder", id = 283, slot = "Condition", add_Data = {0}, force = 0, charge = {0}, effect_FRA = "Si vous vérouillez une cible, recevez 1 marqueur de stress. Si vous recevez 1 marqueur de stress, alors recevez 1 marqueur d'épuisement.", effect_ENG = "When you acquire a lock, gain 1 stress token. If you receive a stress token, then receive 1 deplete token." }
D.upgrades[285] = { name_FRA = "Harcelé", name_ENG = "Harrassed", id = 284, slot = "Condition", add_Data = {0}, force = 0, charge = {0}, effect_FRA = "Lorsque vous retirez un jeton de stress, recevez 1 jeton contrainte ou épuisement de votre choix.", effect_ENG = "When you remove a stress token, receive a strain or deplete token of your choice." }
D.upgrades[286] = { name_FRA = "Tactique de Bombardement", name_ENG = "Bombing Tactic", id = 285, slot = "Condition", add_Data = {0}, force = 0, charge = {0}, effect_FRA = "Les bombes alliées ne vous infligent pas de dégats. Vous ne déclenchez pas les Mines alliées lorsque vous vous déplacez à travers.", effect_ENG = "Friendly bombs don't inflict damage on you. You don't trigger friendly Mines when you move through them" }
D.upgrades[287] = { name_FRA = "Suspect", name_ENG = "Suspect", id = 286, slot = "Condition", add_Data = {0}, force = 0, charge = {1, "yellow", "0"}, effect_FRA = "Si la <img class='inline-img' src='img/charge.png'> est active, au début de la phase d'engagement, vous recevez 1 jeton désarmement. Vous ne pouvez pas être attaqué. Pendant la phase de fin, vous pouvez dépenser 1 <img class='inline-img' src='img/charge.png'>. Si vous êtes le dernier vaisseau allié en jeu, perdez 1 <img class='inline-img' src='img/charge.png'>.<br>Si la <img class='inline-img' src='img/charge.png'> est inactive, pendant la phase système, tous les vaisseau ennemis à portée 0-3 peuvent vous verrouiller.", effect_ENG = "If the <img class='inline-img' src='img/charge.png'> is active, at the beginning of engagement phase, you receive a weapon disabled token. You cannot be attacked. During end phase you may spend 1<img class='inline-img' src='img/charge.png'>. If you are the last friendly ship alive, lose 1 <img class='inline-img' src='img/charge.png'>.<br>If the <img class='inline-img' src='img/charge.png'> is inactive, during system phase, all enemy ships at range 0-3 can acquire locks on you." }
D.upgrades[288] = { name_FRA = "Visions", name_ENG = "Visions", id = 287, slot = "Condition", add_Data = {0}, force = 0, charge = {0}, effect_FRA = "Lorsque Jacen Syndulla essaie de deviner votre manoeuvre, s'il a deviné juste votre direction, vous recevez 1 jeton épuisement. Si Jacen Syndulla devine en plus votre vitesse exacte, il récupère 1 <img class='inline-img' src='img/fo.png'>.", effect_ENG = "When Jacen Syndulla tries to guess your maneuver, if he guessed the right direction, you receive 1 deplete token. If Jacen Syndulla guessed also the exact speed, he recovers 1 <img class='inline-img' src='img/fo.png'>." }
