D.upgrades[309] = { name_FRA = "Sous Protection", name_ENG = "Guarded", id = 308, slot = "Condition", add_Data = {0}, force = 0, charge = {0}, effect_FRA = "Tant que vous défendez, si vous n'êtes pas dans le <img class='inline-img' src='img/bulls.png'> de l'attaquant, lancez 1 dé de défense supplémentaire pour chaque allié Protecteur Magna Garde calculateur ou esquivant situé dans l'arc d'attaque.", effect_ENG = "While you defend, if you are not in the attacker's <img class='inline-img' src='img/bulls.png'> , roll 1 additional defense die for each friendly calculating or evading MagnaGuard Protector in the attack arc." }
D.upgrades[310] = { name_FRA = "*Perfide", name_ENG = "*Treacherous", id = 309, slot = "Talent-special", add_Data = {0}, force = 0, charge = {0}, effect_FRA = "Tant que vous défendez, vous pouvez choisir un vaisseau gênant l’attaque et dépenser 1 <img class='inline-img' src='img/charge.png'>. Dans ce cas, annulez 1 résultat <img class='inline-img' src='img/hit.png'> ou <img class='inline-img' src='img/crit.png'> et le vaisseau que vous avez choisi gagne 1 marqueur de contrainte.<br>Après qu’un vaisseau à portée 0-3 a été détruit, récupérez 1 <img class='inline-img' src='img/charge.png'>.", effect_ENG = "While you defend, you may choose a ship obstructing the attack and spend 1 <img class='inline-img' src='img/charge.png'>. If you do, cancel 1 <img class='inline-img' src='img/hit.png'> or <img class='inline-img' src='img/crit.png'> result and the ship you chose gains 1 strain token.<br>After a ship at range 0-3 is destroyed, recover 1 <img class='inline-img' src='img/charge.png'>." }
D.upgrades[311] = { name_FRA = "Boba Fett", name_ENG = "Boba Fett", id = 310, slot = "Gunner", add_Data = {0}, force = 0, charge = {0}, effect_FRA = "Tant que vous effectuez une attaque, s’il n’y a aucun autre vaisseau dans l’arc d’attaque, vous pouvez changer 1 de vos résultats <img class='inline-img' src='img/Fo W.png'> en un résultat <img class='inline-img' src='img/hit.png'>.", effect_ENG = "While you perform an attack, if there are no other ships in the attack arc, you may change 1 of your <img class='inline-img' src='img/Fo W.png'> results to a <img class='inline-img' src='img/hit.png'> result." }
D.upgrades[312] = { name_FRA = "Dark Sidious", name_ENG = "Darth Sidious", id = 311, slot = "Crew", add_Data = {0}, charge = {1, "addCoFAction", ""}, effect_FRA = "Après avoir effectué une action <img class='inline-img' src='img/Co W.png'> violette, le vaisseau que vous avez coordonné gagne 1 marqueur de stress. Puis il gagne 1 marqueur de concentration ou récupère 1 <img class='inline-img' src='img/fo.png'>. Ajoute l'action <img class='inline-img' src='img/Co W.png'> violette.", effect_ENG = "After you perform a purple <img class='inline-img' src='img/Co W.png'> action, the ship you coordinated gains 1 stress token. Then it gains 1 focus token or recovers 1 <img class='inline-img' src='img/fo.png'>. Adds the purple <img class='inline-img' src='img/Co W.png'> action.", force = 1 }
D.upgrades[313] = { name_FRA = "Assaj Ventress", name_ENG = "Assaj Ventress", id = 312, slot = "Crew", add_Data = {0}, charge = {0}, effect_FRA = "Pendant la phase de système, vous pouvez dépenser 1 <img class='inline-img' src='img/fo.png'>. Dans ce cas, chaque vaisseau ennemi dans votre <img class='inline-img' src='img/attackF.png'> à portée 0-1 gagne 1 marqueur de contrainte sauf s'il choisit de gagner 1 marqueur de brouillage. ", effect_ENG = "During the System Phase, you may spend 1 <img class='inline-img' src='img/fo.png'>. If you do, each enemy ship in your <img class='inline-img' src='img/attackF.png'> at range 0-1 gains 1 strain token unless it chooses to gain 1 jam token.", force = 1 }
D.upgrades[314] = { name_FRA = "Jango Fett", name_ENG = "Jango Fett", id = 313, slot = "Crew", add_Data = {0}, force = 0, charge = {0}, effect_FRA = "Tant que vous défendez ou effectuez une attaque, vous pouvez dépenser votre verrouillage sur le vaisseau ennemi pour dégrader un de ses dés.", effect_ENG = "While you defend or perform an attack, you may spend your lock on the enemy ship to downgrade one of its dice." }
D.upgrades[315] = { name_FRA = "Comte Dooku", name_ENG = "Count Dooku", id = 314, slot = "Crew", add_Data = {0}, charge = {0}, force = 1, effect_FRA = "Durant une attaque, avant qu’un vaisseau à portée 0-2 ne lance des dés d’attaque ou de défense, si toutes vos <img class='inline-img' src='img/fo.png'> sont actives, vous pouvez dépenser 1 <img class='inline-img' src='img/fo.png'> et nommer un résultat. Si le lancer ne contient pas le résultat nommé, le vaisseau doit changer 1 dé pour ce résultat. ", effect_ENG = "During an attack, before a ship at range 0-2 rolls attack or defense dice, if all your <img class='inline-img' src='img/fo.png'> are active, you may spend 1 <img class='inline-img' src='img/fo.png'> and name a result. If the roll does not contain the named result, the ship must change 1 die to that result." }
D.upgrades[316] = { name_FRA = "Savage Opress", name_ENG = "Savage Opress", id = 315, slot = "Crew", add_Data = {0}, force = 0, charge = {0}, effect_FRA = "Après qu'un vaisseau allié dans votre à portée 1-2 a gagné un marqueur de stress ou de contrainte, vous pouvez dépenser 1 <img class='inline-img' src='img/fo.png'>. Dans ce cas, ce vaisseau allié gagne 1 marqueur de concentration.", effect_ENG = "After an allied ship at range 1-2 gains a stress or strain token, you may spend 1 <img class='inline-img' src='img/fo.png'>. If you do, that allied ship gains 1 focus token." }
D.upgrades[317] = { name_FRA = "Enchevêtrement", name_ENG = "Ensnare", id = 316, slot = "Special", add_Data = {0}, force = 0, charge = {0}, effect_FRA = "Cet amélioration a été intégrée au chassis n°35 pinpoint tractor array, et est inutilisée en l'état", effect_ENG = " This upgrade has been integrated into the n°35 pinpoint tractor array chassis, and is unused as is" }
