D.upgrades[320] = { name_FRA = "TIE Outland (***)", name_ENG = "TIE Outland (***)", id = 319, slot = "Title", add_Data = {0}, force = 0, charge = {1, "yellow", "0"}, effect_FRA = "Après avoir effectué une action, vous pouvez dépenser 1 <img class='inline-img' src='img/charge.png'>. Dans ce cas, vous pouvez effectuer une action <img class='inline-img' src='img/Bo W.png'> ou <img class='inline-img' src='img/Ev W.png'>.", effect_ENG = "After you perform an action, you may spend 1<img class='inline-img' src='img/charge.png'>. If you do, you may perform a <img class='inline-img' src='img/Bo W.png'> action, or <img class='inline-img' src='img/Ev W.png'> action." }
