D.upgrades[322] = { name_FRA = "Fondor", name_ENG = "Fondor", id = 321, slot = "Title", add_Data = {0}, force = 0, charge = {0}, effect_FRA = "Ajoute un emplacement <img class='inline-img' src='img/Illicit.png'> et un emplacement <img class='inline-img' src='img/Calculator.png'>", effect_ENG = "Add 1 <img class='inline-img' src='img/Illicit.png'> slot and 1 <img class='inline-img' src='img/Calculator.png'> slot" }
D.upgrades[323] = { name_FRA = "Agent Double", name_ENG = "Double Agent", id = 322, slot = "Condition", add_Data = {0}, force = 0, charge = {0}, effect_FRA = "Pendant la phase système, vous pouvez dépenser 1<img class='inline-img' src='img/charge.png'>. Dans ce cas, vous pouvez regarder le cadran d'un vaisseau ennemi à portée 0-1 du vaisseau avec la condition 'Agent Double'. De plus, vous bénéficiez ce tour ci de la capacité du pilote ou du <img class='inline-img' src='img/Crew.png'> concerné par 'Agent Double' à la place du vaisseau adverse.", effect_ENG = "During the system phase, you may spend 1 <img class='inline-img' src='img/charge.png'>. If you do, you may look at the dial of an enemy ship at range 0-1 of the ship with the 'Double Agent' condition. Additionally, you gain the ability of the pilot or <img class='inline-img' src='img/Crew.png'> associated with 'Double Agent' instead of the enemy ship for this round." }
D.upgrades[324] = { name_FRA = "Merrin", name_ENG = "Merrin", id = 323, slot = "Crew", force = 1, add_Data = {0}, charge = {0}, effect_FRA = "Pendant la phase système, vous pouvez dépenser 1 <img class='inline-img' src='img/fo.png'>. Dans ce cas, recevez 1 jeton épuisement et un jeton occultation.", effect_ENG = "During System phase, you may spend 1 <img class='inline-img' src='img/fo.png'>. If you do, receive 1 deplete token and 1 cloak token." }
D.upgrades[325] = { name_FRA = "Commando Wookie", name_ENG = "Wookie Commando", id = 324, slot = "Gunner", add_Data = {0}, force = 0, charge = {1, "yellow", "+"}, effect_FRA = "Lorsque un vaisseau ennemi effectue une manœuvre à portée 0-1 dans votre <img class='inline-img' src='img/attack180.png'>, vous pouvez dépenser 1 <img class='inline-img' src='img/charge.png'>. Dans ce cas, lancez 1 dé.<br><img class='inline-img' src='img/crit.png'> : infligez 1 dégât ; <img class='inline-img' src='img/hit.png'>/<img class='inline-img' src='img/Fo W.png'> : exposez 1 carte de dégât ou infligez 1 jeton contrainte.", effect_ENG = "When an enemy ship executes a maneuver at range 0-1 in your <img class='inline-img' src='img/attack180.png'>, you may spend 1 <img class='inline-img' src='img/charge.png'>. If you do, roll a die.<br><img class='inline-img' src='img/crit.png'> : deal a damage; <img class='inline-img' src='img/hit.png'>/<img class='inline-img' src='img/Fo W.png'> : expose a damage card or deal a strain token." }
D.upgrades[326] = { name_FRA = "Moroff", name_ENG = "Moroff", id = 325, slot = "Gunner", add_Data = {0}, force = 0, charge = {0}, effect_FRA = "Après avoir effectué une attaque, vous pouvez effectuer une attaque bonus avec une arme différente. Vous pouvez modifier un résultat <img class='inline-img' src='img/hit.png'> en un résultat <img class='inline-img' src='img/crit.png'> pour cette attaque bonus.", effect_ENG = "After you perform an attack, you may perform a bonus attack with a different weapon. You may modify a <img class='inline-img' src='img/hit.png'> result into a <img class='inline-img' src='img/crit.png'> result for this bonus attack." }
D.upgrades[327] = { name_FRA = "Magva Yarro", name_ENG = "Magva Yarro", id = 326, slot = "Gunner", add_Data = {0}, force = 0, charge = {0}, effect_FRA = "Lorsque un vaisseau ennemi dans votre arc de tir effectue une attaque, il ne peut pas relancer plus d'1 dé. Après que vous avez effectué une attaque, vous pouvez effectuer une attaque depuis un arc différent.", effect_ENG = "When an enemy ship in your firing arc performs an attack, it cannot reroll more then 1 dice. After you perform an attack, you may perform an attack from a different arc." }
D.upgrades[328] = { name_FRA = "Napalm", name_ENG = "Firebomb", id = 327, slot = "Illicit", add_Data = {0}, force = 0, charge = {1, "yellow", "0"}, effect_FRA = "Considérez le comme un engin de type Mine. Vous pouvez le larguer pendant la phase système. Lorsqu'un vaisseau se déplace à travers ou le chevauche, il saute sa phase 'effectuer une action', puis il expose une carte de dégat, et vous pouvez retourner l'une de ses <img class='inline-img' src='img/charge.png'> située sur son pilote ou une de ses améliorations.", effect_ENG = "Consider it as a Mine. You may drop it during System Phase. When a ship moves through, it exposes a damage card, and you may flip off 1 of its <img class='inline-img' src='img/charge.png'> located on its pilot card or upgrade." }
