D.upgrades[330] = { name_FRA = "Kleya Marki", name_ENG = "Kleya Marki", id = 329, slot = "Crew", add_Data = {0}, force = 0, charge = {1, "addJaWAction", "linkCoRAction"}, effect_FRA = "Ajoute l'action <img class='inline-img' src='img/Ja W.png'> -> <img class='inline-img' src='img/Co W.png'> rouge", effect_ENG = "Add action <img class='inline-img' src='img/Ja W.png'> -> Red <img class='inline-img' src='img/Co W.png'>" }
D.upgrades[331] = { name_FRA = "Agent Kallus", name_ENG = "Agent Kallus", id = 330, slot = "Crew", add_Data = {0}, force = 0, charge = {0}, effect_FRA = "Fin de la mise en place : assignez la condition 'Traqué' à un vaisseau ennemi.", effect_ENG = "END OF SETUP : assign the 'Hunted' condition to an enemy ship." }
D.upgrades[332] = { name_FRA = "Traqué", name_ENG = "Hunted", id = 331, slot = "Condition", add_Data = {0}, force = 0, charge = {0}, effect_FRA = "Lorsque vous êtes attaqué par un vaisseau avec l'amélioration 'Agent Kallus', il peut modifier un résultat <img class='inline-img' src='img/Fo W.png'> en un résultat <img class='inline-img' src='img/hit.png'>. Lorsque vous êtes détruit, votre adversaire gagne 1 PO (cela déclenche aussi le gain de point Tactique).", effect_ENG = "When you are attacked by a ship with the Agent Kallus upgrade, it may modify an <img class='inline-img' src='img/Fo W.png'> result to a <img class='inline-img' src='img/hit.png'> result. When you are destroyed, your opponent gains 1 PO (it triggers also the gain of Tactic point)" }
D.upgrades[333] = { name_FRA = "Slicer du BSI", name_ENG = "ISB Slicer", id = 332, slot = "Crew", add_Data = {0}, force = 0, charge = {0}, effect_FRA = "À la fin de la phase, les vaisseaux ennemis à portée 0-2 ne peuvent pas retirer leur marqueur de brouillage.", effect_ENG = "Enemy ships at range 0-2 don't remove their jam token during end phase." }
D.upgrades[334] = { name_FRA = "Death Troopers", name_ENG = "Death Troopers", id = 333, slot = "Crew", add_Data = {0}, force = 0, charge = {0}, effect_FRA = "Pendant la phase d’activation, les vaisseaux ennemis à portée 0-1 ne peuvent pas retirer de marqueurs de stress.", effect_ENG = "During Activation Phase, enemy ships don't remove their stress token if they are at range 0-1." }
D.upgrades[335] = { name_FRA = "Agent du BSI", name_ENG = "ISB Agent", id = 334, slot = "Gunner", add_Data = {0}, force = 0, charge = {0}, effect_FRA = "Lorsque vous gagnez un jeton bleu, s'il y a un vaisseau ennemi dans votre <img class='inline-img' src='img/bulls.png'>, vous pouvez brouiller ce vaisseau.", effect_ENG = "When you gain a blue token, if there's an enemy ship in your <img class='inline-img' src='img/bulls.png'>, you may jam that ship." }
D.upgrades[336] = { name_FRA = "Banque de Données du BSI", name_ENG = "ISB Databank", id = 335, slot = "Calculator", add_Data = {0}, force = 0, charge = {0}, effect_FRA = "Au début de la phase d'engagement, s'il y a un vaisseau ennemi brouillé à portée 0-1, gagnez 1 jeton de calcul.", effect_ENG = "At the start of Engagement Phase, if there is a jammed enemy ship at range 0-1, gain 1 calculate token" }
D.upgrades[337] = { name_FRA = "Directeur Krennic", name_ENG = "Director Krennic", id = 336, slot = "Crew", add_Data = {0}, force = 0, charge = {0}, effect_FRA = "Mise en place : avant de placer les forces, assignez la condition 'Prototype Optimisé' à un autre vaisseau allié.", effect_ENG = "Setup: Before placing forces, assign the 'Optimized Prototype' condition to another friendly ship." }
D.upgrades[338] = { name_FRA = "Prototype Optimisé", name_ENG = "Optimized Prototype", id = 337, slot = "Condition", add_Data = {0}, force = 0, charge = {0}, effect_FRA = "Lorsque vous effectuez une attaque principale contre un vaisseau verrouillé par un vaisseau allié avec l'amélioration 'Directeur Krennic', vous pouvez dépenser 1 résultat non vierge. Dans ce cas, choisissez l'un des effets suivants : le défenseur perd 1 bouclier ou le défenseur expose une carte de dégât.", effect_ENG = "While you perform a primary attack against a ship locked by a friendly ship with the Director Krennic upgrade, you may spend 1 non-blank result. If you do, choose one: the defender loses 1 shield or the defender exposes a damage card." }
D.upgrades[339] = { name_FRA = "Moff Jerjerrod", name_ENG = "Moff Jerjerrod", id = 338, slot = "Crew", add_Data = {0}, force = 0, charge = {2, "yellow", "+"}, effect_FRA = "Pendant la phase de système, vous pouvez dépenser 2 <img class='inline-img' src='img/charge.png'>. Dans ce cas, choisissez le gabarit 1<img class='inline-img' src='img/manBl2.png'>, 1<img class='inline-img' src='img/manSt2.png'> ou 1<img class='inline-img' src='img/manBr2.png'>. Chaque vaisseau allié peut effectuer une action <img class='inline-img' src='img/Bo W.png'> rouge en utilisant ce gabarit.", effect_ENG = "During the System Phase, you may spend 2 <img class='inline-img' src='img/charge.png'>. If you do, choose the 1<img class='inline-img' src='img/manBl2.png'>, 1<img class='inline-img' src='img/manSt2.png'> ou 1<img class='inline-img' src='img/manBr2.png'> template. Each friendly ship may perform a red <img class='inline-img' src='img/Bo W.png'> action using that template." }
D.upgrades[340] = { name_FRA = "Larma D'Acy", name_ENG = "Larma D'Arcy", id = 339, slot = "Crew", add_Data = {0}, force = 0, charge = {0}, effect_FRA = "Tant que vous avez 2 marqueurs de stress ou moins, vous pouvez effectuer des actions <img class='inline-img' src='img/Re W.png'>, <img class='inline-img' src='img/Co W.png'> et <img class='inline-img' src='img/Ja W.png'>.<br>Tant que vous effectuez une action blanche <img class='inline-img' src='img/Re W.png'>, <img class='inline-img' src='img/Co W.png'> ou <img class='inline-img' src='img/Ja W.png'>, si vous êtes stressé, gagnez 1 jeton épuisement.", effect_ENG = "While you have 2 or fewer stress tokens, you may perform <img class='inline-img' src='img/Re W.png'>, <img class='inline-img' src='img/Co W.png'> and <img class='inline-img' src='img/Ja W.png'> actions.<br>While you perform a white <img class='inline-img' src='img/Re W.png'>, <img class='inline-img' src='img/Co W.png'> or <img class='inline-img' src='img/Ja W.png'> action, if you are stressed, gain 1 deplete token." }
D.upgrades[341] = { name_FRA = "Korr Sella", name_ENG = "Korr Sella", id = 340, slot = "Crew", add_Data = {0}, force = 0, charge = {0}, effect_FRA = "Après avoir entièrement exécuté une manœuvre bleue, retirez tous vos marqueurs de stress.", effect_ENG = "After you fully execute a blue maneuver, remove all your stress tokens." }
D.upgrades[342] = { name_FRA = "Générale Organa", name_ENG = "General Organa", id = 341, slot = "Crew", add_Data = {0}, force = 1, charge = {0}, effect_FRA = "After a friendly ship reveals a non-0<img class='inline-img' src='img/manOp2.png'> maneuver, you may spend 1 <img class='inline-img' src='img/fo.png'>. If you do, the chosen ship reduces the difficulty of that maneuver.", effect_ENG = "After a friendly ship reveals a non-0<img class='inline-img' src='img/manOp2.png'> maneuver, you may spend 1 <img class='inline-img' src='img/fo.png'>. If you do, the chosen ship reduces the difficulty of that maneuver." }
D.upgrades[343] = { name_FRA = "Amilyn Holdo", name_ENG = "Amilyn Holdo", id = 342, slot = "Crew", add_Data = {0}, force = 0, charge = {0}, effect_FRA = "ACTION : Exécutez une maneuvre 5<img class='inline-img' src='img/manSt2.png'> vers l'avant. Si votre position finale recouvre celle d'un autre vaisseau, ce vaisseau subit 1/2/3/4 dégats si vous êtes un vaisseau petit/moyen/grand/énorme. Puis votre vaisseau est détruit. Si un vaisseau ennemi a été détruit de cette manière, gagnez 1 PO", effect_ENG = "ACTION : Execute a 5<img class='inline-img' src='img/manSt2.png'> forward maneuver. If your final position overlaps another ship, this ship suffers 1/2/3/4 damage if you are a small/medium/large/huge ship. Then your ship is destroyed. If an enemy ship is destroyed this way, receive 1 PO" }
D.upgrades[344] = { name_FRA = "*Optimiste", name_ENG = "*Hopeful", id = 343, slot = "Talent-special", add_Data = {0}, force = 0, charge = {0}, effect_FRA = "Après qu'un autre vaisseau allié à portée 0-3 a été détruit, si ce vaisseau était limité ou qu'il avait l'amélioration Optimiste, vous pouvez effectuer une action <img class='inline-img' src='img/Fo W.png'> ou <img class='inline-img' src='img/Bo W.png'>.", effect_ENG = "After another friendly ship at range 0-3 is destroyed, if that ship is limited or has the Hopeful upgrade, you may perform a <img class='inline-img' src='img/fo.png'> or <img class='inline-img' src='img/Bo W.png'> action." }
D.upgrades[345] = { name_FRA = "Jacen Syndulla", name_ENG = "Jacen Syndulla", id = 344, slot = "Crew", add_Data = {0}, force = 0, charge = {0}, effect_FRA = "Mise en place : avant de placer les forces, assignez la condition 'Visions' à un vaisseau ennemi. En phase système, si le vaisseau avec 'Visions' est à portée 0-2, vous pouvez tenter de deviner sa manoeuvre.", effect_ENG = "Setup: Before placing forces, assign the 'Visions' condition to an enemy ship. During System Phase, if the ship with 'Visions' is at range 0-2, you may attempt to guess its maneuver." }
