D.upgrades[350] = { name_FRA = "Jas Emari", name_ENG = "Jas Emari", id = 349, slot = "Crew", add_Data = {0}, force = 0, charge = {0}, effect_FRA = "Lorsque vous vous défendez contre un vaisseau ennemi avec une condition, vous pouvez améliorer un résultat d'un dé de défense.", effect_ENG = "When you defend against an enenmy ship with a condition, you may upgrade a defense die." }
D.upgrades[351] = { name_FRA = "Puce CoMar Tri-Tracker", name_ENG = "CoMar Tri-Tracker Chip", id = 350, slot = "Calculator", add_Data = {0}, force = 0, charge = {0}, effect_FRA = "Lorsque vous attaquez un vaisseau que vous avez verrouillé, vous pouvez dépenser votre verrouillage pour modifier autant de résultats que souhaités en résultats <img class='inline-img' src='img/hit.png'>", effect_ENG = "When you perform an attack against a ship you have locked, you may spend your lock to modify as many results as you wish into <img class='inline-img' src='img/hit.png'> results." }
D.upgrades[352] = { name_FRA = "*Noble Tradition", name_ENG = "*Proud Tradition", id = 351, slot = "Talent-special", add_Data = {0}, force = 0, charge = {0}, effect_FRA = "Tant que vous avez 2 marqueurs de stress ou moins, vous pouvez effectuer des actions <img class='inline-img' src='img/Fo W.png'>, même si vous êtes stressé. Après que vous avez effectué une attaque, si vous êtes stressé, le défenseur peut dépenser 1 marqueur de concentration ou subir 1 dégât <img class='inline-img' src='img/crit.png'>. Dans ce cas, votre action <img class='inline-img' src='img/Fo W.png'> dans votre barre d'action devient rouge.", effect_ENG = "While you have 2 or fewer stress tokens, you may perform <img class='inline-img' src='img/Fo W.png'> actions, even if you are stressed. After you perform an attack, if you are stressed, the defender may spend 1 focus token or suffer 1 <img class='inline-img' src='img/crit.png'> damage. If it does, your <img class='inline-img' src='img/Fo W.png'> action in your action bar becomes red." }
D.upgrades[353] = { name_FRA = "Agent Terex", name_ENG = "Agent Terex", id = 352, slot = "Crew", add_Data = {0}, force = 0, charge = {0}, effect_FRA = "Durant la mise en place, placez 3 jetons calcul sur cette amélioration.<br>Pendant la phase système, vous pouvez transférer 1 de ces jetons calculs vers 1 vaisseau à portée 0-3.<br>Lorsqu'il n'y a plus de jetons calculs, pendant la phase de système, lancez 1 dé d’attaque. Sur un résultat <img class='inline-img' src='img/hit.png'> ou <img class='inline-img' src='img/crit.png'> gagnez 1 marqueur de calcul. Sinon, gagnez 1 marqueur de brouillage.<br>ACTION : Transférez 1 jeton calcul ou de brouillage depuis votre vaisseau avec un autre vaisseau à portée 1-3.", effect_ENG = "During SETUP, place 3 calculate tokens onto this upgrade.<br>During System Phase, you may transfer 1 of these tokens to a ship at range 0-3.<br>When there is no more calcultate tokens on this upgrade, during System Phase, roll an attack die. On a <img class='inline-img' src='img/hit.png'> or <img class='inline-img' src='img/crit.png'>, gain 1 calculate token. Else gain 1 jam token.<br>ACTION : Transfer 1 calculate or jam token from you to another ship at range 1-3." }
D.upgrades[354] = { name_FRA = "Commandante Malarus", name_ENG = "Commander Malarus", id = 353, slot = "Crew", add_Data = {0}, force = 0, charge = {0}, effect_FRA = "Lorsqu'un vaisseau allié à portée 0-1 avec une initiative inférieure effectue une attaque, il peut relancer un résultat vierge'. Dans ce cas, et si cette attaque ne touche pas, il reçoit un jeton stress.", effect_ENG = "When a friendly ship at range 0-1 with a lower initiative performs an attack, he may reroll a blank result. In this case, and if this attack doesn't hit, he receives a stress token." }
D.upgrades[355] = { name_FRA = "Général Pryde", name_ENG = "General Pryde", id = 354, slot = "Crew", add_Data = {0}, force = 0, charge = {0}, effect_FRA = "Lorsque vous attaquez ou défendez contre un vaisseau brouillé, vous pouvez recevoir 1 jeton contrainte pour lancer un dé supplémentaire.", effect_ENG = "When you attack or defend against a jammed ship, you may receive 1 strain token to roll 1 additional die." }
D.upgrades[356] = { name_FRA = "Vikrul", name_ENG = "Vikrul", id = 355, slot = "Gunner", add_Data = {0}, charge = {0}, force = 1, effect_FRA = "Lorsque vous attaquez un vaisseau avec un jeton orange, vous pouvez dépenser 1 <img class='inline-img' src='img/fo.png'> pour dégrader 1 dé de défense du défenseur.", effect_ENG = "When you perform an attack againt a ship with an orange token, you may spend 1 <img class='inline-img' src='img/fo.png'> to downgrade 1 defense die from the defender." }
D.upgrades[357] = { name_FRA = "Kuruk", name_ENG = "Kuruk", id = 356, slot = "Crew", add_Data = {0}, charge = {0}, force = 1, effect_FRA = "Ajoute 1 emplacement de type 'Force-Dark'. Lorsque vous récupérez un point de force, vous pouvez retirer un marqueur de contrainte ou d'épuisement.", effect_ENG = "Add 1 'Force-Dark' slot. When you recover 1 force point, you may remove 1 strain or deplete token." }
D.upgrades[358] = { name_FRA = "Amirale Sloane", name_ENG = "Admiral Sloane", id = 357, slot = "Crew", add_Data = {0}, force = 0, charge = {0}, effect_FRA = "Après qu'un vaisseau ennemi à portée 0-2 a détruit un vaisseau allié, il reçoit 1 marqueur de stress.", effect_ENG = "When an enemy ship at range 0-2 destroys a friendly ship, he receives 1 stress token." }
D.upgrades[359] = { name_FRA = "Soeurs de la Nuit", name_ENG = "Night Sisters", id = 358, slot = "Crew", add_Data = {0}, charge = {0}, force = 3, effect_FRA = "Vous ne pouvez pas récupérer de la force en phase de fin. Lorsqu'un vaisseau allié à portée 3 est détruit, vous pouvez dépenser 1<img class='inline-img' src='img/fo.png'>. Dans ce cas, ne le retirez pas de la partie pendant ce tour. Pendant la phase système, vous pouvez dépenser 1 <img class='inline-img' src='img/fo.png'> pour qu'un vaisseau allié détruit ne soit pas retiré de la partie pour le reste de ce tour.", effect_ENG = "You cannot recover force tokens during End Phase. When a friendly ship at range 3 is destroyed, you may spend 1 <img class='inline-img' src='img/fo.png'>. If you do, don't remove it from the game. During System Phase, you may spend 1 <img class='inline-img' src='img/fo.png'> so that a targeted destroyed friendly ship is not removed from the game this turn." }
D.upgrades[360] = { name_FRA = "Capitaine Enoch", name_ENG = "Captain Enoch", id = 359, slot = "Crew", add_Data = {0}, force = 0, charge = {0}, effect_FRA = "Lorsque vous coordonnez un vaisseau, vous pouvez revoir un dégat <img class='inline-img' src='img/crit.png'> ou exposer une carte de dégat. Dans ce cas, tous les vaisseaux alliés à portée 0-1 du vaisseau coordonné peuvent effectuer l'action choisie par le vaisseau coordonné, sous condition d'être capable de l'effectuer, et avec le niveau de difficulté adéquat.", effect_ENG = "When you coordinate a ship, you may suffer a <img class='inline-img' src='img/crit.png'> damage or expose a damage card. If you do, each friendly ships at range 0-1 of the coordinated ship may perform this ship's chosen action, under the condition that they are able to perform it, with the accordingly difficulty." }
D.upgrades[361] = { name_FRA = "Morgan Elsbeth", name_ENG = "Morgan Elsbeth", id = 360, slot = "Crew", add_Data = {0}, force = 1, charge = {0}, effect_FRA = "Ajoute un emplacement 'Force-Dark'. Lorsque vous dépensez 1 ou plusieurs points de force, vous pouvez choisir un vaisseau ennemi à portée 0-2. Dans ce cas, ce vaisseau doit immédiatement planifier sa prochaine manoeuvre et ne peut plus la modifier tant qu'elle n'a pas été révélée.", effect_ENG = "Add a 'Force-Dark' slot. When you spend 1 or several force points, you may choose an enemy ship at range 0-2. If you do, this ship must select its next maneuver, and he cannot modify its dial until it is revealed." }
D.upgrades[362] = { name_FRA = "Docteur Pershing", name_ENG = "Doctor Pershing", id = 361, slot = "Crew", add_Data = {0}, force = 0, charge = {1, "yellow", "0"}, effect_FRA = "Lorsqu'un vaisseau ennemi à portée 0-3 utilise un point de force, vous pouvez récupérez votre <img class='inline-img' src='img/charge.png'>. En phase système, vous pouvez dépensez 1 <img class='inline-img' src='img/charge.png'> pour aquérir une cible à portée 0-3.", effect_ENG = "When an enemy ship at range 0-3 spends a force point, you may recover a <img class='inline-img' src='img/charge.png'>. During System Phase, you may spend 1 <img class='inline-img' src='img/charge.png'> to gain a lock on a target at range 0-3." }
D.upgrades[363] = { name_FRA = "Purge Troopers", name_ENG = "Purge Troopers", id = 362, slot = "Crew", add_Data = {0}, force = 0, charge = {0}, effect_FRA = "Lorsque vous vous engagez, lorsque vous déclarez la cible de votre attaque, celle ci choisit si elle reçoit un marqueur de stress, contrainte ou épuisement.", effect_ENG = "When you engage, when you declare your attack target, it chooses to receive a stress or strain or deplete token." }
D.upgrades[364] = { name_FRA = "Syndicat Pyke", name_ENG = "Pyke Syndicate", id = 363, slot = "Special", add_Data = {0}, force = 0, charge = {0}, effect_FRA = "", effect_ENG = "" }
D.upgrades[365] = { name_FRA = "Aube Ecarlate", name_ENG = "Crimson Dawn", id = 364, add_Data = {0}, slot = "Special", force = 0, charge = {0}, effect_FRA = "", effect_ENG = "" }
D.upgrades[366] = { name_FRA = "Sacrifice", name_ENG = "Sacrifice", id = 365, add_Data = {0}, slot = "Talent-elite", force = 0, charge = {0}, effect_FRA = "Gagnez 2 points de Logistique", effect_ENG = "Gain 2 Logistics points" }
D.upgrades[367] = { name_FRA = "Canon Blaster", name_ENG = "Blaster Cannon", id = 366, slot = "Cannon", add_Data = {0}, force = 0, charge = {0}, effect_FRA = "2<img class='inline-img' src='img/attackF.png'> portée 1-3", effect_ENG = "2<img class='inline-img' src='img/attackF.png'> Range 1-3" }
D.upgrades[368] = { name_FRA = "Missile à concussion ST2", name_ENG = "ST2 Concussion Missile", id = 367, slot = "Missile", add_Data = {0}, force = 0, charge = {2, "yellow", "0"}, effect_FRA = "Attaque <img class='inline-img' src='img/Lo W.png'> : 4<img class='inline-img' src='img/attackF.png'> portée 2-3  : dépensez 1 <img class='inline-img' src='img/charge.png'>. Si cette attaque touche, après avoir attribué les dégats, exposez une carte de dégat du défenseur.", effect_ENG = "Attack <img class='inline-img' src='img/Lo W.png'> : 4<img class='inline-img' src='img/attackF.png'> Range 2-3 : spend 1 <img class='inline-img' src='img/charge.png'>. If this attack hits, after assigning damage, expose 1 damage card from the defender." }
D.upgrades[369] = { name_FRA = "Désigné pour mourir", name_ENG = "Marked for Elimination", id = 368, slot = "Condition", add_Data = {0}, force = 0, charge = {0}, effect_FRA = "Lorsque vous défendez, si l'attaquant est équippé avec Capteur de Positionnement et a un verrouillage sur vous, vous ne pouvez pas dépenser des jetons verts.", effect_ENG = "While you defend, if the attacker is equipped with Tracking Fob and has a lock on you, you cannot spend green tokens." }
D.upgrades[370] = { name_FRA = "*Focalisé", name_ENG = "*Enthralled", id = 369, slot = "Talent-special", add_Data = {0}, force = 0, charge = {0}, effect_FRA = "Lorsque vous effectuez une action de scénario, gagnez 1 jeton calcul.", effect_ENG = "While you perform a scenario action, gain 1 calculate token." }
D.upgrades[371] = { name_FRA = "Proie", name_ENG = "Prey", id = 370, slot = "Condition", add_Data = {0}, force = 0, charge = {0}, effect_FRA = "Lorsque vous êtes détruit, vous devez assigner la condition 'Proie' à un vaisseau allié au delà de la portée 3 de vous. S'il n'y en a pas, assignez la à un vaisseau à portée 3. Répétez cette opération en réduisant la portée jusqu'à trouver une cible potentielle.", effect_ENG = "When you are destroyed, you MUST assign the prey condition to a friendly ship beyond range 3 of you. If there's none, assign it to a ship at range 3. Continue this operation by reducing the range until there's a suitable target." }
D.upgrades[372] = { name_FRA = "Tir de Suppression", name_ENG = "Suppressive Fire", id = 371, slot = "Condition", add_Data = {0}, force = 0, charge = {0}, effect_FRA = "Tant que vous effectuez une attaque contre un vaisseau autre que le Capitaine Rex, lancez 1 dé d'attaque an moins. Après que le Capitaine Rex a défendu, retirez cette condition. A la fin de la phase d’engagement, si le Capitaine Rex n'a pas effectué d'attaque à cette phase, retirez cette condition. Après que le Capitaine Rex a été détruit, retirez cette condition.", effect_ENG = "While you perform an attack against a ship that is not Captain Rex, roll 1 less attack die. After Captain Rex defends, remove this condition. At the end of engagement phase, if Captain Rex hasn't attacked this phase, remove this condition. After Captain Rex is destroyed, remove this condition." }
D.upgrades[373] = { name_FRA = "Munitions Supplémentaires", name_ENG = "Extra Munitions", id = 372, slot = "Modification", add_Data = {0}, force = 0, charge = {0}, effect_FRA = "Au début de la phase de mise en place, vous devez choisir une amélioration <img class='inline-img' src='img/missile.png'>, <img class='inline-img' src='img/Torpedo.png'> ou <img class='inline-img' src='img/Payload.png'>, et placez 1 jeton munition dessus. En phase système, vous pouvez dépenser ce jeton munition et recevoir 1 jeton désarmement. Dans ce cas, récupérez 1 <img class='inline-img' src='img/charge.png'> sur cette munition.", effect_ENG = "" }
D.upgrades[374] = { name_FRA = "Je vais te montrer le côté obscur", name_ENG = "I'll show you the Dark Side", id = 373, slot = "Condition", add_Data = {0}, force = 0, charge = {0}, effect_FRA = "Lorsque vous subissez un dégat, votre adversaire va chercher dans votre paquet de dégats une carte de dégat Pilote. Vous en subissez les effets mais elle ne compte pas dans votre décompte de dégats. Puis vous retirez cette condition.", effect_ENG = "When you suffer a damage, your opponent searches your damage deck for a damage Pilot Card. You apply this card effect, but it doesn't count as a damage when deciding if you're destroyed or not. Then, remove this condition." }
D.upgrades[375] = { name_FRA = "Mission Sauvetage d'Otage", name_ENG = "Hostage Rescue Mission", id = 374, slot = "Condition", add_Data = {0}, force = 0, charge = {0}, effect_FRA = "Mission Sauvetage d'Otage : A la fin du jeu, gagnez 3 PO. Lorsque vous êtes détruit, larguez une 'Capsule de l'Otage' à portée 1 de vous et perdez la condition 'MSO'.<br>Capsule de l'Otage : (Satellite) Quand un vaisseau est à portée 0-1, il peut effectuer une action de sauvetage : (ACTION SCENARIO) : Assignez la condition 'MSO' à votre vaisseau, et remettez la capsule de l'otage en réserve.", effect_ENG = "<br>Hostage Rescue Mission : At the end of the game, gain 3 PO. When you are destroyed, drop a 'Hostage Capsule' at range 1 of you and lose the 'HRM' condition.<br>Hostage Capsule : (Remote) When a ship is at range 0-1, it can do a rescue action : (SCENARIO ACTION) : assign the 'HRM' condition to your ship, and put the Hostage Capsule into Reserve." }
D.upgrades[376] = { name_FRA = "Haine", name_ENG = "Hate", id = 375, slot = "Force-Dark", add_Data = {0}, force = 0, charge = {0}, effect_FRA = "Lorsque vous encaissez des dégats, vous pouvez récupérer 1 <img class='inline-img' src='img/fo.png'>", effect_ENG = "When you suffer damages, you may recover 1 <img class='inline-img' src='img/fo.png'>" }
D.upgrades[377] = { name_FRA = "Justiciable", name_ENG = "Answerable to the law", id = 376, slot = "Condition", add_Data = {0}, force = 0, charge = {0}, effect_FRA = "Après avoir défendu, si vous n'avez pas reçu de dégat, recevez 1 marqueur d'épuisement.", effect_ENG = "After defending, if you have not suffered any damage, then receive 1 deplete token." }
D.upgrades[378] = { name_FRA = "Proie Effrayée", name_ENG = "Fearful Prey", id = 377, slot = "Condition", add_Data = {0}, force = 0, charge = {0}, effect_FRA = "Après avoir défendu contre un ennemi Prédateur Effrayant, si vous n'avez pas dépensé au moins 1 marqueur vert durant l'attaque, gagnez 1 marqueur de contrainte.", effect_ENG = "After you defend against an enemy Fearsome Predator, if you did not spend at least 1 green token during the attack, gain 1 strain token." }
D.upgrades[379] = { name_FRA = "Manoeuvre Malaisante", name_ENG = "Sickening Maneuver", id = 378, slot = "Condition", add_Data = {0}, force = 0, charge = {0}, effect_FRA = "Vous pouvez exécuter des manœuvres rouges, même si vous êtes stressé. Après avoir révélé une manœuvre de virage sur l'aile <img class='inline-img' src='img/manTl2.png'> ou <img class='inline-img' src='img/manTr2.png'>  ou de virage <img class='inline-img' src='img/manBl2.png'> ou <img class='inline-img' src='img/manBr2.png'>, vous devez gagner 1 marqueur de contrainte et exécuter cette manœuvre comme un dérapage. Après avoir révélé une manœuvre en ligne droite <img class='inline-img' src='img/manSt2.png'> , vous devez exécuter cette manœuvre comme un virage Koiogran <img class='inline-img' src='img/manKo2.png'>  rouge. Après avoir exécuté une manœuvre, retirez cet état.", effect_ENG = "You can execute red maneuvers even while stressed. After you reveal a bank <img class='inline-img' src='img/manBl2.png'> or <img class='inline-img' src='img/manBr2.png'>  or turn <img class='inline-img' src='img/manTl2.png'> or <img class='inline-img' src='img/manTr2.png'> maneuver, you must gain 1 strain and execute the maneuver as a sideslip. After you reveal a straight <img class='inline-img' src='img/manSt2.png'>  maneuver, you must execute that maneuver as a red koiogran turn <img class='inline-img' src='img/manKo2.png'> . After you execute a maneuver, remove this condition." }
D.upgrades[380] = { name_FRA = "*Menaçant", name_ENG = "*Threatening", id = 379, slot = "Talent-special", add_Data = {0}, force = 0, charge = {0}, effect_FRA = "", effect_ENG = "" }
