D.leaders[34] = { leadername_FRA = "!!Reine Soruna", leadername_ENG = "!!Queen Soruna", leaderfaction = {"New_Republic_Patrol", "Naboo_Defense_Force", ""}, leaderid = 33, leaderability_FRA = "<div class='text'>Lorsqu'un de vos vaisseaux détruit un vaisseau adverse, vous pouvez dépenser 1 <img class='inline-img' src='img/charge.png'>. Dans ce cas, ce vaisseau gagne l'un de ces bonus jusqu'à la fin de la partie : <Initiative +1>, <Action <img class='inline-img' src='img/Co W.png'>, <Début phase Activation : vous pouvez choisir un vaisseau allié à portée 1. Dans ce cas, il gagne votre initiative jusqu'à la fin du tour></div>", leaderability_ENG = "<div class='text'>When one of your ships destroys an enemy ship, you can spend 1 <img class='inline-img' src='img/charge.png'>. If you do, that ship gains one of these bonuses until the end of the game: <Initiative +1>, <Action <img class='inline-img' src='img/Co W.png'>, <Start of Activation phase: you can choose an allied ship at range 1. If you do, it gains your initiative until the end of the turn></div>", charge = {3, "yellow"}, logistic = 15 }
