D.chassis[1] = { name = "", id = 0, effect1_FRA = "", effect2_FRA = "", effect3_FRA = "" }
D.chassis[2] = { name = "Copilot", id = 1, effect1_FRA = "(Copilote) : Tant que vous êtes arrimé, votre Vaisseau-Mère considère aussi votre capacité de pilote comme étant la sienne.", effect2_FRA = "", effect3_FRA = "", effect1_ENG = "(Copilot) : While you are docked, your Docking Ship also considers your pilot ability as its own.", effect2_ENG = "", effect3_ENG = "" }
D.chassis[3] = { name = "Customized Weapons", id = 2, effect1_FRA = "<div>(Armes Personnalisées) : Les <img class='inline-img' src='img/Turret.png'> et <img class='inline-img' src='img/Cannon.png'> que vous équippez sont considérées comme votre arme principale, et sont toujours considérées comme des armes spéciales. Lorsque vous attaquez avec, vous choisissez si vous les utilisez comme arme principale (bonus de portée actif) ou spéciale.</div>", effect2_FRA = "", effect3_FRA = "", effect1_ENG = "<div>(Customized Weapons) : The <img class='inline-img' src='img/Turret.png'> and <img class='inline-img' src='img/Cannon.png'> you equip are treated as your primary weapon, and are always treated as special weapons. When you attack with them, you choose whether to use them as a primary weapon (with primary weapon range bonus active) or as a special weapon.</div>", effect2_ENG = "", effect3_ENG = "" }
D.chassis[4] = { name = "Servomotor S-Foils", id = 3, effect1_FRA = "(Servomoteurs S-Foils) Avant votre activation, vous pouvez changer de configuration :", effect2_FRA = "<img class='chargeforceimg' src='img/chargestatRed.png'> (Déplié)", effect3_FRA = "<img class='chargeforceimg' src='img/chargestat.png'> <div>(Réplié) Tant que vous effectuez une attaque principale, lancez 1 dé en moins. Ajoute  : <img class='inline-img' src='img/Br W.png'/> <br> <img class='inline-img' src='img/Fo W.png'/> <img class='inline-img' src='img/fleche.png'/> Red <img class='inline-img' src='img/Br W.png'/></div>", effect1_ENG = "(Servomotor S-Foils) :", effect2_ENG = "<img class='chargeforceimg' src='img/chargestatRed.png'> (Open) ", effect3_ENG = "<img class='chargeforceimg' src='img/chargestat.png'> <div>(Closed) While you perform a primary attack, roll 1 fewer die. Add <img class='inline-img' src='img/Br W.png'/> , <img class='inline-img' src='img/Fo W.png'/><img class='inline-img' src='img/fleche.png'/>Red<img class='inline-img' src='img/Br W.png'/></div>" }
D.chassis[5] = { name = "Pivot Wing", id = 4, effect1_FRA = "(Aile Pivot) : Après avoir exécuté une manoeuvre 0<img class='inline-img' src='img/manOp2.png'>, vous pouvez gagner 2 jetons contrainte. Dans ce cas, vous pouvez pivoter votre vaisseau de 90° ou 180°", effect2_FRA = "", effect3_FRA = "", effect1_ENG = "(Pivot Wing) : After you perform a 0<img class='inline-img' src='img/manOp2.png'>, maneuver, you may receive 2 strain tokens. If you do, you may rotate your ship 90° or 180°.", effect2_ENG = "", effect3_ENG = "" }
D.chassis[6] = { name = "Vectored Thrusters", id = 5, effect1_FRA = "<div>(Propulseurs Vectorisés) : Après avoir effectué une action, vous pouvez effectuer une action <img class='inline-img' src='img/Bo W.png'> rouge.</div>", effect2_FRA = "", effect3_FRA = "", effect1_ENG = "<div>(Vectored Thrusters) : After you perform an action, you may perform a red <img class='inline-img' src='img/Bo W.png'> action.</div>", effect2_ENG = "", effect3_ENG = "" }
D.chassis[7] = { name = "Stabilized S-Foils", id = 6, effect1_FRA = "(S-Foils Stabilisés) Avant votre activation, vous pouvez changer de configuration:", effect2_FRA = "<img class='inline-img' src='img/chargestat.png'>(Dépliés) Après avoir effectué une attaque principale, vous pouvez dépenser votre verrouillage sur le défenseur pour effectuer une attaque spéciale bonus contre ce vaisseau.", effect3_FRA = "<img class='inline-img' src='img/chargestatRed.png'><div>(Repliés) Lorsque vous attaquez, si la cible n'est pas dans votre <img class='inline-img' src='img/bulls.png'>, lancez 1 dé de moins. Ajoute <img class='inline-img' src='img/Ev W.png'> , <img class='inline-img' src='img/Br W.png'><img class='inline-img' src='img/fleche.png'><img class='inline-img' src='img/Ev W.png'>Rouge</div>", effect1_ENG = "(Stabilized S-Foils) :", effect2_ENG = "<img class='inline-img' src='img/chargestat.png'>(Opened) After you perform a primary attack, you may spend your lock on the defender to perform a bonus special attack against that ship.", effect3_ENG = "<img class='inline-img' src='img/chargestatRed.png'><div>(Closed) When you attack, if the target is not in your <img class='inline-img' src='img/bulls.png'>, roll 1 fewer die. Add <img class='inline-img' src='img/Ev W.png'> , <img class='inline-img' src='img/Br W.png'><img class='inline-img' src='img/fleche.png'>Red<img class='inline-img' src='img/Ev W.png'></div>" }
D.chassis[8] = { name = "Advanced Targetting Computer", id = 7, effect1_FRA = "<div>(Ordinateur de Visée Avancé) : Tant que vous effectuez une attaque principale contre un défenseur que vous avez vérouillé, lancez 1 dé d'attaque supplémentaire et changez 1 résultat <img class='inline-img' src='img/hit.png'> en un résultat <img class='inline-img' src='img/crit.png'></div>", effect2_FRA = "", effect3_FRA = "", effect1_ENG = "<div>(Advanced Targetting Computer) : While you perform a primary attack against a defender you have locked, roll 1 additional attack die and change 1 result <img class='inline-img' src='img/hit.png'> to a result <img class='inline-img' src='img/crit.png'>.</div>", effect2_ENG = "", effect3_ENG = "" }
D.chassis[9] = { name = "Nimble Bomber", id = 8, effect1_FRA = "<div>(Bombardier Agile) : Si vous devez utiliser un gabarit <img class='inline-img' src='img/manSt2.png'> pour larguer un engin, vous pouvez utiliser un gabarit <img class='inline-img' src='img/manBl2.png'> ou <img class='inline-img' src='img/manBr2.png'> de même vitesse à la place.</div>", effect2_FRA = "", effect3_FRA = "", effect1_ENG = "<div>(Nimble Bomber) : If you are required to use a <img class='inline-img' src='img/manSt2.png'> template to drop a device, you may use a <img class='inline-img' src='img/manBl2.png'> or <img class='inline-img' src='img/manBr2.png'> template of the same speed instead.</div>", effect2_ENG = "", effect3_ENG = "" }
D.chassis[10] = { name = "Ion Repulsorlifts", id = 9, effect1_FRA = "(Rétropropulseurs Ioniques) : Lorsque vous effectuez une manoeuvre rouge, vous pouvez prendre 3 jetons ion au lieu d'un jeton stress. Dans ce cas, vous pouvez pivoter votre vaisseau de 90° ou 180°.", effect2_FRA = "", effect3_FRA = "", effect1_ENG = "(Ion Repulsorlifts) : When you perform a red maneuver, you may take 3 ion tokens instead of 1 stress token. In this case, you may rotate your ship 90° or 180°.", effect2_ENG = "", effect3_ENG = "" }
D.chassis[11] = { name = "Autothrusters", id = 10, effect1_FRA = "<div>(Autopropulseurs) : Après avoir effectué une action, vous pouvez effectuer une action <img class='inline-img' src='img/Br W.png'> rouge ou <img class='inline-img' src='img/Bo W.png'> rouge.</div>", effect2_FRA = "", effect3_FRA = "", effect1_ENG = "<div>(Autothrusters) : After you perform an action, you may perform a red <img class='inline-img' src='img/Br W.png'> or red <img class='inline-img' src='img/Bo W.png'> action.</div>", effect2_ENG = "", effect3_ENG = "" }
D.chassis[12] = { name = "Full Throttle", id = 11, effect1_FRA = "(Plein Gaz) : Après avoir entièrement executé une manoeuvre à vitesse 3-5, vous pouvez gagner un jeton évasion.", effect2_FRA = "", effect3_FRA = "", effect1_ENG = "(Full Throttle) : After you fully execute a speed 3-5 maneuver, you may gain 1 evade token.", effect2_ENG = "", effect3_ENG = "" }
D.chassis[13] = { name = "Controlled Ailerons", id = 12, effect1_FRA = "(Ailerons Contrôlables) : Avant de révéler votre cadran, si vous n'êtes pas stressé, vous pouvez accélérer.", effect2_FRA = "", effect3_FRA = "", effect1_ENG = "(Controlled Ailerons) : Before you reveal your dial, if you are not stressed, you may boost.", effect2_ENG = "", effect3_ENG = "" }
D.chassis[14] = { name = "Rotating Cannons", id = 13, effect1_FRA = "<div>(Canons Rotatifs) : Vous pouvez pivoter votre indicateur <img class='inline-img' src='img/Tarc.png'> uniquement vers votre <img class='inline-img' src='img/Farc.png'> ou <img class='inline-img' src='img/Barc.png'>. Vous devez considérer le prérequis <img class='inline-img' src='img/Farc.png'> de vos améliorations <img class='inline-img' src='img/Cannon.png'> équipées comme étant <img class='inline-img' src='img/Tarc.png'>.</div>", effect2_FRA = "", effect3_FRA = "", effect1_ENG = "<div>(Rotating Cannons) : You can rotate your <img class='inline-img' src='img/Tarc.png'> indicator only to your <img class='inline-img' src='img/Farc.png'> or <img class='inline-img' src='img/Barc.png'>. You must treat the <img class='inline-img' src='img/Farc.png'> requirement of your equipped <img class='inline-img' src='img/Cannon.png'> upgrades as <img class='inline-img' src='img/Tarc.png'>.</div>", effect2_ENG = "", effect3_ENG = "" }
D.chassis[15] = { name = "Adaptative Ailerons", id = 14, effect1_FRA = "(Ailerons Adaptables) : Avant de révéler votre cadran, si vous n'êtes pas stressé, vous devez accélérer.", effect2_FRA = "", effect3_FRA = "", effect1_ENG = "(Adaptative Ailerons) : Before you reveal your dial, if you are not stressed, you must boost.", effect2_ENG = "", effect3_ENG = "" }
D.chassis[16] = { name = "Rigged Energy Cells", id = 15, effect1_FRA = "<img class='chargeforceimg' src='img/chargestat.png'><img class='chargeforceimg' src='img/chargestat.png'><img class='chargeforceimg' src='img/chargestat.png'><div>(Cellules Énergétiques Bidouillées) : À la fin de la phase d’activation, si vous n'êtes pas arrimé perdez 1 <img class='inline-img' src='img/charge.png'>. Vous êtes détruit si vous avez 0 <img class='inline-img' src='img/charge.png'>. Avant de retirer votre figurine, chaque vaisseau à porté 0–1 subit 1 dégât <img class='inline-img' src='img/crit.png'> </div>", effect2_FRA = "", effect3_FRA = "", effect1_ENG = "<img class='chargeforceimg' src='img/chargestat.png'><img class='chargeforceimg' src='img/chargestat.png'><img class='chargeforceimg' src='img/chargestat.png'><div>(Rigged Energy Cells) : At the end of the activation phase, if you are not docked, lose 1 <img class='inline-img' src='img/charge.png'>. You are destroyed if you have 0 <img class='inline-img' src='img/charge.png'>. Before removing your ship, each ship at range 0-1 suffers 1 <img class='inline-img' src='img/crit.png'> damage </div>", effect2_ENG = "", effect3_ENG = "" }
D.chassis[17] = { name = "Docking Ship", id = 16, effect1_FRA = "(Vaisseau-Mère) : MISE EN PLACE: vous DEVEZ avoir un vaisseau arrimé avec vous avec la capacité Copilot. Considérez les boucliers de votre vaisseau arrimé comme les vôtres.", effect2_FRA = "", effect3_FRA = "", effect1_ENG = "(Docking Ship) : SETUP: you MUST have a ship docked with you with the Copilot ability. Treat the shields of your docked ship as your own.", effect2_ENG = "", effect3_ENG = "" }
D.chassis[18] = { name = "Networked Calculations (not used, became a calculator upgrade for trade federation)", id = 17, effect1_FRA = "<div>(Calculs en Réseau) :  Lorsque vous défendez ou attaquez, you pouvez dépenser 1 jeton calcul d'un vaisseau allié à portée 0-1 pour modifier 1 résultat <img class='inline-img' src='img/Fo W.png'> en résultat <img class='inline-img' src='img/hit.png'> ou <img class='inline-img' src='img/Ev W.png'>.</div>", effect2_FRA = "", effect3_FRA = "", effect1_ENG = "<div>(Networked Calculations) : When you defend or attack, you may spend 1 calculate token from an allied ship at range 0-1 to change 1 <img class='inline-img' src='img/Fo W.png'> result to a <img class='inline-img' src='img/hit.png'> or <img class='inline-img' src='img/Ev W.png'> result.</div>", effect2_ENG = "", effect3_ENG = "" }
D.chassis[19] = { name = "Tail Laser Cannon", id = 18, effect1_FRA = "<div>(Canon Laser de Poupe) : Considérez le <img class='inline-img' src='img/Farc.png'> de vos attaques <img class='inline-img' src='img/Cannon.png'> comme <img class='inline-img' src='img/Barc.png'>.</div>", effect2_FRA = "", effect3_FRA = "", effect1_ENG = "<div>(Tail Laser Cannon) : Treat the <img class='inline-img' src='img/Farc.png'> of your <img class='inline-img' src='img/Cannon.png'> attacks as <img class='inline-img' src='img/Barc.png'>.</div>", effect2_ENG = "", effect3_ENG = "" }
D.chassis[20] = { name = "Stygium Array", id = 19, effect1_FRA = "<div>(Réseau de Stygium) : après vous être désocculté, vous pouvez effectuer une action <img class='inline-img' src='img/Ev W.png'>. Au début de la phase de dénouement, vous pouvez dépenser 1 marqueur d’évasion pour gagner 1 marqueur d’occultation.</div>", effect2_FRA = "", effect3_FRA = "", effect1_ENG = "<div>(Stygium Array) : After you decloak, you may perform a <img class='inline-img' src='img/Ev W.png'> action. At the start of the End phase, you may spend 1 evade token to gain 1 cloak token.</div>", effect2_ENG = "", effect3_ENG = "" }
D.chassis[21] = { name = "Microthrusters", id = 20, effect1_FRA = "<div>(Micropropulseurs) : Tant que vous effectuez un tonneau, vous devez utiliser le gabarit <img class='inline-img' src='img/manBl2.png'> ou <img class='inline-img' src='img/manBr2.png'> à la place du gabarit <img class='inline-img' src='img/manSt2.png'>.</div>", effect2_FRA = "", effect3_FRA = "", effect1_ENG = "<div>(Microthrusters) : While you perform a barrel roll, you must use the <img class='inline-img' src='img/manBl2.png'> or <img class='inline-img' src='img/manBr2.png'> template instead of the <img class='inline-img' src='img/manSt2.png'> template.</div>", effect2_ENG = "", effect3_ENG = "" }
D.chassis[22] = { name = "Weapon Hardpoint (not used, upgrade slot weapon hardpoint is enough", id = 21, effect1_FRA = "<div>(Emplacement d’Arme) : Vous pouvez vous équiper de 1 amélioration <img class='inline-img' src='img/Cannon.png'>, <img class='inline-img' src='img/Torpedo.png'>, ou <img class='inline-img' src='img/Missile.png'>.</div>", effect2_FRA = "", effect3_FRA = "", effect1_ENG = "<div>(Weapon Hardpoint) : You may equip 1 <img class='inline-img' src='img/Cannon.png'>, <img class='inline-img' src='img/Torpedo.png'>, or <img class='inline-img' src='img/Missile.png'> upgrade.</div>", effect2_ENG = "", effect3_ENG = "" }
D.chassis[23] = { name = "Tail Gun", id = 22, effect1_FRA = "<div>(Artillerie De Poupe) : tant que vous avez un vaisseau arrimé, vous bénéficiez d’une arme principale <img class='inline-img' src='img/Barc.png'> avec une valeur d’attaque égale à celle de l’attaque principale <img class='inline-img' src='img/Farc.png'> du vaisseau arrimé.</div>", effect2_FRA = "", effect3_FRA = "", effect1_ENG = "<div>(Tail Gun) : while you have a ship docked, you gain a primary weapon <img class='inline-img' src='img/Barc.png'> with an attack value equal to the <img class='inline-img' src='img/Farc.png'> primary attack value of the docked ship.</div>", effect2_ENG = "", effect3_ENG = "" }
D.chassis[24] = { name = "Locked and Loaded", id = 23, effect1_FRA = "<div>(Chargé et Prêt à Tirer) : Tant que vous êtes arrimé, après que votre vaisseau porteur a effectué une attaque principale <img class='inline-img' src='img/Farc.png'> ou <img class='inline-img' src='img/Tarc.png'>, il peut effectuer une attaque principale <img class='inline-img' src='img/Barc.png'>.</div>", effect2_FRA = "", effect3_FRA = "", effect1_ENG = "<div>(Locked and Loaded) : While you are docked, after your Docking Ship performs a primary <img class='inline-img' src='img/Farc.png'> or <img class='inline-img' src='img/Tarc.png'> attack, it may perform a primary <img class='inline-img' src='img/Barc.png'> attack.</div>", effect2_ENG = "", effect3_ENG = "" }
D.chassis[25] = { name = "Concordia Faceoff", id = 24, effect1_FRA = "<div>(Opposition Concordia) : Tant que vous défendez, si la portée d’attaque est 1 et que vous êtes dans le <img class='inline-img' src='img/Farc.png'> de l’attaquant, changez 1 résultat en un résultat <img class='inline-img' src='img/Ev W.png'>.</div>", effect2_FRA = "", effect3_FRA = "", effect1_ENG = "<div>(Concordia Faceoff) : While you defend, if the attack range is 1 and you are in the attacker's <img class='inline-img' src='img/Farc.png'>, change 1 result to a <img class='inline-img' src='img/Ev W.png'> result.</div>", effect2_ENG = "", effect3_ENG = "" }
D.chassis[26] = { name = "Spacetug Tractor Array", id = 25, effect1_FRA = "<div>(Remorquage par Faisceau Tractant) : ACTION : choisissez un vaisseau à portée 1 dans votre <img class='inline-img' src='img/Farc.png'>. Ce vaisseau reçoit 1 jeton tracté, ou 2 s'il se trouve dans votre <img class='inline-img' src='img/bulls.png'>.</div>", effect2_FRA = "", effect3_FRA = "", effect1_ENG = "<div>(Spacetug Tractor Array) : ACTION: choose a ship at range 1 in your <img class='inline-img' src='img/Farc.png'>. That ship gains 1 tractor token, or 2 if it is in your <img class='inline-img' src='img/bulls.png'>.</div>", effect2_ENG = "", effect3_ENG = "" }
D.chassis[27] = { name = "Dead to Rights", id = 26, effect1_FRA = "<div>(Dans Le Mille) : Tant que vous effectuez une attaque, si le défenseur est dans votre <img class='inline-img' src='img/bulls.png'>, les dés de défense ne peuvent pas être modifiés en utilisant des marqueurs verts.</div>", effect2_FRA = "", effect3_FRA = "", effect1_ENG = "<div>(Dead to Rights) : While you perform an attack, if the defender is in your <img class='inline-img' src='img/bulls.png'>, defense dice cannot be modified using green tokens.</div>", effect2_ENG = "", effect3_ENG = "" }
D.chassis[28] = { name = "Comms Shuttle", id = 27, effect1_FRA = "<div>(Navette de Communication) : Tant que vous êtes arrimé, votre vaisseau porteur gagne <img class='inline-img' src='img/Co W.png'>. Avant que votre vaisseau porteur ne s’active, il peut effectuer une action <img class='inline-img' src='img/Co W.png'>.</div>", effect2_FRA = "", effect3_FRA = "", effect1_ENG = "<div>(Comms Shuttle) : While you are docked, your Docking Ship gains <img class='inline-img' src='img/Co W.png'>. Before your Docking Ship activates, it may perform a <img class='inline-img' src='img/Co W.png'> action.</div>", effect2_ENG = "", effect3_ENG = "" }
D.chassis[29] = { name = "Integrated S-Foils", id = 28, effect1_FRA = "(S-Foils Intégrés) Avant votre activation, vous pouvez changer de configuration : ", effect2_FRA = "<img class='inline-img' src='img/chargestatRed.png'><div>(Repliés) Tant que vous effectuez une attaque principale, si le défenseur n’est pas dans votre <img class='inline-img' src='img/bulls.png'>, lancez 1 dé d’attaque en moins. Ajoute <img class='inline-img' src='img/Br W.png'> , <img class='inline-img' src='img/Fo W.png'> <img class='inline-img' src='img/fleche.png'> <img class='inline-img' src='img/Br W.png'>Rouge</div>", effect3_FRA = "<img class='inline-img' src='img/chargestat.png'>(Dépliés)", effect1_ENG = "(Integrated S-Foils) : ", effect2_ENG = "<img class='inline-img' src='img/chargestatRed.png'><div>(Closed) While you perform a primary attack, if the defender is not in your <img class='inline-img' src='img/bulls.png'>, roll 1 fewer attack die.Add <img class='inline-img' src='img/Br W.png'> , <img class='inline-img' src='img/Fo W.png'><img class='inline-img' src='img/fleche.png'>Red<img class='inline-img' src='img/Br W.png'></div>", effect3_ENG = "<img class='inline-img' src='img/chargestat.png'>(Opened)" }
D.chassis[30] = { name = "Refined Gyrostabilizers", id = 29, effect1ENG = "<div>(Refined Gyrostabilizers) : You can rotate your Turret Arc indicator only to your Front Arc or Rear Arc. After you perform an action, you may perform a red <img class='inline-img' src='img/Bo W.png'> action or red <img class='inline-img' src='img/Ra W.png'> action.</div>", effect1_FRA = "<div>(Gyrostabilisateurs Perfectionnés) : vous pouvez pivoter votre <img class='inline-img' src='img/Tarc.png'> uniquement vers votre <img class='inline-img' src='img/Farc.png'> ou <img class='inline-img' src='img/Barc.png'>. Après avoir effectué une action, vous pouvez effectuer une action rouge <img class='inline-img' src='img/Bo W.png'> ou <img class='inline-img' src='img/Ra W.png'> rouge.</div>", effect2_FRA = "", effect3_FRA = "", effect2_ENG = "", effect3_ENG = "" }
D.chassis[31] = { name = "Rotating Launcher", id = 30, effect1_FRA = "<div>(Lanceur Rotatif) : Vous pouvez pivoter votre indicateur <img class='inline-img' src='img/Tarc.png'> uniquement vers votre <img class='inline-img' src='img/Farc.png'> ou <img class='inline-img' src='img/Barc.png'>. Vous devez considérer le prérequis <img class='inline-img' src='img/Farc.png'> de vos améliorations <img class='inline-img' src='img/Missile.png'> équipées comme étant <img class='inline-img' src='img/Tarc.png'>.</div>", effect2_FRA = "", effect3_FRA = "", effect1_ENG = "<div>(Rotating Launcher) : You can rotate your <img class='inline-img' src='img/Tarc.png'> indicator only to your <img class='inline-img' src='img/Farc.png'> or <img class='inline-img' src='img/Barc.png'>. You must treat the <img class='inline-img' src='img/Farc.png'> requirement of your equipped <img class='inline-img' src='img/Missile.png'> upgrades as <img class='inline-img' src='img/Tarc.png'>.</div>", effect2_ENG = "", effect3_ENG = "" }
D.chassis[32] = { name = "Notched Stabilizers", id = 31, effect1_FRA = "(Stabilisateurs Crantés) : Tant que vous vous déplacez, ignorez les astéroïdes et les débris.", effect2_FRA = "", effect3_FRA = "", effect1_ENG = "(Notched Stabilizers) : While you move, ignore asteroids and debris.", effect2_ENG = "", effect3_ENG = "" }
D.chassis[33] = { name = "Fine-Tuned Controls", id = 32, effect1_FRA = "<div>(Commandes Réactives) : Après avoir entièrement exécuté une manœuvre, vous pouvez dépenser 1 Force pour effectuer une action <img class='inline-img' src='img/Br W.png'> ou <img class='inline-img' src='img/Bo W.png'>.</div>", effect2_FRA = "", effect3_FRA = "", effect1_ENG = "<div>(Fine-Tuned Controls) : After you fully execute a maneuver, you may spend 1 Force to perform a <img class='inline-img' src='img/Br W.png'> or <img class='inline-img' src='img/Bo W.png'> action.</div>", effect2_ENG = "", effect3_ENG = "" }
D.chassis[34] = { name = "Calibrated Laser Targeting", id = 33, effect1_FRA = "<div>(Visée Laser Calibrée) : Tant que vous effectuez une attaque principale, si le défenseur est dans votre <img class='inline-img' src='img/bulls.png'>, ajoutez 1 résultat <img class='inline-img' src='img/Fo W.png'>.</div>", effect2_FRA = "", effect3_FRA = "", effect1_ENG = "<div>(Calibrated Laser Targeting) : While you perform a primary attack, if the defender is in your <img class='inline-img' src='img/bulls.png'>, add 1 <img class='inline-img' src='img/Fo W.png'> result.</div>", effect2_ENG = "", effect3_ENG = "" }
D.chassis[35] = { name = "Grappling Struts", id = 34, effect1_FRA = "(Support d'Ancrage) : ", effect2_FRA = "<img class='inline-img' src='img/chargestatRed.png'><div>(Replié) Après un mouvement, si vous chevauchez un astéroïde/débris, ignorez ses effets et changez de configuration.</div>", effect3_FRA = "<img class='inline-img' src='img/chargestat.png'><div>(Déplié) Ignorez l'astéroïde/débris que vous chevauchez. Si vous révélez un virage, tournez de 90° dans la direction sélectionnée et ignorez la manoeuvre. Si vous révélez une manoeuvre <img class='inline-img' src='img/manSt2.png'>2, executez là puis changez de configuration. Si vous révélez toute autre manoeuvre, ne vous déplacez pas et ignorez la manoeuvre.</div>", effect1_ENG = "(Grappling Struts) : ", effect2_ENG = "<img class='inline-img' src='img/chargestatRed.png'><div>(Folded) After a move, if you overlap an asteroid/debris, ignore its effects and change configuration.</div>", effect3_ENG = "<img class='inline-img' src='img/chargestat.png'><div>(Unfolded) Ignore the asteroid/debris you overlap. If you reveal a turn, rotate 90° in the chosen direction and ignore the maneuver. If you reveal a <img class='inline-img' src='img/manSt2.png'>2 maneuver, execute it then change configuration. If you reveal any other maneuver, do not move and ignore the maneuver.</div>" }
D.chassis[36] = { name = "Pinpoint Tractor Array", id = 35, effect1_FRA = "<div>(Dispositif Tracteur De Précision) : vous ne pouvez pas faire pivoter votre <img class='inline-img' src='img/Tarc.png'> vers votre <img class='inline-img' src='img/Barc.png'>. Après avoir entièrement exécuté une manœuvre, vous pouvez gagner 1 jeton tractage pour effectuer une action <img class='inline-img' src='img/Ra W.png'>.<br>Lorsque vous vous engagez, vous pouvez choisir un vaisseau dans votre <img class='inline-img' src='img/Tarc.png'> à portée 0-1. Dans ce cas, vous pouvez lui transférer 1 jeton tractage.</div>", effect2_FRA = "", effect3_FRA = "", effect1_ENG = "<div>(Pinpoint Tractor Array) : You cannot rotate your <img class='inline-img' src='img/Tarc.png'> toward your <img class='inline-img' src='img/Barc.png'>. After you fully execute a maneuver, you may gain 1 tractor token to perform a <img class='inline-img' src='img/Ra W.png'> action.<br>When you engage, you may choose a ship in your <img class='inline-img' src='img/Tarc.png'> at range 0-1. If you do, you may transfer 1 tractor token to it.</div>", effect2_ENG = "", effect3_ENG = "" }
D.chassis[37] = { name = "Plated Hull", id = 36, effect1_FRA = "<div>(Coque Blindée) : Tant que vous défendez, si vous n’êtes pas critiquement endommagé, changez 1 résultat <img class='inline-img' src='img/crit.png'> en un résultat <img class='inline-img' src='img/hit.png'>.</div>", effect2_FRA = "", effect3_FRA = "", effect1_ENG = "<div>(Plated Hull) : While you defend, if you are not critically damaged, change 1 <img class='inline-img' src='img/crit.png'> result to a <img class='inline-img' src='img/hit.png'> result.</div>", effect2_ENG = "", effect3_ENG = "" }
D.chassis[38] = { name = "Explosion with Wings", id = 37, effect1_FRA = "<div>(Explosion en Vol) : Mise en Place : Choisissez une carte vaisseau du paquet de dégat et assignez vous la face cachée. Après avoir effectué une action <img class='inline-img' src='img/Sl W.png'>, vous pouvez exposer 1 carte de dégât pour retirer 1 jeton orange ou rouge.</div>", effect2_FRA = "", effect3_FRA = "", effect1_ENG = "<div>(Explosion with Wings) : Setup: Choose 1 ship damage card and receive it facedown. After you perform a <img class='inline-img' src='img/Sl W.png'> action, you may expose 1 damage card to remove 1 orange or red token.</div>", effect2_ENG = "", effect3_ENG = "" }
D.chassis[39] = { name = "Fine-Tuned Thrusters", id = 38, effect1_FRA = "<div>(Propulseurs Réactifs) : Après avoir entièrement exécuté une manœuvre, si vous n’êtes pas épuisé ou contraint, vous pouvez gagner 1 marqueur d’épuisement ou de contrainte pour effectuer une action <img class='inline-img' src='img/Lo W.png'> ou <img class='inline-img' src='img/Br W.png'>.</div>", effect2_FRA = "", effect3_FRA = "", effect1_ENG = "<div>(Fine-Tuned Thrusters) : After you fully execute a maneuver, if you are not exhausted or stressed, you may gain 1 exhaustion or stress token to perform a <img class='inline-img' src='img/Lo W.png'> or <img class='inline-img' src='img/Br W.png'> action.</div>", effect2_ENG = "", effect3_ENG = "" }
D.chassis[40] = { name = "Repulsorlift Stabilizers", id = 39, effect1_FRA = "(Stabilisateurs de Répulseurs) Après avoir révélé une manoeuvre <img class='inline-img' src='img/manTl2.png'> / <img class='inline-img' src='img/manBl2.png'> / <img class='inline-img' src='img/manBr2.png'> / <img class='inline-img' src='img/manTr2.png'>, vous pouvez effectuer cette manoeuvre comme un dérapage, en augmentant sa difficulté. Dans ce cas, recevez 1 jeton contrainte.<div>", effect2_FRA = "", effect3_FRA = "", effect1_ENG = "(Repulsorlift Stabilizers) : After you reveal a <img class='inline-img' src='img/manTl2.png'> / <img class='inline-img' src='img/manBl2.png'> / <img class='inline-img' src='img/manBr2.png'> / <img class='inline-img' src='img/manTr2.png'> maneuver, you may perform that maneuver as a sideslip, increasing its difficulty. If you do, receive 1 strain token.</div>", effect2_ENG = "", effect3_ENG = "" }
D.chassis[41] = { name = "Fire Convergence", id = 40, effect1_FRA = "<img class='chargeforceimg' src='img/chargestat.png'><img class='chargeforceimg' src='img/chargestat.png'><div>(Convergence Des Tirs) : Tant qu’un vaisseau allié effectue une attaque non-<img class='inline-img' src='img/Tarc.png'>, si le défenseur est dans votre <img class='inline-img' src='img/Tarc.png'>, vous pouvez dépenser 1 <img class='inline-img' src='img/charge.png'>. Dans ce cas, l’attaquant relance jusqu’à 2 dés d’attaque.</div>", effect2_FRA = "", effect3_FRA = "", effect1_ENG = "<img class='chargeforceimg' src='img/chargestat.png'><img class='chargeforceimg' src='img/chargestat.png'><div>(Fire Convergence) : While an allied ship performs a non-<img class='inline-img' src='img/Tarc.png'> attack, if the defender is in your <img class='inline-img' src='img/Tarc.png'>, you may spend 1 <img class='inline-img' src='img/charge.png'>. If you do, the attacker rerolls up to 2 attack dice.</div>", effect2_ENG = "", effect3_ENG = "" }
D.chassis[42] = { name = "Twin Ion Engines (not used anymore since the Tie Mod Slot Creation)", id = 41, effect1_FRA = "(Moteurs Ioniques Jumelés) : Vous pouvez équipper des améliorations réservées aux TIE.", effect2_FRA = "", effect3_FRA = "", effect1_ENG = "(Twin Ion Engines) : You may equip upgrades restricted to TIEs.", effect2_ENG = "", effect3_ENG = "" }
D.chassis[43] = { name = "Intuitive Controls", id = 42, effect1_FRA = "<div>(Contrôles Intuitifs) : Pendant la phase de système, vous pouvez effectuer une action <img class='inline-img' src='img/Br W.png'> violette ou <img class='inline-img' src='img/Bo W.png'> violette.</div>", effect2_FRA = "", effect3_FRA = "", effect1_ENG = "<div>(Intuitive Controls) : During the System phase, you may perform a purple <img class='inline-img' src='img/Br W.png'> or purple <img class='inline-img' src='img/Bo W.png'> action.</div>", effect2_ENG = "", effect3_ENG = "" }
D.chassis[44] = { name = "Intuitive Interface", id = 43, effect1_FRA = "<div>(Interface Intuitive) : Après avoir effectué une action ajoutée par une amélioration, recevez un jeton <img class='inline-img' src='img/Cc W.png'></div>", effect2_FRA = "", effect3_FRA = "", effect1_ENG = "<div>(Intuitive Interface) : After you perform an action added by an upgrade, gain 1 <img class='inline-img' src='img/Cc W.png'> token.</div>", effect2_ENG = "", effect3_ENG = "" }
D.chassis[45] = { name = "Enhanced Jamming Suite", id = 44, effect1_FRA = "(Brouilleurs Renforcés) : Tant que vous brouillez, vous pouvez vous choisir ou choisir un autre vaisseau allié.<br>Tant que vous défendez, si l'attaquant n'a pas de marqueur vert ou s'il y a un vaisseau brouillé dans l'arc d'attaque, vous pouvez lancer 1 dé de défense supplémentaire. ", effect2_FRA = "", effect3_FRA = "", effect1_ENG = "(Enhanced Jamming Suite) : While you jam, you may choose yourself or another allied ship.<br>While you defend, if the attacker has no green token or if there is a jammed ship in the attack arc, you may roll 1 additional defense die.", effect2_ENG = "", effect3_ENG = "" }
D.chassis[46] = { name = "Pursuit Thrusters", id = 45, effect1_FRA = "<div>(Propulseurs de Poursuite) : Pendant la Phase de Système, vous pouvez effectuer une action <img class='inline-img' src='img/Bo W.png'>.</div>", effect2_FRA = "", effect3_FRA = "", effect1_ENG = "<div>(Pursuit Thrusters) : During the System Phase, you may perform a <img class='inline-img' src='img/Bo W.png'> action.</div>", effect2_ENG = "", effect3_ENG = "" }
D.chassis[47] = { name = "Troop Bay", id = 46, effect1_FRA = "(Baie de Largage) : Un 'Super Commando' peut être arrimé avec vous.", effect2_FRA = "", effect3_FRA = "", effect1_ENG = "(Troop Bay) : A 'Super Commando' may be docked with you.", effect2_ENG = "", effect3_ENG = "" }
D.chassis[48] = { name = "Hidden Devices", id = 47, effect1_FRA = "<img class='chargeforceimg' src='img/chargestat.png'><div>(Appareils Dissimulés) : Vous pouvez dépenser cette charge comme si elle se trouvait sur une de vos cartes <img class='inline-img' src='img/Illicit.png'> équipées.</div>", effect2_FRA = "", effect3_FRA = "", effect1_ENG = "<img class='chargeforceimg' src='img/chargestat.png'><div>(Hidden Devices) : You may spend this charge as if it were on one of your equipped <img class='inline-img' src='img/Illicit.png'> cards.</div>", effect2_ENG = "", effect3_ENG = "" }
D.chassis[49] = { name = "Versatile Frame", id = 48, effect1_FRA = "<div>(Chassis Polyvalent) : Lors que vous vous engagez, si vous avez un verrouillage sur le défenseur, vous pouvez attaquez avec vos <img class='inline-img' src='img/Torpedo.png'> comme une attaque spéciale. Tant que votre manoeuvre révélée est bleue, ajoutez l'action <img class='inline-img' src='img/Bo W.png'> à votre barre d'action.</div>", effect2_FRA = "", effect3_FRA = "", effect1_ENG = "<div>(Versatile Frame) : When you engage, if you have a lock on the defender, you may attack with your <img class='inline-img' src='img/Torpedo.png'> as a special attack. When your revealed maneuver is blue, add the <img class='inline-img' src='img/Bo W.png'> to your action bar.</div>", effect2_ENG = "", effect3_ENG = "" }
D.chassis[50] = { name = "Boarding", id = 49, effect1_FRA = "(Abordage) : Vous pouvez attaquer à portée 0. Dans ce cas, le défenseur ne lance pas de dés de défense.", effect2_FRA = "", effect3_FRA = "", effect1_ENG = "(Boarding) : You may attack at range 0. If you do, the defender does not roll defense dice.", effect2_ENG = "", effect3_ENG = "" }
D.chassis[51] = { name = "Multiple Targets", id = 50, effect1_FRA = "<div>(Cibles Multiples) : Lorsque vous subissez une attaque qui touche, annulez tous les résultats et prenez 1 dégat <img class='inline-img' src='img/hit.png'>.</div>", effect2_FRA = "", effect3_FRA = "", effect1_ENG = "<div>(Multiple Targets) : When you suffer an attack that hits, cancel all results and take 1 <img class='inline-img' src='img/hit.png'> damage.</div>", effect2_ENG = "", effect3_ENG = "" }
D.chassis[52] = { name = "Hit & Run", id = 51, effect1_FRA = "(Fulgurance) : Lorsque vous attaquez ou défendez, si la vitesse de votre manoeuvre révélée est plus grande que celle du vaisseau vous attaquant ou se défendant contre vous, alors vous pouvez lancer un dé supplémentaire.", effect2_FRA = "", effect3_FRA = "", effect1_ENG = "(Hit and Run) : When you attack or defend, if the speed of your revealed maneuver is higher than the one of the ship attacking you or defending against you, you can roll one additional die.", effect2_ENG = "", effect3_ENG = "" }
D.chassis[53] = { name = "Constrictor", id = 52, effect1_FRA = "<div>(Constricteur) : Avant d'effectuer une attaque, si le vaisseau ennemi se trouve dans votre <img class='inline-img' src='img/bulls.png'>, vous pouvez recevoir un jeton épuisement pour lui assigner 2 jetons Tractage.</div>", effect2_FRA = "", effect3_FRA = "", effect1_ENG = "<div>(Constrictor) : Before you perform an attack, if the enemy ship is in your <img class='inline-img' src='img/bulls.png'>, you may gain an exhaustion token to assign it 2 Tractor tokens.</div>", effect2_ENG = "", effect3_ENG = "" }
D.chassis[54] = { name = "Optimized Launching Tubes", id = 53, effect1_FRA = "<div>(Tubes de lancement optimisés) : Vous pouvez lancer des engins au lieu de les larguer, en utilisant le même gabarit. Lorsque vous effectuez une action <img class='inline-img' src='img/Un W.png'>, vous pouvez subir un dégat <img class='inline-img' src='img/crit.png'> ou exposer une carte de dégat pour récupérer la <img class='inline-img' src='img/charge.png'> que vous venez d'utiliser</div>", effect2_FRA = "", effect3_FRA = "", effect1_ENG = "<div>(Optimized Launching Tubes) : You may launch devices instead of dropping them, using the same template. When you perform an <img class='inline-img' src='img/Un W.png'> action, you may suffer 1 <img class='inline-img' src='img/crit.png'> damage or expose a damage card to recover the <img class='inline-img' src='img/charge.png'> you've just spent.</div>", effect2_ENG = "", effect3_ENG = "" }
D.chassis[55] = { name = "Surcharge des Propulseurs", name_ENG = "Overdrive Thrusters", id = 54, effect1_FRA = "<div>(Surcharge des Propulseurs) : Lorsque vous effectuez un <img class='inline-img' src='img/Br W.png'> ou un <img class='inline-img' src='img/Bo W.png'>, vous pouvez recevoir un jeton contrainte pour utiliser le gabarit de vitesse supérieure de même direction.</div>", effect2_FRA = "", effect3_FRA = "", effect1_ENG = "<div>(Overdrive Thrusters) : When you perform a <img class='inline-img' src='img/Br W.png'> or <img class='inline-img' src='img/Bo W.png'>, you may gain a stress token to use the next higher speed template of the same direction.</div>", effect2_ENG = "", effect3_ENG = "" }
D.chassis[56] = { name = "Turbo Thrusters (not used, merged with 56 Folding Wings)", id = 55, effect1_FRA = "<img class='chargeforceimg' src='img/chargestat.png'><div>(Turbo-Propulseurs) : Après avoir exécuté une action <img class='inline-img' src='img/Sl W.png'>, vous pouvez dépenser 1 <img class='inline-img' src='img/charge.png'> ou exposer une carte de dégat pour retirer un marqueur de désarmement.</div>", effect2_FRA = "", effect3_FRA = "", effect1_ENG = "<img class='chargeforceimg' src='img/chargestat.png'><div>(Turbo Thrusters) : After you execute a <img class='inline-img' src='img/Sl W.png'> action, you can spend 1 <img class='inline-img' src='img/charge.png'> or expose a damage card to remove a disable token.</div>", effect2_ENG = "", effect3_ENG = "" }
D.chassis[57] = { name = "Folding Wings", id = 56, effect1_FRA = "(Ailes Repliantes) Avant votre activation, vous pouvez changer de configuration : ", effect2_FRA = "<img class='inline-img' src='img/chargestatRed.png'><div>(*Ailes Pliées) Vous pouvez attaquer uniquement dans votre <img class='inline-img' src='img/bulls.png'>.<br>Lorsque vous défendez, lancez 1 dé de défense en plus.</div>", effect3_FRA = "<img class='inline-img' src='img/chargestat.png'><div>(**Ailes Dépliées) Après avoir exécuté une action <img class='inline-img' src='img/Sl W.png'>, vous pouvez retourner votre <img class='inline-img' src='img/charge.png'> ou exposer une carte de dégat pour retirer un marqueur de désarmement.</div>", effect1_ENG = "(Folding Wings) : ", effect2_ENG = "<img class='inline-img' src='img/chargestatRed.png'><div>(*Folded Wings) You can only attack in your <img class='inline-img' src='img/bulls.png'>.<br>When you defend, roll 1 additional defense die.</div>", effect3_ENG = "<img class='inline-img' src='img/chargestat.png'><div>(**Unfolded Wings) After you perform a <img class='inline-img' src='img/Sl W.png'> action, you may flip your <img class='inline-img' src='img/charge.png'> or expose a damage card to remove a disarm token.</div>" }
D.chassis[58] = { name = "Night Buzzard", id = 57, effect1_FRA = "<div>(Night Buzzard) : Lorsque vous effectuez une manoeuvre, vous pouvez augmenter sa difficulté. Dans ce cas, vous pouvez récupérer 1 <img class='inline-img' src='img/charge.png'> de votre capacité de pilote.</div>", effect2_FRA = "", effect3_FRA = "", effect1_ENG = "<div>(Night Buzzard) : When you perform a maneuver, you may increase its difficulty. If you do, you may recover 1 <img class='inline-img' src='img/charge.png'> from your pilot ability.</div>", effect2_ENG = "", effect3_ENG = "" }
D.chassis[59] = { name = "Tail Laser Turret", id = 58, effect1_FRA = "(Tourelle Laser de Poupe) : Votre tourelle ne peut être tournée que vers l'arrière.", effect2_FRA = "", effect3_FRA = "", effect1_ENG = "(Tail Laser Turret) : Your turret can only be rotated to the rear.", effect2_ENG = "", effect3_ENG = "" }
D.chassis[60] = { name = "Intercept Booster", id = 59, effect1_FRA = "<img class='chargeforceimg' src='img/chargestat.png'><img class='chargeforceimg' src='img/chargestat.png'><img class='chargeforceimg' src='img/chargeminus.png'><div>(Propulseur d'Interception) : Tant que vous avez une charge active, vous pouvez effectuer les actions : <img class='inline-img' src='Sl W.png'><img class='inline-img' src='fleche.png'><img class='inline-img' src='Lo W.png'>Rouge</div>", effect2_FRA = "", effect3_FRA = "", effect1_ENG = "<img class='chargeforceimg' src='img/chargestat.png'><img class='chargeforceimg' src='img/chargestat.png'><img class='chargeforceimg' src='img/chargeminus.png'><div>(Intercept Booster) : While you have an active charge, you may perform the actions: <img class='inline-img' src='Sl W.png'><img class='inline-img' src='fleche.png'>Red<img class='inline-img' src='Lo W.png'></div>", effect2_ENG = "", effect3_ENG = "" }
D.chassis[61] = { name = "Luxury Cruiser", id = 60, effect1_FRA = "<div>(Croiseur Luxueux) :  Chaque amélioration <img class='inline-img' src='img/Crew.png'> sur ce vaisseau coûtent 1 point de logistique de moins.</div>", effect2_FRA = "", effect3_FRA = "", effect1_ENG = "<div>(Luxury Cruiser) : Each <img class='inline-img' src='img/Crew.png'> upgrade on this ship costs 1 less logistics point.</div>", effect2_ENG = "", effect3_ENG = "" }
D.chassis[62] = { name = "Shield Struts", id = 61, effect1_FRA = "(Boucliers Rétractables) Lorsque votre manoeuvre révélée est bleue, considérez que vous êtes renforcé.<br>Lorsque votre manoeuvre révélée est rouge, vous lancez 2 dés d'attaque supplémentaires lorsque vous attaquez.", effect2_FRA = "", effect3_FRA = "", effect1_ENG = "(Shield Struts) : When your revealed maneuver is blue, consider yourself as reinforced.<br>When your revealed maneuver is red, roll 2 additional attack dice when you attack.", effect2_ENG = "", effect3_ENG = "" }
D.chassis[63] = { name = "Rapid-Fire", id = 62, effect1_FRA = "(Tir à Répétition) :  Lorsque vous effectuez une attaque principale, vous ne bénéficiez pas du bonus de portée 1. Après avoir effectué une attaque principale, vous pouvez effectuer une attaque principale bonus.", effect2_FRA = "", effect3_FRA = "", effect1_ENG = "(Rapid-Fire) : When you perform a primary attack, you do not gain the range 1 bonus. After you perform a primary attack, you may perform a bonus primary attack.", effect2_ENG = "", effect3_ENG = "" }
D.chassis[64] = { name = "Maneuvering Side Thrusters", id = 63, effect1_FRA = "<div>(Propulsion Latérale) :  Lorsque vous révélez une manoeuvre <img class='inline-img' src='img/manBl2.png'><img class='inline-img' src='img/manBr2.png'> ou <img class='inline-img' src='img/manTl2.png'><img class='inline-img' src='img/manTr2.png'>, vous pouvez recevoir un jeton épuisement. Dans ce cas, vous pouvez effectuer cette maneouvre en dérapage.</div>", effect2_FRA = "", effect3_FRA = "", effect1_ENG = "<div>(Maneuvering Side Thrusters) : When you reveal a <img class='inline-img' src='img/manBl2.png'><img class='inline-img' src='img/manBr2.png'> or <img class='inline-img' src='img/manTl2.png'><img class='inline-img' src='img/manTr2.png'> maneuver, you may gain an exhaustion token. If you do, you may perform that maneuver as a sideslip.</div>", effect2_ENG = "", effect3_ENG = "" }
D.chassis[65] = { name = "Cannons Cooldown", id = 64, effect1_FRA = "<img class='chargeforceimg' src='img/chargestat.png'><img class='chargeforceimg' src='img/chargestat.png'><img class='chargeforceimg' src='img/chargeplus.png'><div>(Refroidissement des Canons) :  Lorsque vous vous engagez, si vous voulez effectuez une attaque principale, vous devez dépenser 2 <img class='inline-img' src='img/charge.png'>.</div>", effect2_FRA = "", effect3_FRA = "", effect1_ENG = "<img class='chargeforceimg' src='img/chargestat.png'><img class='chargeforceimg' src='img/chargestat.png'><img class='chargeforceimg' src='img/chargeplus.png'><div>(Cannons Cooldown) : When you engage, if you want to perform a primary attack, you must spend 2 <img class='inline-img' src='img/charge.png'>.</div>", effect2_ENG = "", effect3_ENG = "" }
D.chassis[66] = { name = "Hyperspace Jump", id = 65, effect1_FRA = "(Saut Hyperespace) :  Mise en Place : Vous et votre vaisseau-mère commencez dans la réserve. Au début de la phase de fin du tour 1, placez vous dans la portée 1 d'un bord au delà de la portée 3 d'un vaisseau adverse.", effect2_FRA = "", effect3_FRA = "", effect1_ENG = "(Hyperspace Jump) : You and your mother ship begin in reserve. At the beginning of the first end phase, place yourself within range 1 of a border, beyond range 3 of an enemy ship.", effect2_ENG = "", effect3_ENG = "" }
D.chassis[67] = { name = "Devastating Barrage", id = 66, effect1_FRA = "<div>(Tir de Barrage Dévastateur) : tant que vous effectuez une attaque <img class='inline-img' src='img/Torpedo.png'> ou <img class='inline-img' src='img/Missile.png'>, si le défenseur est dans votre <img class='inline-img' src='img/bulls.png'>, vos résultats <img class='inline-img' src='img/crit.png'> ne peuvent pas être annulés par des résultats <img class='inline-img' src='img/Ev W.png'>.</div>", effect2_FRA = "", effect3_FRA = "", effect1_ENG = "<div>(Devastating Barrage) : while you perform a <img class='inline-img' src='img/Torpedo.png'> and <img class='inline-img' src='img/Missile.png'> attack, if the defender is in your <img class='inline-img' src='img/bulls.png'>, your <img class='inline-img' src='img/crit.png'> results cannot be canceled by <img class='inline-img' src='img/Ev W.png'> results.</div>", effect2_ENG = "", effect3_ENG = "" }
D.chassis[68] = { name = "Emergency Extraction", id = 67, effect1_FRA = "<div>(Détachement d'urgence) : Vous ne pouvez pas déployer votre vaisseau arrimé tant que vous n'êtes pas détruit. Lorsque vous êtes détruit, effectuez un déploiement d'urgence (Déployez le vaisseau arrimé qui passe sa phase d'action, et reçoit un jeton désarmement).</div>", effect2_FRA = "", effect3_FRA = "", effect1_ENG = "<div>(Emergency Extraction) : You cannot undock your docked ship while you are not destroyed. When you are destroyed, perform an emergency undocking (undock the docked ship whick skips its action phase, and receive a disarm token.</div>", effect2_ENG = "", effect3_ENG = "" }
D.chassis[69] = { name = "Xg-1 Assault Configuration", id = 68, effect1_FRA = "(Configuration d'Assaut Xg-1) : Tant que vous avez exactement 1 marqueur de désarmement, vous pouvez toujours effectuer des attaques spéciales. Tant que vous effectuez une attaque spéciale alors que vous êtes désarmé, lancez 3 dés d’attaque au maximum.", effect2_FRA = "", effect3_FRA = "", effect1_ENG = "(Xg-1 Assault Configuration) : While you have exactly 1 disarm token, you can still perform special attacks. While you perform a special attack while disarmed, roll a maximum of 3 attack dice.", effect2_ENG = "", effect3_ENG = "" }
D.chassis[70] = { name = "Logistic Supply", id = 69, effect1_FRA = "(Ravitaillement) : Vous êtes un engin distant. Vous ne pouvez pas être relocalisé sauf si le contraire est spécifié. En phase de mise en place, vous pouvez être placé sur toute la carte sans aucune restriction. Vous ne pouvez être la cible d'une attaque que si vous défendez à portée 1, ou si défendez à portée 2 et que l'attaquant possède un verrouillage sur vous.", effect2_FRA = "", effect3_FRA = "", effect1_ENG = "(Supply) : You are a remote. You can't be relocated except if the contrary is specified. During setup, you may be placed anywhere on the field without restrictions. You can only be targeted by range 1 attacks, or range 2 attacks if the attacker has a lock on you.", effect2_ENG = "", effect3_ENG = "" }
D.chassis[71] = { name = "Racing Ship", id = 70, effect1_FRA = "(Vaisseau de Course) : Après avoir effectué une action, vous pouvez effectuer une action <img class='inline-img' src='img/Sl W.png'> puis recevez un jeton contrainte ou épuisement. Après avoir effectué une action <img class='inline-img' src='img/Sl W.png'> vous pouvez recevoir un jeton contrainte ou épuisement pour retirer le jeton désarmement.", effect2_FRA = "", effect3_FRA = "", effect1_ENG = "(Racing Ship) : After you perform an action, you may perform a <img class='inline-img' src='img/Sl W.png'> action, then receive a strain or deplete token. After you perform a <img class='inline-img' src='img/Sl W.png'> action, you may receive a strain or deplete token to remove the disarm token.", effect2_ENG = "", effect3_ENG = "" }

